/**
 * Verification test for Phase 1 completion criteria
 * Tests that all required components are properly implemented
 */

import { beforeEach, describe, expect, it, vi } from "vitest"

import { conductResearch } from "@/app/actions/researchAgentOrchestrator"
import type {
  ResearchStage,
  ResearchUpdate,
} from "@/app/actions/researchAgentOrchestrator"

// Unmock axios for integration tests that need real HTTP requests
vi.unmock("axios")

// Mock the BAML client to avoid real API calls
vi.mock("@/baml_client", () => import("@/__mocks__/baml_client"))

describe("Research Orchestrator - Phase 1 Verification", () => {
  beforeEach(() => {
    vi.clearAllMocks()
  })

  it("should have all required types defined", () => {
    // Verify ResearchStage enum covers all required stages
    const requiredStages: ResearchStage[] = [
      "IDLE",
      "INITIALIZING",
      "GENERATING_QUERIES",
      "FETCHING_DOCUMENTS",
      "ANALYZING_DOCUMENTS",
      "SYNTHESIZING_FINDINGS",
      "ASSESSING_RESEARCH",
      "GENERATING_REPORT",
      "ITERATION_PAUSED",
      "HUMAN_REVIEW_REQUESTED",
      "COMPLETED",
      "ERROR",
    ]

    // TypeScript compilation will fail if these types don't exist
    expect(requiredStages.length).toBe(12)
  })

  it("should export conductResearch Server Action", () => {
    expect(typeof conductResearch).toBe("function")
  })

  it("should have proper function signature", async () => {
    const legalQuestion = "Test question"
    const result = conductResearch(legalQuestion)

    // Should return a Promise<ReadableStream>
    expect(result).toBeInstanceOf(Promise)

    const stream = await result
    expect(stream).toBeInstanceOf(ReadableStream)

    // Clean up the stream
    const reader = stream.getReader()
    reader.releaseLock()
  })

  it("should implement proper ResearchUpdate structure", () => {
    // This test ensures TypeScript validates the ResearchUpdate interface
    const validUpdate: ResearchUpdate = {
      type: "STATUS_CHANGE",
      stage: "INITIALIZING",
      message: "Test message",
    }

    expect(validUpdate.type).toBe("STATUS_CHANGE")
    expect(validUpdate.stage).toBe("INITIALIZING")
  })

  it("should handle basic stream lifecycle (with timeout)", async () => {
    const legalQuestion = "What are the legal implications of contract breach?"
    const stream = await conductResearch(legalQuestion)

    const updates: ResearchUpdate[] = []
    const reader = stream.getReader()
    const decoder = new TextDecoder()

    // Set a timeout to prevent hanging
    const timeout = new Promise((_, reject) =>
      setTimeout(() => reject(new Error("Test timeout")), 30000)
    )

    try {
      await Promise.race([
        (async () => {
          let chunks = 0
          while (chunks < 10) {
            // Read up to 10 chunks to avoid infinite loop
            const { done, value } = await reader.read()
            if (done) {
              break
            }

            const chunk = decoder.decode(value)
            const lines = chunk.split("\n").filter(line => line.trim())

            for (const line of lines) {
              try {
                const update = JSON.parse(line) as ResearchUpdate
                updates.push(update)
              } catch {
                console.warn("Failed to parse JSON line:", line)
              }
            }
            chunks++
          }
        })(),
        timeout,
      ])
    } catch (error) {
      if (error instanceof Error && error.message !== "Test timeout") {
        console.warn(
          "Stream processing error (expected for BAML without API keys):",
          error.message
        )
      }
    } finally {
      reader.releaseLock()
    }

    // Verify we got at least the initial updates
    expect(updates.length).toBeGreaterThan(0)

    // Should start with INITIALIZING
    if (updates.length > 0) {
      expect(updates[0]?.stage).toBe("INITIALIZING")
      expect(updates[0]?.type).toBe("STATUS_CHANGE")
    }
  }, 35000)
})



/**
 * Integration test for the research orchestrator with real API calls
 * This test requires actual API keys and will be skipped in CI unless keys are available
 */

import { beforeAll, beforeEach, expect, vi } from "vitest"

import { conductResearch } from "@/app/actions/researchAgentOrchestrator"
import type { ResearchUpdate } from "@/app/actions/researchAgentOrchestrator"
import type { FinalLegalReport } from "@/baml_client/types"

import {
  API_KEYS,
  describeWithApiKeys,
  itWithApiKeys,
  logApiKeyStatus,
} from "../../utils/api-test-helpers"

// Unmock axios for integration tests that need real HTTP requests
vi.unmock("axios")

// This entire test suite requires both Google AI and Exa Search APIs
describeWithApiKeys(
  "Research Orchestrator - Real API Integration",
  [...API_KEYS.GOOGLE_AI, ...API_KEYS.EXA_SEARCH],
  () => {
    beforeAll(() => {
      // Log API key status when debugging
      if (process.env.DEBUG_API_TESTS === "true") {
        logApiKeyStatus([...API_KEYS.GOOGLE_AI, ...API_KEYS.EXA_SEARCH])
      }
    })

    beforeEach(() => {
      // Clear any mocks that might interfere with real API calls
      vi.clearAllMocks()
    })

    itWithApiKeys(
      "should complete full research pipeline with real APIs",
      [...API_KEYS.GOOGLE_AI, ...API_KEYS.EXA_SEARCH],
      async () => {
        const legalQuestion =
          "What are the basic requirements for forming a valid contract in California?"

        // Use real APIs - no mocking
        const stream = await conductResearch(legalQuestion)

        const updates: ResearchUpdate[] = []
        const reader = stream.getReader()
        const decoder = new TextDecoder()

        try {
          let completedFound = false
          const maxTimeoutMs = 300000 // 5 minutes for full real API test
          const startTime = Date.now()

          while (!completedFound) {
            // Check for overall timeout
            if (Date.now() - startTime > maxTimeoutMs) {
              throw new Error(`Real API test timeout after ${maxTimeoutMs}ms`)
            }

            const { done, value } = await reader.read()
            if (done) {
              break
            }

            const chunk = decoder.decode(value)
            const lines = chunk.split("\n").filter(line => line.trim())

            for (const line of lines) {
              try {
                const update = JSON.parse(line) as ResearchUpdate
                updates.push(update)

                // Log progress when debugging
                if (process.env.DEBUG_API_TESTS === "true") {
                  console.log(
                    `Update: ${update.stage} - ${update.type}`,
                    update.message
                  )
                }

                // Consider multiple valid completion states
                if (
                  update.stage === "COMPLETED" ||
                  update.stage === "HUMAN_REVIEW_REQUESTED" ||
                  update.stage === "ITERATION_PAUSED" ||
                  update.type === "ERROR"
                ) {
                  completedFound = true
                  break
                }
              } catch {
                // Ignore JSON parsing errors
              }
            }

            // Add small delay to prevent tight loop
            if (!completedFound) {
              await new Promise(resolve => setTimeout(resolve, 100))
            }
          }
        } finally {
          reader.releaseLock()
        }

        // Verify we got some pipeline activity
        expect(updates.length).toBeGreaterThan(0)

        // Check for required stages or error handling
        const stages = updates.map(u => u.stage)
        const types = updates.map(u => u.type)

        // Either we completed successfully or handled errors gracefully
        const hasInitialization = stages.includes("INITIALIZING")
        const hasCompletion = stages.includes("COMPLETED")
        const hasHumanReview = stages.includes("HUMAN_REVIEW_REQUESTED")
        const hasIterationPaused = stages.includes("ITERATION_PAUSED")
        const hasError = types.includes("ERROR")

        expect(hasInitialization).toBe(true)

        if (hasError) {
          // If there were errors, verify they were handled gracefully
          const errorUpdates = updates.filter(u => u.type === "ERROR")
          expect(errorUpdates.length).toBeGreaterThan(0)
          expect(errorUpdates[0]?.message).toBeDefined()
        } else {
          // If no errors, verify we reached a valid end state
          const hasValidEndState =
            hasCompletion || hasHumanReview || hasIterationPaused
          expect(hasValidEndState).toBe(true)

          // Verify we got actual data, not just mocked responses
          const dataUpdates = updates.filter(u => u.type === "DATA")
          if (dataUpdates.length > 0) {
            // Check that we have meaningful content (not just mock data)
            const hasRealContent = dataUpdates.some(
              update =>
                update.data &&
                typeof update.data === "object" &&
                JSON.stringify(update.data).toLowerCase().includes("california")
            )
            expect(hasRealContent).toBe(true)
          }
        }
      },
      {
        skipInCI: true, // Skip in CI unless API keys are explicitly provided
        timeout: 300000, // 5 minutes for full real API test
      }
    )

    // Helper functions to reduce cognitive complexity

    interface StreamProcessingResult {
      hasCompleted: boolean
      hasError: boolean
    }

    async function processResearchStream(
      reader: ReadableStreamDefaultReader,
      updates: ResearchUpdate[]
    ): Promise {
      try {
        const startTime = Date.now()
        const maxTimeoutMs = 240000 // 4 minutes
        let hasCompleted = false
        let hasError = false

        while (!hasCompleted && !hasError) {
          if (Date.now() - startTime > maxTimeoutMs) {
            console.warn(`Test timeout after ${maxTimeoutMs}ms`)
            break
          }

          const streamResult = await readStreamChunk(reader)
          if (streamResult.done) {
            break
          }

          const parsedUpdates = parseStreamChunk(streamResult.value)
          updates.push(...parsedUpdates)

          const status = checkCompletionStatus(parsedUpdates)
          hasCompleted = status.completed
          hasError = status.error

          if (!hasCompleted && !hasError) {
            await new Promise(resolve => setTimeout(resolve, 100))
          }
        }

        return { hasCompleted, hasError }
      } finally {
        reader.releaseLock()
      }
    }

    async function readStreamChunk(
      reader: ReadableStreamDefaultReader
    ) {
      const { done, value } = await reader.read()
      return { done, value }
    }

    function parseStreamChunk(value: Uint8Array | undefined): ResearchUpdate[] {
      if (!value) {
        return []
      }
      const chunk = new TextDecoder().decode(value)
      const lines = chunk.split("\n").filter(line => line.trim())
      const updates: ResearchUpdate[] = []

      for (const line of lines) {
        try {
          const update = JSON.parse(line) as ResearchUpdate
          updates.push(update)
        } catch {
          // Ignore parsing errors
        }
      }

      return updates
    }

    function checkCompletionStatus(updates: ResearchUpdate[]): {
      completed: boolean
      error: boolean
    } {
      const hasCompleted = updates.some(
        update =>
          update.stage === "COMPLETED" ||
          update.stage === "HUMAN_REVIEW_REQUESTED" ||
          update.stage === "ITERATION_PAUSED"
      )

      const hasError = updates.some(update => update.type === "ERROR")

      return { completed: hasCompleted, error: hasError }
    }

    function extractFinalReport(
      updates: ResearchUpdate[]
    ): FinalLegalReport | null {
      for (const update of updates) {
        if (update.type === "DATA" && update.data) {
          if (
            typeof update.data === "object" &&
            update.data !== null &&
            ("executive_summary" in update.data ||
              "executiveSummary" in update.data)
          ) {
            return update.data as FinalLegalReport
          }
        }
      }
      return null
    }

    function validateTestResults(
      updates: ResearchUpdate[],
      hasCompleted: boolean,
      hasError: boolean,
      finalReport: FinalLegalReport | null
    ): void {
      expect(updates.length).toBeGreaterThan(0)

      if (hasError) {
        validateErrorHandling(updates)
      } else if (hasCompleted && finalReport) {
        validateSuccessfulCompletion(finalReport)
      } else {
        validateProgressMade(updates)
      }
    }

    function validateErrorHandling(updates: ResearchUpdate[]): void {
      const errorUpdate = updates.find(u => u.type === "ERROR")
      expect(errorUpdate?.message).toBeDefined()
      console.log("Test handled error gracefully:", errorUpdate?.message)
    }

    function validateSuccessfulCompletion(finalReport: FinalLegalReport): void {
      expect(finalReport.report_title).toBeDefined()
      expect(finalReport.executive_summary).toBeDefined()
      expect(finalReport.sections).toBeDefined()
      expect(Array.isArray(finalReport.sections)).toBe(true)
      expect(finalReport.conclusion).toBeDefined()

      const reportText = JSON.stringify(finalReport).toLowerCase()
      const isRelevant =
        reportText.includes("statute") ||
        reportText.includes("limitation") ||
        reportText.includes("new york") ||
        reportText.includes("personal injury")

      expect(isRelevant).toBe(true)

      console.log("✅ Structured legal analysis completed successfully")
      console.log(`Report title: ${finalReport.report_title}`)
      console.log(`Number of sections: ${finalReport.sections.length}`)
    }

    function validateProgressMade(updates: ResearchUpdate[]): void {
      const stages = updates.map(u => u.stage)
      expect(stages).toContain("INITIALIZING")

      const hasDataUpdates = updates.some(u => u.type === "DATA")
      if (hasDataUpdates) {
        console.log("Test made progress with data updates but didn't complete")
      } else {
        console.log("Test started but didn't progress to data generation")
      }
    }

    itWithApiKeys(
      "should handle API errors gracefully",
      [...API_KEYS.GOOGLE_AI, ...API_KEYS.EXA_SEARCH],
      async () => {
        // Test with an empty question - this should still complete gracefully
        const stream = await conductResearch("")

        const updates: ResearchUpdate[] = []
        const reader = stream.getReader()

        try {
          const startTime = Date.now()
          const maxTimeoutMs = 180000 // 3 minutes for error handling test
          let completedFound = false

          while (!completedFound) {
            // Check for timeout
            if (Date.now() - startTime > maxTimeoutMs) {
              console.warn(
                `Error handling test timeout after ${maxTimeoutMs}ms - got ${updates.length} updates`
              )
              console.warn(
                "Last few updates:",
                updates.slice(-3).map(u => `${u.stage}:${u.type}:${u.message}`)
              )
              break
            }

            const { done, value } = await reader.read()
            if (done) {
              break
            }

            const chunk = new TextDecoder().decode(value)
            const lines = chunk.split("\n").filter(line => line.trim())

            for (const line of lines) {
              try {
                const update = JSON.parse(line) as ResearchUpdate
                updates.push(update)

                // Log progress for debugging
                if (process.env.DEBUG_API_TESTS === "true") {
                  console.log(
                    `Error test update: ${update.stage} - ${update.type}: ${update.message}`
                  )
                }

                if (
                  update.stage === "COMPLETED" ||
                  update.stage === "HUMAN_REVIEW_REQUESTED" ||
                  update.stage === "ITERATION_PAUSED" ||
                  update.type === "ERROR"
                ) {
                  completedFound = true
                  break
                }
              } catch {
                // Ignore parsing errors
              }
            }

            // Add small delay to prevent tight loop
            if (!completedFound) {
              await new Promise(resolve => setTimeout(resolve, 100))
            }
          }
        } finally {
          reader.releaseLock()
        }

        // Should either complete successfully, request review, pause, or fail gracefully
        const hasCompletion = updates.some(u => u.stage === "COMPLETED")
        const hasHumanReview = updates.some(
          u => u.stage === "HUMAN_REVIEW_REQUESTED"
        )
        const hasIterationPaused = updates.some(
          u => u.stage === "ITERATION_PAUSED"
        )
        const hasError = updates.some(u => u.type === "ERROR")

        // Verify we got some meaningful response regardless of outcome
        expect(updates.length).toBeGreaterThan(0)
        expect(
          hasCompletion || hasHumanReview || hasIterationPaused || hasError
        ).toBe(true)

        // Log final outcome for debugging
        if (hasError) {
          const errorUpdate = updates.find(u => u.type === "ERROR")
          console.log("Test completed with error:", errorUpdate?.message)
        } else if (hasCompletion) {
          console.log("Test completed successfully")
        } else if (hasHumanReview || hasIterationPaused) {
          console.log("Test completed with review/pause request")
        }
      },
      {
        skipInCI: true,
        timeout: 180000, // 3 minutes for error handling test - allows normal completion
      }
    )

    itWithApiKeys(
      "should produce structured legal analysis",
      [...API_KEYS.GOOGLE_AI, ...API_KEYS.EXA_SEARCH],
      async () => {
        const legalQuestion =
          "What is the statute of limitations for personal injury claims in New York?"

        const stream = await conductResearch(legalQuestion)
        const reader = stream.getReader()

        const updates: ResearchUpdate[] = []
        let finalReport: FinalLegalReport | null = null

        const result = await processResearchStream(reader, updates)
        const { hasCompleted, hasError } = result

        // Extract final report from updates if available
        finalReport = extractFinalReport(updates)

        validateTestResults(updates, hasCompleted, hasError, finalReport)
      },
      {
        skipInCI: true,
        timeout: 240000, // 4 minutes for structured analysis test
      }
    )
  }
)



import { act, renderHook, waitFor } from "@testing-library/react"
import { Provider, createStore } from "jotai"
import { createElement } from "react"
import type { ReactNode } from "react"
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest"

import { conductResearch } from "@/app/actions/researchAgentOrchestrator"
import { useResearchAgent } from "@/lib/hooks/useResearchAgent"
import {
  autoModeStateAtom,
  researchSessionAtom,
} from "@/lib/state/researchAtoms"

// Mock the server action
vi.mock("@/app/actions/researchAgentOrchestrator", () => ({
  conductResearch: vi.fn(),
}))

const mockConductResearch = vi.mocked(conductResearch)

describe("useResearchAgent Hook - Auto Mode", () => {
  let store: ReturnType

  const JotaiProvider = ({ children }: { children: ReactNode }) =>
    createElement(Provider, { store }, children)

  beforeEach(() => {
    store = createStore()
    mockConductResearch.mockClear()
  })

  afterEach(() => {
    mockConductResearch.mockClear()
  })

  describe("Auto Mode Toggle", () => {
    it("should toggle auto mode on and off", async () => {
      const { result } = renderHook(() => useResearchAgent(), {
        wrapper: JotaiProvider,
      })

      // Initially auto mode should be disabled
      expect(result.current.autoModeEnabled).toBe(false)

      // Toggle auto mode on
      act(() => {
        result.current.toggleAutoMode()
      })

      await waitFor(() => {
        expect(result.current.autoModeEnabled).toBe(true)
      })

      // Toggle auto mode off
      act(() => {
        result.current.toggleAutoMode()
      })

      await waitFor(() => {
        expect(result.current.autoModeEnabled).toBe(false)
      })
    })

    it("should preserve auto mode state across hook re-renders", async () => {
      const { result, rerender } = renderHook(() => useResearchAgent(), {
        wrapper: JotaiProvider,
      })

      // Enable auto mode
      act(() => {
        result.current.toggleAutoMode()
      })

      await waitFor(() => {
        expect(result.current.autoModeEnabled).toBe(true)
      })

      // Re-render the hook
      rerender()

      // Auto mode should still be enabled
      expect(result.current.autoModeEnabled).toBe(true)
    })
  })

  describe("Auto Mode Configuration", () => {
    it("should pass auto mode config to conductResearch when starting research", async () => {
      // Mock a successful stream
      const mockStream = new ReadableStream({
        start(controller) {
          const update = {
            type: "STATUS_CHANGE",
            stage: "INITIALIZING",
            message: "Starting research...",
          }
          controller.enqueue(
            new TextEncoder().encode(`${JSON.stringify(update)}\n`)
          )
          controller.close()
        },
      })

      mockConductResearch.mockResolvedValue(mockStream)

      const { result } = renderHook(() => useResearchAgent(), {
        wrapper: JotaiProvider,
      })

      // Enable auto mode
      act(() => {
        result.current.toggleAutoMode()
      })

      await waitFor(() => {
        expect(result.current.autoModeEnabled).toBe(true)
      })

      // Start research
      await act(async () => {
        await result.current.startResearch("Test legal question")
      })

      // Verify conductResearch was called with auto mode config
      expect(mockConductResearch).toHaveBeenCalledWith(
        "Test legal question",
        expect.objectContaining({
          isEnabled: true,
          maxIterations: 3,
          currentIteration: 0,
        })
      )
    })

    it("should pass disabled auto mode config when auto mode is off", async () => {
      // Mock a successful stream
      const mockStream = new ReadableStream({
        start(controller) {
          const update = {
            type: "STATUS_CHANGE",
            stage: "INITIALIZING",
            message: "Starting research...",
          }
          controller.enqueue(
            new TextEncoder().encode(`${JSON.stringify(update)}\n`)
          )
          controller.close()
        },
      })

      mockConductResearch.mockResolvedValue(mockStream)

      const { result } = renderHook(() => useResearchAgent(), {
        wrapper: JotaiProvider,
      })

      // Auto mode should be disabled by default
      expect(result.current.autoModeEnabled).toBe(false)

      // Start research
      await act(async () => {
        await result.current.startResearch("Test legal question")
      })

      // Verify conductResearch was called with auto mode disabled
      expect(mockConductResearch).toHaveBeenCalledWith(
        "Test legal question",
        expect.objectContaining({
          isEnabled: false,
          maxIterations: 3,
          currentIteration: 0,
        })
      )
    })
  })

  describe("Research Session Management", () => {
    it("should generate a unique session ID when starting research", async () => {
      // Mock a successful stream
      const mockStream = new ReadableStream({
        start(controller) {
          controller.close()
        },
      })

      mockConductResearch.mockResolvedValue(mockStream)

      const { result } = renderHook(() => useResearchAgent(), {
        wrapper: JotaiProvider,
      })

      // Start research
      await act(async () => {
        await result.current.startResearch("Test legal question")
      })

      // Check that a session ID was generated
      const sessionState = store.get(researchSessionAtom)
      expect(sessionState.sessionId).toBeTruthy()
      expect(sessionState.sessionId).toMatch(/^research_\d+_[a-z0-9]+$/)
    })

    it("should initialize auto mode state with legal question", async () => {
      // Mock a successful stream
      const mockStream = new ReadableStream({
        start(controller) {
          controller.close()
        },
      })

      mockConductResearch.mockResolvedValue(mockStream)

      const { result } = renderHook(() => useResearchAgent(), {
        wrapper: JotaiProvider,
      })

      const testQuestion = "What are the patent requirements for AI inventions?"

      // Start research
      await act(async () => {
        await result.current.startResearch(testQuestion)
      })

      // Check that auto mode state was updated
      const autoModeState = store.get(autoModeStateAtom)
      expect(autoModeState.originalQuestion).toBe(testQuestion)
      expect(autoModeState.currentIteration).toBe(0)
    })
  })

  describe("Accumulative Data Handling", () => {
    it("should accumulate search queries with timestamps", async () => {
      const mockStream = new ReadableStream({
        start(controller) {
          const update = {
            type: "DATA",
            stage: "GENERATING_QUERIES",
            data: {
              queries: [
                {
                  query_string: "patent requirements AI",
                  expected_information_summary: "Patent eligibility for AI",
                },
              ],
            },
          }
          controller.enqueue(
            new TextEncoder().encode(`${JSON.stringify(update)}\n`)
          )
          controller.close()
        },
      })

      mockConductResearch.mockResolvedValue(mockStream)

      const { result } = renderHook(() => useResearchAgent(), {
        wrapper: JotaiProvider,
      })

      // Start research
      await act(async () => {
        await result.current.startResearch("Test legal question")
      })

      // Wait for the stream to be processed
      await waitFor(() => {
        const sessionState = store.get(researchSessionAtom)
        expect(sessionState.accumulatedQueries).toHaveLength(1)
        expect(sessionState.accumulatedQueries[0]).toMatchObject({
          query_string: "patent requirements AI",
          expected_information_summary: "Patent eligibility for AI",
          timestamp: expect.any(String),
        })
      })
    })

    it("should accumulate analyzed documents with timestamps", async () => {
      const mockStream = new ReadableStream({
        start(controller) {
          const update = {
            type: "DATA",
            stage: "ANALYZING_DOCUMENTS",
            data: {
              docId: "doc-123",
              title: "Test Document",
              relevanceScore: 8,
              summarySnippet: "Test summary",
            },
          }
          controller.enqueue(
            new TextEncoder().encode(`${JSON.stringify(update)}\n`)
          )
          controller.close()
        },
      })

      mockConductResearch.mockResolvedValue(mockStream)

      const { result } = renderHook(() => useResearchAgent(), {
        wrapper: JotaiProvider,
      })

      // Start research
      await act(async () => {
        await result.current.startResearch("Test legal question")
      })

      // Wait for the stream to be processed
      await waitFor(() => {
        const sessionState = store.get(researchSessionAtom)
        expect(sessionState.accumulatedDocuments).toHaveLength(1)
        expect(sessionState.accumulatedDocuments[0]).toMatchObject({
          docId: "doc-123",
          title: "Test Document",
          relevanceScore: 8,
          summarySnippet: "Test summary",
          timestamp: expect.any(String),
        })
      })
    })

    it("should accumulate synthesis topics with timestamps", async () => {
      const mockStream = new ReadableStream({
        start(controller) {
          const update = {
            type: "DATA",
            stage: "SYNTHESIZING_FINDINGS",
            data: {
              topics: [
                {
                  title: "Patent Eligibility",
                  synthesisSnippet: "AI inventions must meet...",
                  confidence: 85,
                  docIds: ["doc-123"],
                },
              ],
            },
          }
          controller.enqueue(
            new TextEncoder().encode(`${JSON.stringify(update)}\n`)
          )
          controller.close()
        },
      })

      mockConductResearch.mockResolvedValue(mockStream)

      const { result } = renderHook(() => useResearchAgent(), {
        wrapper: JotaiProvider,
      })

      // Start research
      await act(async () => {
        await result.current.startResearch("Test legal question")
      })

      // Wait for the stream to be processed
      await waitFor(() => {
        const sessionState = store.get(researchSessionAtom)
        expect(sessionState.accumulatedTopics).toHaveLength(1)
        expect(sessionState.accumulatedTopics[0]).toMatchObject({
          title: "Patent Eligibility",
          synthesisSnippet: "AI inventions must meet...",
          confidence: 85,
          docIds: ["doc-123"],
          timestamp: expect.any(String),
        })
      })
    })
  })

  describe("Pause and Resume Functionality", () => {
    it("should allow pausing research", async () => {
      const { result } = renderHook(() => useResearchAgent(), {
        wrapper: JotaiProvider,
      })

      // Mock a stream that processes quickly
      const mockStream = new ReadableStream({
        start(controller) {
          const update = {
            type: "STATUS_CHANGE",
            stage: "ANALYZING_DOCUMENTS",
            message: "Analyzing documents...",
          }
          controller.enqueue(
            new TextEncoder().encode(`${JSON.stringify(update)}\n`)
          )
          controller.close()
        },
      })

      mockConductResearch.mockResolvedValue(mockStream)

      // Start research
      await act(async () => {
        await result.current.startResearch("Test legal question")
      })

      // Immediately pause research (before stream closes)
      act(() => {
        result.current.pauseResearch()
      })

      // Check that pause method was called successfully
      expect(typeof result.current.pauseResearch).toBe("function")
    })

    it("should clear pause state when aborting research", async () => {
      const { result } = renderHook(() => useResearchAgent(), {
        wrapper: JotaiProvider,
      })

      const mockStream = new ReadableStream({
        start(controller) {
          const update = {
            type: "STATUS_CHANGE",
            stage: "ANALYZING_DOCUMENTS",
            message: "Analyzing documents...",
          }
          controller.enqueue(
            new TextEncoder().encode(`${JSON.stringify(update)}\n`)
          )
          controller.close()
        },
      })

      mockConductResearch.mockResolvedValue(mockStream)

      // Start research
      await act(async () => {
        await result.current.startResearch("Test legal question")
      })

      // Pause research
      act(() => {
        result.current.pauseResearch()
      })

      // Abort research
      act(() => {
        result.current.abortResearch()
      })

      // Check that abort method was called successfully
      expect(typeof result.current.abortResearch).toBe("function")
    })
  })

  describe("Error Handling", () => {
    it("should handle auto mode configuration errors gracefully", async () => {
      const { result } = renderHook(() => useResearchAgent(), {
        wrapper: JotaiProvider,
      })

      mockConductResearch.mockRejectedValue(new Error("Auto mode error"))

      // Enable auto mode
      act(() => {
        result.current.toggleAutoMode()
      })

      // Start research
      await act(async () => {
        await result.current.startResearch("Test legal question")
      })

      // Check error state
      await waitFor(() => {
        expect(result.current.error).toBeTruthy()
        expect(result.current.isLoading).toBe(false)
      })
    })

    it("should reset auto mode state when resetting research", async () => {
      const { result } = renderHook(() => useResearchAgent(), {
        wrapper: JotaiProvider,
      })

      // Enable auto mode and set some state
      act(() => {
        result.current.toggleAutoMode()
      })

      // Simulate setting up research state
      const autoModeState = store.get(autoModeStateAtom)
      store.set(autoModeStateAtom, {
        ...autoModeState,
        currentIteration: 2,
        originalQuestion: "Test question",
      })

      // Mock a successful stream to trigger state reset
      const mockStream = new ReadableStream({
        start(controller) {
          controller.close()
        },
      })

      mockConductResearch.mockResolvedValue(mockStream)

      // Start new research (which should reset state)
      await act(async () => {
        await result.current.startResearch("New test question")
      })

      // Check that auto mode state was reset but enabled flag preserved
      const newAutoModeState = store.get(autoModeStateAtom)
      expect(newAutoModeState.isEnabled).toBe(true) // Preserved
      expect(newAutoModeState.currentIteration).toBe(0) // Reset
      expect(newAutoModeState.originalQuestion).toBe("New test question") // Updated
    })
  })
})



import { act, renderHook, waitFor } from "@testing-library/react"
import { Provider, createStore } from "jotai"
import { createElement } from "react"
import type { ReactNode } from "react"
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest"

import { conductResearch } from "@/app/actions/researchAgentOrchestrator"
import type { ResearchUpdate } from "@/app/actions/researchAgentOrchestrator"
import { useResearchAgent } from "@/lib/hooks/useResearchAgent"
import {
  analyzedDocsSummaryAtom,
  researchStatusAtom,
} from "@/lib/state/researchAtoms"
import type {
  ClientAnalysisReasoning,
  ClientAnalyzedDoc,
  ClientLegalEntity,
} from "@/lib/state/researchAtoms"

// Mock the server action
vi.mock("@/app/actions/researchAgentOrchestrator", () => ({
  conductResearch: vi.fn(),
}))

const mockedConductResearch = vi.mocked(conductResearch)

describe("useResearchAgent Hook - Extended Data Handling", () => {
  let store: ReturnType

  const JotaiProvider = ({ children }: { children: ReactNode }) =>
    createElement(Provider, { store }, children)

  beforeEach(() => {
    store = createStore()
    vi.clearAllMocks()
  })

  afterEach(() => {
    vi.clearAllTimers()
  })

  const createMockStream = (updates: ResearchUpdate[]) => {
    const encoder = new TextEncoder()
    const stream = new ReadableStream({
      start(controller) {
        for (const update of updates) {
          const data = encoder.encode(`${JSON.stringify(update)}\n`)
          controller.enqueue(data)
        }
        controller.close()
      },
    })
    return stream
  }

  const mockExtendedAnalysisData: ClientAnalyzedDoc = {
    docId: "doc-extended-1",
    title: "Smith v. Jones, 345 F.Supp. 2d 123 (N.D. Cal. 2023)",
    url: "https://example.com/smith-v-jones",
    relevanceScore: 9,
    confidenceScore: 8,
    summarySnippet:
      "The court found that COVID-19 related restrictions constituted force majeure events when explicitly mentioned in the contract.",
    keyArguments: [
      "Government-mandated closures during COVID-19 constitute unforeseeable circumstances",
      "Force majeure clauses must be interpreted strictly against the party invoking them",
      "Performance must be truly impossible, not merely more difficult or expensive",
    ],
    extractedEntities: [
      {
        name: "Smith v. Jones",
        type: "Case",
        details: "345 F.Supp. 2d 123 (N.D. Cal. 2023)",
      },
      {
        name: "Force Majeure",
        type: "LegalConcept",
        details: "Contractual excuse doctrine",
      },
    ],
    extractedQuotes: [
      '"The pandemic represents an unprecedented disruption to commercial activities"',
      '"Force majeure relief is available only when performance is truly impossible"',
    ],
    fullText: "SMITH v. JONES\n\nFull text of the court decision...",
    counterArguments: [
      "The pandemic was foreseeable by early 2020",
      "Alternative performance methods were available",
    ],
    analysisReasoning: {
      analyzeLegalQuestionSummary:
        "The legal question involves determining whether COVID-19 restrictions constitute force majeure events under contract law.",
      considerRelevantPrinciplesSummary:
        "Relevant principles include the doctrine of impossibility, force majeure clauses, and government intervention defenses.",
    },
  }

  describe("Extended Document Analysis Processing", () => {
    it("should handle extended document analysis data correctly", async () => {
      const updates: ResearchUpdate[] = [
        {
          type: "STATUS_CHANGE",
          stage: "ANALYZING_DOCUMENTS",
          message: "Starting document analysis...",
        },
        {
          type: "DATA",
          stage: "ANALYZING_DOCUMENTS",
          data: mockExtendedAnalysisData,
          message: "Analysis complete for Smith v. Jones",
        },
      ]

      const mockStream = createMockStream(updates)
      mockedConductResearch.mockResolvedValue(mockStream)

      const { result } = renderHook(() => useResearchAgent(), {
        wrapper: JotaiProvider,
      })

      await act(async () => {
        await result.current.startResearch("Test legal question")
      })

      await waitFor(() => {
        const analyzedDocs = store.get(analyzedDocsSummaryAtom)
        expect(analyzedDocs).toHaveLength(1)

        const doc = analyzedDocs[0]
        expect(doc?.docId).toBe("doc-extended-1")
        expect(doc?.title).toBe(
          "Smith v. Jones, 345 F.Supp. 2d 123 (N.D. Cal. 2023)"
        )
        expect(doc?.url).toBe("https://example.com/smith-v-jones")
        expect(doc?.keyArguments).toHaveLength(3)
        expect(doc?.extractedEntities).toHaveLength(2)
        expect(doc?.extractedQuotes).toHaveLength(2)
        expect(doc?.counterArguments).toHaveLength(2)
        expect(doc?.analysisReasoning?.analyzeLegalQuestionSummary).toContain(
          "COVID-19 restrictions"
        )
      })
    })

    it("should update existing documents with progressive data", async () => {
      // First update with basic data
      const initialUpdate: ResearchUpdate = {
        type: "DATA",
        stage: "ANALYZING_DOCUMENTS",
        data: {
          docId: "doc-progressive",
          title: "Progressive Document",
          relevanceScore: 7,
          summarySnippet: "Initial summary...",
        },
        message: "Initial analysis",
      }

      // Second update with extended data
      const extendedUpdate: ResearchUpdate = {
        type: "DATA",
        stage: "ANALYZING_DOCUMENTS",
        data: {
          docId: "doc-progressive",
          title: "Progressive Document",
          relevanceScore: 7,
          summarySnippet: "Updated summary with more content...",
          keyArguments: ["New argument 1", "New argument 2"],
          extractedEntities: [
            {
              name: "Test Entity",
              type: "LegalConcept",
              details: "Test details",
            },
          ],
        },
        message: "Extended analysis complete",
      }

      const updates = [initialUpdate, extendedUpdate]
      const mockStream = createMockStream(updates)
      mockedConductResearch.mockResolvedValue(mockStream)

      const { result } = renderHook(() => useResearchAgent(), {
        wrapper: JotaiProvider,
      })

      await act(async () => {
        await result.current.startResearch("Test legal question")
      })

      await waitFor(() => {
        const analyzedDocs = store.get(analyzedDocsSummaryAtom)
        expect(analyzedDocs).toHaveLength(1)

        const doc = analyzedDocs[0]
        expect(doc?.docId).toBe("doc-progressive")
        expect(doc?.summarySnippet).toBe("Updated summary with more content...")
        expect(doc?.keyArguments).toEqual(["New argument 1", "New argument 2"])
        expect(doc?.extractedEntities).toHaveLength(1)
        expect(doc?.extractedEntities?.[0]?.name).toBe("Test Entity")
      })
    })

    it("should handle multiple documents with different data completeness", async () => {
      const updates: ResearchUpdate[] = [
        {
          type: "DATA",
          stage: "ANALYZING_DOCUMENTS",
          data: {
            docId: "doc-minimal",
            title: "Minimal Document",
            relevanceScore: 5,
            summarySnippet: "Basic summary",
          },
          message: "Basic analysis complete",
        },
        {
          type: "DATA",
          stage: "ANALYZING_DOCUMENTS",
          data: mockExtendedAnalysisData,
          message: "Extended analysis complete",
        },
      ]

      const mockStream = createMockStream(updates)
      mockedConductResearch.mockResolvedValue(mockStream)

      const { result } = renderHook(() => useResearchAgent(), {
        wrapper: JotaiProvider,
      })

      await act(async () => {
        await result.current.startResearch("Test legal question")
      })

      await waitFor(() => {
        const analyzedDocs = store.get(analyzedDocsSummaryAtom)
        expect(analyzedDocs).toHaveLength(2)

        // Check minimal document
        const minimalDoc = analyzedDocs.find(doc => doc.docId === "doc-minimal")
        expect(minimalDoc).toBeDefined()
        expect(minimalDoc?.keyArguments).toBeUndefined()
        expect(minimalDoc?.extractedEntities).toBeUndefined()

        // Check extended document
        const extendedDoc = analyzedDocs.find(
          doc => doc.docId === "doc-extended-1"
        )
        expect(extendedDoc).toBeDefined()
        expect(extendedDoc?.keyArguments).toHaveLength(3)
        expect(extendedDoc?.extractedEntities).toHaveLength(2)
      })
    })

    it("should handle streaming text updates for extended fields", async () => {
      const streamingUpdates: ResearchUpdate[] = [
        {
          type: "DATA",
          stage: "ANALYZING_DOCUMENTS",
          data: {
            docId: "doc-streaming",
            title: "Streaming Document",
            relevanceScore: 8,
            summarySnippet: "The court found that...",
            keyArguments: ["Initial argument"],
          },
          message: "Partial analysis",
        },
        {
          type: "DATA",
          stage: "ANALYZING_DOCUMENTS",
          data: {
            docId: "doc-streaming",
            title: "Streaming Document",
            relevanceScore: 8,
            summarySnippet: "The court found that COVID-19 restrictions...",
            keyArguments: [
              "Initial argument",
              "Additional argument from further analysis",
            ],
          },
          message: "Updated analysis",
        },
      ]

      const mockStream = createMockStream(streamingUpdates)
      mockedConductResearch.mockResolvedValue(mockStream)

      const { result } = renderHook(() => useResearchAgent(), {
        wrapper: JotaiProvider,
      })

      await act(async () => {
        await result.current.startResearch("Test legal question")
      })

      await waitFor(() => {
        const analyzedDocs = store.get(analyzedDocsSummaryAtom)
        const doc = analyzedDocs[0]
        expect(doc?.summarySnippet).toBe(
          "The court found that COVID-19 restrictions..."
        )
        expect(doc?.keyArguments).toHaveLength(2)
        expect(doc?.keyArguments?.[1]).toBe(
          "Additional argument from further analysis"
        )
      })
    })

    it("should preserve entity type information correctly", async () => {
      const diverseEntities: ClientLegalEntity[] = [
        { name: "Test Case", type: "Case", details: "Citation" },
        {
          name: "Test Statute",
          type: "Statute",
          details: "Code section",
        },
        { name: "John Doe", type: "Person", details: "Role" },
        { name: "Corp Inc.", type: "Organization", details: "Company" },
        {
          name: "Legal Concept",
          type: "LegalConcept",
          details: "Description",
        },
        { name: "California", type: "Jurisdiction", details: "State" },
      ]

      const updates: ResearchUpdate[] = [
        {
          type: "DATA",
          stage: "ANALYZING_DOCUMENTS",
          data: {
            docId: "doc-entities",
            title: "Entity Test Document",
            relevanceScore: 7,
            extractedEntities: diverseEntities,
          },
          message: "Entity extraction complete",
        },
      ]

      const mockStream = createMockStream(updates)
      mockedConductResearch.mockResolvedValue(mockStream)

      const { result } = renderHook(() => useResearchAgent(), {
        wrapper: JotaiProvider,
      })

      await act(async () => {
        await result.current.startResearch("Test legal question")
      })

      await waitFor(() => {
        const analyzedDocs = store.get(analyzedDocsSummaryAtom)
        const doc = analyzedDocs[0]
        expect(doc?.extractedEntities).toHaveLength(6)

        const entityTypes = doc?.extractedEntities?.map(e => e.type)
        expect(entityTypes).toContain("Case")
        expect(entityTypes).toContain("Statute")
        expect(entityTypes).toContain("Person")
        expect(entityTypes).toContain("Organization")
        expect(entityTypes).toContain("LegalConcept")
        expect(entityTypes).toContain("Jurisdiction")

        // Verify entity details are preserved
        const caseEntity = doc?.extractedEntities?.find(e => e.type === "Case")
        expect(caseEntity?.details).toBe("Citation")
      })
    })

    it("should handle analysis reasoning data correctly", async () => {
      const reasoningData: ClientAnalysisReasoning = {
        analyzeLegalQuestionSummary:
          "Comprehensive analysis of the legal question involving contract law and force majeure provisions.",
        considerRelevantPrinciplesSummary:
          "Relevant principles include impossibility doctrine, government intervention, and contractual interpretation.",
        formulateSearchQueriesSummary:
          "Search strategy focused on recent precedents and statutory provisions.",
        specifyExpectedInfoSummary:
          "Expected case law, regulatory guidance, and scholarly commentary.",
        ensureComprehensiveCoverageSummary:
          "Multi-jurisdictional approach ensuring comprehensive legal analysis.",
      }

      const updates: ResearchUpdate[] = [
        {
          type: "DATA",
          stage: "ANALYZING_DOCUMENTS",
          data: {
            docId: "doc-reasoning",
            title: "Reasoning Test Document",
            relevanceScore: 9,
            analysisReasoning: reasoningData,
          },
          message: "Reasoning analysis complete",
        },
      ]

      const mockStream = createMockStream(updates)
      mockedConductResearch.mockResolvedValue(mockStream)

      const { result } = renderHook(() => useResearchAgent(), {
        wrapper: JotaiProvider,
      })

      await act(async () => {
        await result.current.startResearch("Test legal question")
      })

      await waitFor(() => {
        const analyzedDocs = store.get(analyzedDocsSummaryAtom)
        const doc = analyzedDocs[0]

        expect(doc?.analysisReasoning).toBeDefined()
        expect(doc?.analysisReasoning?.analyzeLegalQuestionSummary).toContain(
          "Comprehensive analysis"
        )
        expect(
          doc?.analysisReasoning?.considerRelevantPrinciplesSummary
        ).toContain("impossibility doctrine")
        expect(doc?.analysisReasoning?.formulateSearchQueriesSummary).toContain(
          "Search strategy"
        )
      })
    })
  })

  describe("Error Handling with Extended Data", () => {
    it("should handle malformed extended data gracefully", async () => {
      const malformedUpdates: ResearchUpdate[] = [
        {
          type: "DATA",
          stage: "ANALYZING_DOCUMENTS",
          data: {
            docId: "doc-malformed",
            title: "Malformed Document",
            relevanceScore: 7,
            extractedEntities: "not an array" as unknown as string[],
            keyArguments: { invalid: "structure" } as unknown as string[],
          },
          message: "Malformed data test",
        },
      ]

      const mockStream = createMockStream(malformedUpdates)
      mockedConductResearch.mockResolvedValue(mockStream)

      const { result } = renderHook(() => useResearchAgent(), {
        wrapper: JotaiProvider,
      })

      await act(async () => {
        await result.current.startResearch("Test legal question")
      })

      // Should not crash and should still store basic document info
      await waitFor(() => {
        const analyzedDocs = store.get(analyzedDocsSummaryAtom)
        expect(analyzedDocs).toHaveLength(1)
        expect(analyzedDocs[0]?.docId).toBe("doc-malformed")
        expect(analyzedDocs[0]?.title).toBe("Malformed Document")
      })
    })

    it("should handle error updates correctly", async () => {
      const failingUpdates: ResearchUpdate[] = [
        {
          type: "STATUS_CHANGE",
          stage: "ANALYZING_DOCUMENTS",
          message: "Starting analysis...",
        },
        {
          type: "ERROR",
          stage: "ANALYZING_DOCUMENTS",
          message: "Analysis failed for some documents",
        },
      ]

      const mockStream = createMockStream(failingUpdates)
      mockedConductResearch.mockResolvedValue(mockStream)

      const { result } = renderHook(() => useResearchAgent(), {
        wrapper: JotaiProvider,
      })

      await act(async () => {
        await result.current.startResearch("Test legal question")
      })

      await waitFor(() => {
        // Error should be reflected in status
        const status = store.get(researchStatusAtom)
        expect(status.error).toContain("Analysis failed")
        expect(status.stage).toBe("ERROR")
      })

      // Analyzed docs should be empty since no successful data updates occurred
      const analyzedDocs = store.get(analyzedDocsSummaryAtom)
      expect(analyzedDocs).toEqual([])
    })
  })

  describe("Performance and Memory", () => {
    it("should handle large datasets efficiently", async () => {
      const largeEntityList: ClientLegalEntity[] = Array.from(
        { length: 100 },
        (_, i) => ({
          name: `Entity ${i}`,
          type: "LegalConcept",
          details: `Details for entity ${i}`,
        })
      )

      const largeKeyArguments = Array.from(
        { length: 50 },
        (_, i) =>
          `This is a very detailed legal argument number ${i} that contains substantial legal reasoning and analysis.`
      )

      const updates: ResearchUpdate[] = [
        {
          type: "DATA",
          stage: "ANALYZING_DOCUMENTS",
          data: {
            docId: "large-doc",
            title: "Large Document",
            relevanceScore: 8,
            extractedEntities: largeEntityList,
            keyArguments: largeKeyArguments,
            fullText: "A".repeat(10000), // Large text content
          },
          message: "Large document processed",
        },
      ]

      const mockStream = createMockStream(updates)
      mockedConductResearch.mockResolvedValue(mockStream)

      const { result } = renderHook(() => useResearchAgent(), {
        wrapper: JotaiProvider,
      })

      const startTime = performance.now()

      await act(async () => {
        await result.current.startResearch("Test legal question")
      })

      await waitFor(() => {
        const analyzedDocs = store.get(analyzedDocsSummaryAtom)
        const doc = analyzedDocs[0]
        expect(doc?.extractedEntities).toHaveLength(100)
        expect(doc?.keyArguments).toHaveLength(50)
        expect(doc?.fullText).toHaveLength(10000)
      })

      const endTime = performance.now()

      // Processing should complete in reasonable time (less than 1 second)
      expect(endTime - startTime).toBeLessThan(1000)
    })
  })
})



import { act, renderHook, waitFor } from "@testing-library/react"
import { Provider, createStore } from "jotai"
import { createElement } from "react"
import type { ReactNode } from "react"
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest"

import { conductResearch } from "@/app/actions/researchAgentOrchestrator"
import type { ResearchStage } from "@/app/actions/researchAgentOrchestrator"
import { useResearchAgent } from "@/lib/hooks/useResearchAgent"
import {
  analyzedDocsSummaryAtom,
  generatedQueriesAtom,
  researchLogAtom,
  researchStatusAtom,
  synthesisDetailsAtom,
} from "@/lib/state/researchAtoms"

// Mock the server action
vi.mock("@/app/actions/researchAgentOrchestrator", () => ({
  conductResearch: vi.fn(),
}))

const mockedConductResearch = vi.mocked(conductResearch)

describe("useResearchAgent Hook", () => {
  let store: ReturnType

  const JotaiProvider = ({ children }: { children: ReactNode }) =>
    createElement(Provider, { store }, children)

  beforeEach(() => {
    store = createStore()
    vi.clearAllMocks()
  })

  afterEach(() => {
    vi.clearAllTimers()
  })

  describe("Hook Skeleton and Basic Structure", () => {
    it("should initialize with correct default state", () => {
      const { result } = renderHook(() => useResearchAgent(), {
        wrapper: JotaiProvider,
      })

      expect(result.current).toEqual({
        startResearch: expect.any(Function),
        resumeResearch: expect.any(Function),
        pauseResearch: expect.any(Function),
        abortResearch: expect.any(Function),
        isLoading: false,
        currentStage: "IDLE",
        currentMessage: "Ready to start research.",
        error: null,
        isPaused: false,
        canResume: false,
        autoModeEnabled: false,
        toggleAutoMode: expect.any(Function),
      })
    })

    it("should provide startResearch function that accepts a legal question", () => {
      const { result } = renderHook(() => useResearchAgent(), {
        wrapper: JotaiProvider,
      })

      expect(typeof result.current.startResearch).toBe("function")
      expect(result.current.startResearch.length).toBe(1) // should accept one parameter
    })

    it("should provide abortResearch function", () => {
      const { result } = renderHook(() => useResearchAgent(), {
        wrapper: JotaiProvider,
      })

      expect(typeof result.current.abortResearch).toBe("function")
      expect(result.current.abortResearch.length).toBe(0) // should accept no parameters
    })

    it("should read research status from Jotai atoms correctly", () => {
      // Set initial state in the store
      store.set(researchStatusAtom, {
        stage: "GENERATING_QUERIES" as ResearchStage,
        isLoading: true,
        error: null,
        message: "Generating search queries...",
        currentProcessedDoc: 0,
        totalDocsToProcess: 5,
      })

      const { result } = renderHook(() => useResearchAgent(), {
        wrapper: JotaiProvider,
      })

      expect(result.current.isLoading).toBe(true)
      expect(result.current.currentStage).toBe("GENERATING_QUERIES")
      expect(result.current.currentMessage).toBe("Generating search queries...")
      expect(result.current.error).toBe(null)
    })

    it("should expose error state when research status has error", () => {
      store.set(researchStatusAtom, {
        stage: "ERROR" as ResearchStage,
        isLoading: false,
        error: "Failed to generate queries",
        message: "An error occurred",
      })

      const { result } = renderHook(() => useResearchAgent(), {
        wrapper: JotaiProvider,
      })

      expect(result.current.isLoading).toBe(false)
      expect(result.current.currentStage).toBe("ERROR")
      expect(result.current.error).toBe("Failed to generate queries")
    })
  })

  describe("startResearch Basic Functionality", () => {
    it("should reset all research state when starting new research", async () => {
      // Set some initial state that should be cleared
      store.set(researchStatusAtom, {
        stage: "COMPLETED" as ResearchStage,
        isLoading: false,
        error: null,
        message: "Previous research completed",
      })
      store.set(researchLogAtom, ["Previous log entry"])
      store.set(generatedQueriesAtom, [{ query_string: "old query" }])

      // Mock a simple stream response
      const mockStream = new ReadableStream({
        start(controller) {
          controller.close()
        },
      })
      mockedConductResearch.mockResolvedValue(mockStream)

      const { result } = renderHook(() => useResearchAgent(), {
        wrapper: JotaiProvider,
      })

      await act(async () => {
        await result.current.startResearch(
          "What are the implications of AI in healthcare?"
        )
      })

      // Check that state was reset
      expect(store.get(generatedQueriesAtom)).toEqual([])
      expect(store.get(analyzedDocsSummaryAtom)).toEqual([])
      expect(store.get(synthesisDetailsAtom)).toEqual({
        topics: [],
        unansweredAspects: [],
        emergingQuestions: [],
        reasoningSummary: "",
      })
    })

    it("should set initializing state when starting research", async () => {
      let streamController:
        | ReadableStreamDefaultController
        | undefined
      const mockStream = new ReadableStream({
        start(controller) {
          streamController = controller
          // Don't close immediately, keep stream open for testing
        },
      })
      mockedConductResearch.mockResolvedValue(mockStream)

      const { result } = renderHook(() => useResearchAgent(), {
        wrapper: JotaiProvider,
      })

      // Start research but don't await completion
      act(() => {
        result.current.startResearch("Test legal question")
      })

      // Check status immediately after calling startResearch
      await waitFor(() => {
        const status = store.get(researchStatusAtom)
        expect(status.stage).toBe("INITIALIZING")
      })

      const status = store.get(researchStatusAtom)
      expect(status.isLoading).toBe(true)
      expect(status.error).toBe(null)
      expect(status.message).toBe("Initializing research...")

      // Clean up by closing the stream
      streamController?.close()
    })

    it("should call conductResearch server action with legal question", async () => {
      const mockStream = new ReadableStream({
        start(controller) {
          controller.close()
        },
      })
      mockedConductResearch.mockResolvedValue(mockStream)

      const { result } = renderHook(() => useResearchAgent(), {
        wrapper: JotaiProvider,
      })

      const legalQuestion =
        "What are the patent implications of AI-generated code?"

      await act(async () => {
        await result.current.startResearch(legalQuestion)
      })

      expect(mockedConductResearch).toHaveBeenCalledWith(legalQuestion, {
        currentIteration: 0,
        isEnabled: false,
        maxIterations: 3,
      })
      expect(mockedConductResearch).toHaveBeenCalledTimes(1)
    })

    it("should handle errors from conductResearch server action", async () => {
      const errorMessage = "Network error"
      mockedConductResearch.mockRejectedValue(new Error(errorMessage))

      const { result } = renderHook(() => useResearchAgent(), {
        wrapper: JotaiProvider,
      })

      await act(async () => {
        await result.current.startResearch("Test question")
      })

      const status = store.get(researchStatusAtom)
      expect(status.stage).toBe("ERROR")
      expect(status.isLoading).toBe(false)
      expect(status.error).toBe(errorMessage)
    })

    it("should add log entries when starting research", async () => {
      const mockStream = new ReadableStream({
        start(controller) {
          controller.close()
        },
      })
      mockedConductResearch.mockResolvedValue(mockStream)

      const { result } = renderHook(() => useResearchAgent(), {
        wrapper: JotaiProvider,
      })

      const legalQuestion = "Test legal question"

      await act(async () => {
        await result.current.startResearch(legalQuestion)
      })

      const logs = store.get(researchLogAtom)
      expect(logs.length).toBeGreaterThan(0)
      expect(logs[0]).toContain("[INITIALIZING]")
      expect(logs[0]).toContain("Research process initiated")
      expect(logs[0]).toContain(legalQuestion)
    })
  })

  describe("abortResearch Basic Functionality", () => {
    it("should be callable without throwing", () => {
      const { result } = renderHook(() => useResearchAgent(), {
        wrapper: JotaiProvider,
      })

      expect(() => {
        result.current.abortResearch()
      }).not.toThrow()
    })

    it("should log when no active research to abort", () => {
      const consoleSpy = vi.spyOn(console, "log").mockImplementation(() => {
        // Mock implementation - intentionally empty
      })

      const { result } = renderHook(() => useResearchAgent(), {
        wrapper: JotaiProvider,
      })

      act(() => {
        result.current.abortResearch()
      })

      expect(consoleSpy).toHaveBeenCalledWith(
        "useResearchAgent: No active research to abort."
      )

      consoleSpy.mockRestore()
    })
  })

  describe("Stream Processing and Update Handling", () => {
    it("should process STATUS_CHANGE updates correctly", async () => {
      const updates = [
        JSON.stringify({
          type: "STATUS_CHANGE",
          stage: "GENERATING_QUERIES",
          message: "Starting query generation",
        }),
        JSON.stringify({
          type: "STATUS_CHANGE",
          stage: "FETCHING_DOCUMENTS",
          message: "Searching for documents",
          currentProcessedDoc: 1,
          totalDocsToProcess: 5,
        }),
      ].join("\n")

      const mockStream = new ReadableStream({
        start(controller) {
          controller.enqueue(new TextEncoder().encode(updates))
          controller.close()
        },
      })
      mockedConductResearch.mockResolvedValue(mockStream)

      const { result } = renderHook(() => useResearchAgent(), {
        wrapper: JotaiProvider,
      })

      await act(async () => {
        await result.current.startResearch("Test legal question")
      })

      await waitFor(() => {
        const status = store.get(researchStatusAtom)
        expect(status.stage).toBe("FETCHING_DOCUMENTS")
        expect(status.message).toBe("Searching for documents")
        expect(status.currentProcessedDoc).toBe(1)
        expect(status.totalDocsToProcess).toBe(5)
        expect(status.isLoading).toBe(false) // Stream ended
      })
    })

    it("should process DATA updates for generated queries", async () => {
      const queryData = {
        queries: [
          {
            query_string: "AI liability healthcare",
            expected_information_summary: "Cases on AI liability",
          },
          {
            query_string: "medical malpractice automation",
            expected_information_summary: "Malpractice precedents",
          },
        ],
      }

      const updates = [
        JSON.stringify({
          type: "DATA",
          stage: "GENERATING_QUERIES",
          message: "Generated search queries",
          data: queryData,
        }),
      ].join("\n")

      const mockStream = new ReadableStream({
        start(controller) {
          controller.enqueue(new TextEncoder().encode(updates))
          controller.close()
        },
      })
      mockedConductResearch.mockResolvedValue(mockStream)

      const { result } = renderHook(() => useResearchAgent(), {
        wrapper: JotaiProvider,
      })

      await act(async () => {
        await result.current.startResearch("Test legal question")
      })

      await waitFor(() => {
        const queries = store.get(generatedQueriesAtom)
        expect(queries).toHaveLength(2)
        expect(queries[0]).toEqual({
          query_string: "AI liability healthcare",
          expected_information_summary: "Cases on AI liability",
          timestamp: expect.any(String),
        })
        expect(queries[1]).toEqual({
          query_string: "medical malpractice automation",
          expected_information_summary: "Malpractice precedents",
          timestamp: expect.any(String),
        })
      })
    })

    it("should process DATA updates for analyzed documents", async () => {
      const docData = {
        docId: "doc-123",
        title: "Test Case Title",
        relevanceScore: 0.85,
        confidenceScore: 0.92,
        summarySnippet: "This case discusses AI liability...",
      }

      const updates = [
        JSON.stringify({
          type: "DATA",
          stage: "ANALYZING_DOCUMENTS",
          message: "Analyzed document",
          data: docData,
        }),
      ].join("\n")

      const mockStream = new ReadableStream({
        start(controller) {
          controller.enqueue(new TextEncoder().encode(updates))
          controller.close()
        },
      })
      mockedConductResearch.mockResolvedValue(mockStream)

      const { result } = renderHook(() => useResearchAgent(), {
        wrapper: JotaiProvider,
      })

      await act(async () => {
        await result.current.startResearch("Test legal question")
      })

      await waitFor(() => {
        const docs = store.get(analyzedDocsSummaryAtom)
        expect(docs).toHaveLength(1)
        expect(docs[0]).toEqual({
          ...docData,
          timestamp: expect.any(String),
        })
      })
    })

    it("should update existing documents when processing additional data", async () => {
      // First, add a document
      const initialDoc = {
        docId: "doc-456",
        title: "Initial Title",
        relevanceScore: 0.7,
      }

      // Then update it with more data
      const updatedDoc = {
        docId: "doc-456",
        summarySnippet: "Updated summary snippet",
        confidenceScore: 0.88,
      }

      const updates = [
        JSON.stringify({
          type: "DATA",
          stage: "ANALYZING_DOCUMENTS",
          data: initialDoc,
        }),
        JSON.stringify({
          type: "DATA",
          stage: "ANALYZING_DOCUMENTS",
          data: updatedDoc,
        }),
      ].join("\n")

      const mockStream = new ReadableStream({
        start(controller) {
          controller.enqueue(new TextEncoder().encode(updates))
          controller.close()
        },
      })
      mockedConductResearch.mockResolvedValue(mockStream)

      const { result } = renderHook(() => useResearchAgent(), {
        wrapper: JotaiProvider,
      })

      await act(async () => {
        await result.current.startResearch("Test legal question")
      })

      await waitFor(() => {
        const docs = store.get(analyzedDocsSummaryAtom)
        expect(docs).toHaveLength(1)
        expect(docs[0]).toEqual({
          docId: "doc-456",
          title: "Initial Title",
          relevanceScore: 0.7,
          summarySnippet: "Updated summary snippet",
          confidenceScore: 0.88,
          timestamp: expect.any(String),
        })
      })
    })

    it("should process synthesis findings updates", async () => {
      const synthesisData = {
        topics: [
          {
            title: "AI Liability",
            synthesisSnippet: "Key findings on liability",
            confidence: 0.9,
          },
          {
            title: "Medical Standards",
            synthesisSnippet: "Standards analysis",
            confidence: 0.8,
          },
        ],
        unansweredAspects: ["Jurisdiction variations"],
        emergingQuestions: ["What about future AI capabilities?"],
        reasoningSummary: "Comprehensive analysis shows...",
      }

      const updates = [
        JSON.stringify({
          type: "DATA",
          stage: "SYNTHESIZING_FINDINGS",
          message: "Synthesis complete",
          data: synthesisData,
        }),
      ].join("\n")

      const mockStream = new ReadableStream({
        start(controller) {
          controller.enqueue(new TextEncoder().encode(updates))
          controller.close()
        },
      })
      mockedConductResearch.mockResolvedValue(mockStream)

      const { result } = renderHook(() => useResearchAgent(), {
        wrapper: JotaiProvider,
      })

      await act(async () => {
        await result.current.startResearch("Test legal question")
      })

      await waitFor(() => {
        const synthesis = store.get(synthesisDetailsAtom)
        expect(synthesis).toEqual({
          ...synthesisData,
          topics: synthesisData.topics.map(topic => ({
            ...topic,
            timestamp: expect.any(String),
          })),
        })
      })
    })

    it("should handle ERROR type updates correctly", async () => {
      const updates = [
        JSON.stringify({
          type: "ERROR",
          stage: "GENERATING_QUERIES",
          message: "Failed to generate queries",
        }),
      ].join("\n")

      const mockStream = new ReadableStream({
        start(controller) {
          controller.enqueue(new TextEncoder().encode(updates))
          controller.close()
        },
      })
      mockedConductResearch.mockResolvedValue(mockStream)

      const { result } = renderHook(() => useResearchAgent(), {
        wrapper: JotaiProvider,
      })

      await act(async () => {
        await result.current.startResearch("Test legal question")
      })

      await waitFor(() => {
        const status = store.get(researchStatusAtom)
        expect(status.stage).toBe("ERROR")
        expect(status.isLoading).toBe(false)
        expect(status.error).toBe("Failed to generate queries")
      })
    })

    it("should handle malformed JSON gracefully", async () => {
      const updates = [
        JSON.stringify({
          type: "STATUS_CHANGE",
          stage: "GENERATING_QUERIES",
          message: "Valid update",
        }),
        '{"invalid": json malformed',
        JSON.stringify({
          type: "STATUS_CHANGE",
          stage: "FETCHING_DOCUMENTS",
          message: "Another valid update",
        }),
      ].join("\n")

      const mockStream = new ReadableStream({
        start(controller) {
          controller.enqueue(new TextEncoder().encode(updates))
          controller.close()
        },
      })
      mockedConductResearch.mockResolvedValue(mockStream)

      const { result } = renderHook(() => useResearchAgent(), {
        wrapper: JotaiProvider,
      })

      await act(async () => {
        await result.current.startResearch("Test legal question")
      })

      await waitFor(() => {
        const status = store.get(researchStatusAtom)
        // Should process the valid updates despite the malformed one
        expect(status.stage).toBe("FETCHING_DOCUMENTS")
        expect(status.message).toBe("Another valid update")

        // Should log the malformed JSON error
        const logs = store.get(researchLogAtom)
        const systemErrorLog = logs.find(log => log.includes("[SYSTEM_ERROR]"))
        expect(systemErrorLog).toBeDefined()
      })
    })

    it("should update research log for all update types", async () => {
      const updates = [
        JSON.stringify({
          type: "STATUS_CHANGE",
          stage: "GENERATING_QUERIES",
          message: "Status change message",
        }),
        JSON.stringify({
          type: "PROGRESS",
          stage: "ANALYZING_DOCUMENTS",
          message: "Progress update",
        }),
        JSON.stringify({
          type: "LOG",
          stage: "SYNTHESIZING_FINDINGS",
          message: "Log entry",
        }),
      ].join("\n")

      const mockStream = new ReadableStream({
        start(controller) {
          controller.enqueue(new TextEncoder().encode(updates))
          controller.close()
        },
      })
      mockedConductResearch.mockResolvedValue(mockStream)

      const { result } = renderHook(() => useResearchAgent(), {
        wrapper: JotaiProvider,
      })

      await act(async () => {
        await result.current.startResearch("Test legal question")
      })

      await waitFor(() => {
        const logs = store.get(researchLogAtom)
        // Should have initial log plus the three updates
        expect(logs.length).toBeGreaterThanOrEqual(4)

        // Check that all update types were logged
        const statusLog = logs.find(log =>
          log.includes("[GENERATING_QUERIES] (STATUS_CHANGE)")
        )
        const progressLog = logs.find(log =>
          log.includes("[ANALYZING_DOCUMENTS] (PROGRESS)")
        )
        const logEntry = logs.find(log =>
          log.includes("[SYNTHESIZING_FINDINGS] (LOG)")
        )

        expect(statusLog).toBeDefined()
        expect(progressLog).toBeDefined()
        expect(logEntry).toBeDefined()
      })
    })
  })

  describe("AbortController Management", () => {
    it("should create AbortController when starting research", async () => {
      let streamController:
        | ReadableStreamDefaultController
        | undefined
      const mockStream = new ReadableStream({
        start(controller) {
          streamController = controller
          // Keep stream open to test abort functionality
        },
      })
      mockedConductResearch.mockResolvedValue(mockStream)

      const { result } = renderHook(() => useResearchAgent(), {
        wrapper: JotaiProvider,
      })

      // Start research but don't await completion to keep controller active
      act(() => {
        result.current.startResearch("Test question")
      })

      // Give it a moment to start
      await waitFor(() => {
        const status = store.get(researchStatusAtom)
        expect(status.stage).toBe("INITIALIZING")
      })

      // Now test abort while controller is still active
      const consoleSpy = vi.spyOn(console, "log").mockImplementation(() => {
        // Mock implementation - intentionally empty
      })

      act(() => {
        result.current.abortResearch()
      })

      // Should log "Abort signal sent" since controller exists
      expect(consoleSpy).toHaveBeenCalledWith(
        "useResearchAgent: Abort signal sent."
      )

      consoleSpy.mockRestore()

      // Clean up
      streamController?.close()
    })
  })
})



// __tests__/lib/state/researchAtoms.test.ts

import { createStore } from "jotai"
import { beforeEach, describe, expect, it } from "vitest"

import {
  type ClientAnalyzedDoc,
  type ClientFinalReport,
  // Types
  type ClientSearchQuery,
  type ClientSynthesis,
  type ResearchStatus,
  analyzedDocsSummaryAtom,
  currentResearchStageAtom,
  executiveSummaryDisplayAtom,
  finalReportContentAtom,
  generatedQueriesAtom,
  // Derived atoms
  isResearchLoadingAtom,
  reportSectionsDisplayAtom,
  researchErrorAtom,
  researchLogAtom,
  // Core atoms
  researchStatusAtom,
  // Reset atom
  resetResearchStateAtom,
  synthesisDetailsAtom,
} from "@/lib/state/researchAtoms"

describe("ResearchAtoms - Type Definitions and Initial States", () => {
  let store: ReturnType

  beforeEach(() => {
    store = createStore()
  })

  describe("researchStatusAtom", () => {
    it("should have correct initial state", () => {
      const initialState = store.get(researchStatusAtom)

      expect(initialState).toEqual({
        stage: "IDLE",
        isLoading: false,
        error: null,
        message: "Ready to start research.",
        currentProcessedDoc: 0,
        totalDocsToProcess: 0,
        currentStreamingField: null,
      })
    })

    it("should accept ResearchStatus type updates", () => {
      const newStatus: ResearchStatus = {
        stage: "GENERATING_QUERIES",
        isLoading: true,
        error: null,
        message: "Generating search queries...",
        currentProcessedDoc: 0,
        totalDocsToProcess: 5,
        currentStreamingField: "queries",
      }

      store.set(researchStatusAtom, newStatus)
      expect(store.get(researchStatusAtom)).toEqual(newStatus)
    })
  })

  describe("researchLogAtom", () => {
    it("should have empty array as initial state", () => {
      const initialState = store.get(researchLogAtom)
      expect(initialState).toEqual([])
    })

    it("should accept string array updates", () => {
      const newLog = [
        "Started research",
        "Generated 3 queries",
        "Fetching documents",
      ]
      store.set(researchLogAtom, newLog)
      expect(store.get(researchLogAtom)).toEqual(newLog)
    })
  })

  describe("generatedQueriesAtom", () => {
    it("should have empty array as initial state", () => {
      const initialState = store.get(generatedQueriesAtom)
      expect(initialState).toEqual([])
    })

    it("should accept ClientSearchQuery array updates", () => {
      const queries: ClientSearchQuery[] = [
        {
          query_string: "contract law",
          expected_information_summary: "Legal precedents",
        },
        {
          query_string: "intellectual property",
          expected_information_summary: "Patent cases",
        },
      ]

      store.set(generatedQueriesAtom, queries)
      expect(store.get(generatedQueriesAtom)).toEqual(queries)
    })
  })

  describe("analyzedDocsSummaryAtom", () => {
    it("should have empty array as initial state", () => {
      const initialState = store.get(analyzedDocsSummaryAtom)
      expect(initialState).toEqual([])
    })

    it("should accept ClientAnalyzedDoc array updates", () => {
      const docs: ClientAnalyzedDoc[] = [
        {
          docId: "doc1",
          title: "Contract Law Basics",
          relevanceScore: 0.95,
          confidenceScore: 0.87,
          summarySnippet:
            "This document covers fundamental contract principles...",
        },
        {
          docId: "doc2",
          title: "Intellectual Property Rights",
          relevanceScore: 0.82,
          confidenceScore: 0.91,
          summarySnippet: "IP protection mechanisms and legal frameworks...",
        },
      ]

      store.set(analyzedDocsSummaryAtom, docs)
      expect(store.get(analyzedDocsSummaryAtom)).toEqual(docs)
    })
  })

  describe("synthesisDetailsAtom", () => {
    it("should have correct initial state", () => {
      const initialState = store.get(synthesisDetailsAtom)
      expect(initialState).toEqual({
        topics: [],
        unansweredAspects: [],
        emergingQuestions: [],
        reasoningSummary: "",
      })
    })

    it("should accept ClientSynthesis type updates", () => {
      const synthesis: ClientSynthesis = {
        topics: [
          {
            title: "Contract Formation",
            synthesisSnippet: "Key elements of valid contracts...",
            confidence: 0.92,
            docIds: ["doc1", "doc2"],
          },
        ],
        unansweredAspects: ["International jurisdiction"],
        emergingQuestions: ["How does digital signature affect validity?"],
        reasoningSummary: "Analysis shows strong precedent for...",
      }

      store.set(synthesisDetailsAtom, synthesis)
      expect(store.get(synthesisDetailsAtom)).toEqual(synthesis)
    })
  })

  describe("finalReportContentAtom", () => {
    it("should have correct initial state", () => {
      const initialState = store.get(finalReportContentAtom)
      expect(initialState).toEqual({
        title: "",
        executiveSummary: "",
        sections: [],
        conclusion: "",
        limitations: [],
        appendixDocIds: [],
      })
    })

    it("should accept ClientFinalReport type updates", () => {
      const report: ClientFinalReport = {
        title: "Legal Analysis Report",
        executiveSummary: "This report analyzes...",
        sections: [
          {
            title: "Background",
            content: "Legal context includes...",
          },
          { title: "Analysis", content: "Key findings show..." },
        ],
        conclusion: "Based on the analysis...",
        limitations: ["Limited case law in jurisdiction"],
        appendixDocIds: ["doc1", "doc2", "doc3"],
      }

      store.set(finalReportContentAtom, report)
      expect(store.get(finalReportContentAtom)).toEqual(report)
    })
  })
})

describe("ResearchAtoms - Derived Atoms", () => {
  let store: ReturnType

  beforeEach(() => {
    store = createStore()
  })

  describe("isResearchLoadingAtom", () => {
    it("should reflect loading state from researchStatusAtom", () => {
      expect(store.get(isResearchLoadingAtom)).toBe(false)

      store.set(researchStatusAtom, {
        stage: "GENERATING_QUERIES",
        isLoading: true,
        error: null,
        message: "Loading...",
        currentProcessedDoc: 0,
        totalDocsToProcess: 0,
      })

      expect(store.get(isResearchLoadingAtom)).toBe(true)
    })
  })

  describe("currentResearchStageAtom", () => {
    it("should reflect stage from researchStatusAtom", () => {
      expect(store.get(currentResearchStageAtom)).toBe("IDLE")

      store.set(researchStatusAtom, {
        stage: "ANALYZING_DOCUMENTS",
        isLoading: true,
        error: null,
        message: "Analyzing...",
        currentProcessedDoc: 0,
        totalDocsToProcess: 0,
      })

      expect(store.get(currentResearchStageAtom)).toBe("ANALYZING_DOCUMENTS")
    })
  })

  describe("researchErrorAtom", () => {
    it("should reflect error from researchStatusAtom", () => {
      expect(store.get(researchErrorAtom)).toBe(null)

      store.set(researchStatusAtom, {
        stage: "ERROR",
        isLoading: false,
        error: "Failed to connect to API",
        message: "Error occurred",
        currentProcessedDoc: 0,
        totalDocsToProcess: 0,
      })

      expect(store.get(researchErrorAtom)).toBe("Failed to connect to API")
    })
  })

  describe("executiveSummaryDisplayAtom", () => {
    it("should reflect executiveSummary from finalReportContentAtom", () => {
      expect(store.get(executiveSummaryDisplayAtom)).toBe("")

      store.set(finalReportContentAtom, {
        title: "",
        executiveSummary: "This is an executive summary...",
        sections: [],
        conclusion: "",
        limitations: [],
        appendixDocIds: [],
      })

      expect(store.get(executiveSummaryDisplayAtom)).toBe(
        "This is an executive summary..."
      )
    })
  })

  describe("reportSectionsDisplayAtom", () => {
    it("should reflect sections from finalReportContentAtom", () => {
      expect(store.get(reportSectionsDisplayAtom)).toEqual([])

      const sections = [
        { title: "Introduction", content: "This report..." },
        { title: "Analysis", content: "The key findings..." },
      ]

      store.set(finalReportContentAtom, {
        title: "",
        executiveSummary: "",
        sections,
        conclusion: "",
        limitations: [],
        appendixDocIds: [],
      })

      expect(store.get(reportSectionsDisplayAtom)).toEqual(sections)
    })
  })
})

describe("ResearchAtoms - Reset Functionality", () => {
  let store: ReturnType

  beforeEach(() => {
    store = createStore()
  })

  it("should reset all atoms to initial state when resetResearchStateAtom is triggered", () => {
    // Set some non-initial values
    store.set(researchStatusAtom, {
      stage: "ANALYZING_DOCUMENTS",
      isLoading: true,
      error: "Some error",
      message: "Processing...",
      currentProcessedDoc: 3,
      totalDocsToProcess: 10,
      currentStreamingField: "analysis",
    })

    store.set(researchLogAtom, [
      "Started",
      "Generated queries",
      "Fetching docs",
    ])

    store.set(generatedQueriesAtom, [
      {
        query_string: "test query",
        expected_information_summary: "test info",
      },
    ])

    store.set(analyzedDocsSummaryAtom, [
      { docId: "test-doc", title: "Test Document", relevanceScore: 0.8 },
    ])

    store.set(synthesisDetailsAtom, {
      topics: [{ title: "Test Topic", synthesisSnippet: "Test snippet" }],
      unansweredAspects: ["aspect1"],
      emergingQuestions: ["question1"],
      reasoningSummary: "Test reasoning",
    })

    store.set(finalReportContentAtom, {
      title: "Test Report",
      executiveSummary: "Test summary",
      sections: [{ title: "Test Section", content: "Test content" }],
      conclusion: "Test conclusion",
      limitations: ["limitation1"],
      appendixDocIds: ["doc1"],
    })

    // Trigger reset
    store.set(resetResearchStateAtom, null)

    // Verify all atoms are reset to initial states
    expect(store.get(researchStatusAtom)).toEqual({
      stage: "IDLE",
      isLoading: false,
      error: null,
      message: "Ready.",
      currentProcessedDoc: 0,
      totalDocsToProcess: 0,
      currentStreamingField: null,
      isPaused: false,
      canResume: false,
    })

    expect(store.get(researchLogAtom)).toEqual([])
    expect(store.get(generatedQueriesAtom)).toEqual([])
    expect(store.get(analyzedDocsSummaryAtom)).toEqual([])

    expect(store.get(synthesisDetailsAtom)).toEqual({
      topics: [],
      unansweredAspects: [],
      emergingQuestions: [],
      reasoningSummary: "",
    })

    expect(store.get(finalReportContentAtom)).toEqual({
      title: "",
      executiveSummary: "",
      sections: [],
      conclusion: "",
      limitations: [],
      appendixDocIds: [],
    })

    // Verify derived atoms also reflect reset state
    expect(store.get(isResearchLoadingAtom)).toBe(false)
    expect(store.get(currentResearchStageAtom)).toBe("IDLE")
    expect(store.get(researchErrorAtom)).toBe(null)
    expect(store.get(executiveSummaryDisplayAtom)).toBe("")
    expect(store.get(reportSectionsDisplayAtom)).toEqual([])
  })

  it("should work when called multiple times", () => {
    // Set some values
    store.set(researchLogAtom, ["test message"])

    // Reset first time
    store.set(resetResearchStateAtom, null)
    expect(store.get(researchLogAtom)).toEqual([])

    // Set values again
    store.set(researchLogAtom, ["another message"])

    // Reset second time
    store.set(resetResearchStateAtom, null)
    expect(store.get(researchLogAtom)).toEqual([])
  })
})



/**
 * Tests for Exa Search custom error classes
 */

import { describe, expect, it } from "vitest"

import {
  ExaAuthError,
  ExaClientError,
  ExaConfigError,
  ExaError,
  ExaNetworkError,
  ExaParsingError,
  ExaRateLimitError,
  ExaServerError,
  getRetryDelay,
  isExaAuthError,
  isExaClientError,
  isExaConfigError,
  isExaError,
  isExaNetworkError,
  isExaParsingError,
  isExaRateLimitError,
  isExaServerError,
  isRetryableExaError,
} from "@/lib/utils/exaSearchErrors"

describe("ExaError Base Class", () => {
  it("should create an error with basic properties", () => {
    const error = new ExaRateLimitError("Test rate limit error", {
      status: 429,
      query: "test query",
    })

    expect(error).toBeInstanceOf(Error)
    expect(error).toBeInstanceOf(ExaError)
    expect(error.name).toBe("ExaRateLimitError")
    expect(error.message).toBe("Test rate limit error")
    expect(error.status).toBe(429)
    expect(error.query).toBe("test query")
  })

  it("should handle cause property", () => {
    const originalError = new Error("Original error")
    const error = new ExaServerError("Wrapped error", {
      cause: originalError,
    })

    expect(error.cause).toBe(originalError)
  })

  it("should create JSON representation", () => {
    const error = new ExaClientError("Client error", {
      status: 400,
      response: { error: "Bad request" },
      requestId: "req-123",
      query: "test query",
    })

    const json = error.toJSON()

    expect(json).toEqual({
      name: "ExaClientError",
      message: "Client error",
      status: 400,
      response: { error: "Bad request" },
      requestId: "req-123",
      query: "test query",
      stack: expect.any(String),
    })
  })
})

describe("ExaRateLimitError", () => {
  it("should handle rate limit specific properties", () => {
    const error = new ExaRateLimitError("Rate limit exceeded", {
      status: 429,
      retryAfter: 60,
      rateLimitType: "quota",
    })

    expect(error.retryAfter).toBe(60)
    expect(error.rateLimitType).toBe("quota")
  })

  it("should suggest retry delay based on retry-after header", () => {
    const error = new ExaRateLimitError("Rate limit exceeded", {
      retryAfter: 30,
    })

    expect(error.getSuggestedRetryDelay()).toBe(30000) // 30 seconds
  })

  it("should suggest exponential backoff when no retry-after", () => {
    const error = new ExaRateLimitError("Rate limit exceeded")

    expect(error.getSuggestedRetryDelay(1)).toBe(1000) // 1 second
    expect(error.getSuggestedRetryDelay(2)).toBe(2000) // 2 seconds
    expect(error.getSuggestedRetryDelay(3)).toBe(4000) // 4 seconds
    expect(error.getSuggestedRetryDelay(10)).toBe(30000) // Max 30 seconds
  })

  it("should default to requests rate limit type", () => {
    const error = new ExaRateLimitError("Rate limit exceeded")

    expect(error.rateLimitType).toBe("requests")
  })
})

describe("ExaAuthError", () => {
  it("should handle auth error types", () => {
    const error = new ExaAuthError("Authentication failed", {
      status: 401,
      authType: "invalid_key",
    })

    expect(error.authType).toBe("invalid_key")
    expect(error.isRecoverable()).toBe(false)
  })

  it("should determine if error is recoverable", () => {
    const invalidKeyError = new ExaAuthError("Invalid key", {
      authType: "invalid_key",
    })
    const permissionError = new ExaAuthError("Insufficient permissions", {
      authType: "insufficient_permissions",
    })

    expect(invalidKeyError.isRecoverable()).toBe(false)
    expect(permissionError.isRecoverable()).toBe(true)
  })

  it("should default to unknown auth type", () => {
    const error = new ExaAuthError("Authentication failed")

    expect(error.authType).toBe("unknown")
  })
})

describe("ExaServerError", () => {
  it("should handle server error properties", () => {
    const error = new ExaServerError("Server error", {
      status: 500,
      isTemporary: true,
    })

    expect(error.isTemporary).toBe(true)
  })

  it("should default to temporary for most 5xx errors", () => {
    const error500 = new ExaServerError("Internal server error", {
      status: 500,
    })
    const error502 = new ExaServerError("Bad gateway", { status: 502 })
    const error501 = new ExaServerError("Not implemented", { status: 501 })

    expect(error500.isTemporary).toBe(true)
    expect(error502.isTemporary).toBe(true)
    expect(error501.isTemporary).toBe(false) // 501 is permanent
  })

  it("should suggest appropriate retry delays", () => {
    const error = new ExaServerError("Server error")

    expect(error.getSuggestedRetryDelay(1)).toBe(500) // 500ms
    expect(error.getSuggestedRetryDelay(2)).toBe(1000) // 1 second
    expect(error.getSuggestedRetryDelay(3)).toBe(2000) // 2 seconds
    expect(error.getSuggestedRetryDelay(10)).toBe(10000) // Max 10 seconds
  })
})

describe("ExaClientError", () => {
  it("should handle client error properties", () => {
    const validationErrors = [
      { field: "query", message: "Query is required", value: "" },
      { field: "num_results", message: "Must be between 1 and 100", value: 0 },
    ]

    const error = new ExaClientError("Validation failed", {
      status: 400,
      errorCode: "VALIDATION_ERROR",
      validationErrors,
    })

    expect(error.errorCode).toBe("VALIDATION_ERROR")
    expect(error.validationErrors).toEqual(validationErrors)
  })

  it("should determine if error is retryable", () => {
    const validationError = new ExaClientError("Bad request", { status: 400 })
    const timeoutError = new ExaClientError("Request timeout", { status: 408 })

    expect(validationError.isRetryable()).toBe(false)
    expect(timeoutError.isRetryable()).toBe(true)
  })
})

describe("ExaNetworkError", () => {
  it("should handle network error properties", () => {
    const error = new ExaNetworkError("Connection refused", {
      isTimeout: false,
      isConnectionError: true,
    })

    expect(error.isTimeout).toBe(false)
    expect(error.isConnectionError).toBe(true)
  })

  it("should suggest different retry delays for timeout vs connection errors", () => {
    const timeoutError = new ExaNetworkError("Timeout", { isTimeout: true })
    const connectionError = new ExaNetworkError("Connection refused", {
      isConnectionError: true,
    })

    expect(timeoutError.getSuggestedRetryDelay(1)).toBe(2000) // Longer for timeouts
    expect(connectionError.getSuggestedRetryDelay(1)).toBe(1000) // Shorter for connection errors
  })

  it("should respect max delays", () => {
    const timeoutError = new ExaNetworkError("Timeout", { isTimeout: true })
    const connectionError = new ExaNetworkError("Connection refused", {
      isConnectionError: true,
    })

    expect(timeoutError.getSuggestedRetryDelay(10)).toBe(60000) // Max 60s for timeouts
    expect(connectionError.getSuggestedRetryDelay(10)).toBe(30000) // Max 30s for connections
  })
})

describe("ExaConfigError", () => {
  it("should handle config error types", () => {
    const error = new ExaConfigError("Missing API key", {
      configType: "missing_api_key",
    })

    expect(error.configType).toBe("missing_api_key")
    expect(error.isRetryable()).toBe(false)
  })

  it("should default to unknown config type", () => {
    const error = new ExaConfigError("Config error")

    expect(error.configType).toBe("unknown")
  })
})

describe("ExaParsingError", () => {
  it("should handle parsing error properties", () => {
    const error = new ExaParsingError("Invalid JSON", {
      expectedFormat: "JSON object",
      actualFormat: "string",
      response: "invalid json",
    })

    expect(error.expectedFormat).toBe("JSON object")
    expect(error.actualFormat).toBe("string")
    expect(error.response).toBe("invalid json")
  })
})

describe("Type Guards", () => {
  it("should correctly identify error types", () => {
    const rateLimitError = new ExaRateLimitError("Rate limit")
    const authError = new ExaAuthError("Auth failed")
    const serverError = new ExaServerError("Server error")
    const clientError = new ExaClientError("Client error")
    const networkError = new ExaNetworkError("Network error")
    const configError = new ExaConfigError("Config error")
    const parsingError = new ExaParsingError("Parsing error")
    const genericError = new Error("Generic error")

    expect(isExaError(rateLimitError)).toBe(true)
    expect(isExaError(genericError)).toBe(false)

    expect(isExaRateLimitError(rateLimitError)).toBe(true)
    expect(isExaRateLimitError(authError)).toBe(false)

    expect(isExaAuthError(authError)).toBe(true)
    expect(isExaAuthError(serverError)).toBe(false)

    expect(isExaServerError(serverError)).toBe(true)
    expect(isExaServerError(clientError)).toBe(false)

    expect(isExaClientError(clientError)).toBe(true)
    expect(isExaClientError(networkError)).toBe(false)

    expect(isExaNetworkError(networkError)).toBe(true)
    expect(isExaNetworkError(configError)).toBe(false)

    expect(isExaConfigError(configError)).toBe(true)
    expect(isExaConfigError(parsingError)).toBe(false)

    expect(isExaParsingError(parsingError)).toBe(true)
    expect(isExaParsingError(genericError)).toBe(false)
  })
})

describe("Retry Logic Helpers", () => {
  it("should correctly identify retryable errors", () => {
    const rateLimitError = new ExaRateLimitError("Rate limit")
    const serverError = new ExaServerError("Server error")
    const networkError = new ExaNetworkError("Network error")
    const authError = new ExaAuthError("Auth failed")
    const configError = new ExaConfigError("Config error")
    const timeoutClientError = new ExaClientError("Timeout", { status: 408 })
    const validationClientError = new ExaClientError("Validation failed", {
      status: 400,
    })

    expect(isRetryableExaError(rateLimitError)).toBe(true)
    expect(isRetryableExaError(serverError)).toBe(true)
    expect(isRetryableExaError(networkError)).toBe(true)
    expect(isRetryableExaError(authError)).toBe(false)
    expect(isRetryableExaError(configError)).toBe(false)
    expect(isRetryableExaError(timeoutClientError)).toBe(true)
    expect(isRetryableExaError(validationClientError)).toBe(false)
  })

  it("should provide appropriate retry delays", () => {
    const rateLimitError = new ExaRateLimitError("Rate limit", {
      retryAfter: 10,
    })
    const serverError = new ExaServerError("Server error")
    const networkError = new ExaNetworkError("Network error")
    const unknownError = new Error("Unknown error")

    expect(getRetryDelay(rateLimitError)).toBe(10000) // Uses retryAfter
    expect(getRetryDelay(serverError, 2)).toBe(1000) // Server error delay
    expect(getRetryDelay(networkError, 3)).toBe(4000) // Network error delay
    expect(getRetryDelay(unknownError, 2)).toBe(2000) // Default fallback
  })

  it("should respect maximum retry delays", () => {
    const rateLimitError = new ExaRateLimitError("Rate limit")
    const serverError = new ExaServerError("Server error")
    const networkError = new ExaNetworkError("Network error")

    expect(getRetryDelay(rateLimitError, 10)).toBe(30000) // Max 30s for rate limit
    expect(getRetryDelay(serverError, 10)).toBe(10000) // Max 10s for server
    expect(getRetryDelay(networkError, 10)).toBe(30000) // Max 30s for network
  })
})



import axios, { isAxiosError } from "axios"
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest"

import type { SearchQueryItem } from "@/baml_client/types"

// Type definition for mock AxiosError used in tests
type MockAxiosError = Error & {
  response?: {
    status: number
    data: Record
    headers?: Record
  }
  code?: string
}
import {
  ExaConfigError,
  isExaAuthError,
  isExaClientError,
  isExaNetworkError,
  isExaParsingError,
  isExaRateLimitError,
  isExaServerError,
} from "@/lib/utils/exaSearchErrors"
import { executeExaSearch } from "@/lib/utils/exaSearchUtil"

// axios is already mocked in setupTests.ts
const mockedAxios = axios as unknown as {
  post: ReturnType
}
const mockedIsAxiosError = isAxiosError as unknown as ReturnType

// Get the actual API key from .env.test (loaded by Vitest config)
const EXA_API_KEY_FROM_ENV = process.env.EXA_API_KEY

beforeEach(() => {
  vi.clearAllMocks()
})

afterEach(() => {
  vi.clearAllMocks()
})

describe("executeExaSearch", () => {
  it("should load EXA_API_KEY from environment variables", () => {
    // Verify that the API key is loaded from .env.test
    expect(EXA_API_KEY_FROM_ENV).toBeDefined()
    expect(typeof EXA_API_KEY_FROM_ENV).toBe("string")
    expect(EXA_API_KEY_FROM_ENV).not.toBe("")
  })

  const mockSearchQuery: SearchQueryItem = {
    query_string: "legal precedents for copyright infringement",
    expected_information: [
      "Recent court cases involving copyright infringement",
      "Key legal arguments in copyright cases",
    ],
  }

  const mockExaResponse = {
    data: {
      results: [
        {
          id: "exa-1234",
          url: "https://example.com/article1",
          title: "Copyright Infringement Case Study",
          author: "John Doe",
          score: 0.95,
          publishedDate: "2023-04-15",
          text: "This is the full text of the article about copyright infringement.",
          highlights: [
            "Important highlight 1 about copyright.",
            "Another important point about infringement.",
          ],
        },
        {
          id: "exa-5678",
          url: "https://example.com/article2",
          title: "Legal Analysis of Recent Copyright Cases",
          author: "Jane Smith",
          score: 0.85,
          publishedDate: "2023-03-10",
          text: "Full text discussing recent copyright cases and their implications.",
          highlights: [
            "Key legal precedent established in case X.",
            "The court ruled that...",
          ],
        },
      ],
      autopromptString: "Modified search query for better results",
      requestId: "req-9876",
    },
  }

  it("should throw ExaConfigError with empty EXA_API_KEY", async () => {
    // Mock the environment variable to be undefined
    const originalEnv = process.env.EXA_API_KEY
    // biome-ignore lint/performance/noDelete: Required for proper environment variable testing
    delete process.env.EXA_API_KEY

    try {
      await expect(executeExaSearch(mockSearchQuery)).rejects.toThrow(
        ExaConfigError
      )
      await expect(executeExaSearch(mockSearchQuery)).rejects.toThrow(
        "EXA_API_KEY environment variable is not set"
      )
    } finally {
      // Restore the original environment variable
      if (originalEnv !== undefined) {
        process.env.EXA_API_KEY = originalEnv
      }
    }
  })

  it("should correctly build request body based on parameters", async () => {
    // Setup
    mockedAxios.post.mockResolvedValueOnce(mockExaResponse)

    // Execute
    await executeExaSearch(mockSearchQuery, 10, true, 5)

    // Verify
    expect(mockedAxios.post).toHaveBeenCalledTimes(1)

    const mockCall = mockedAxios.post.mock.calls[0]
    if (!mockCall) {
      throw new Error("Expected mock call")
    }
    const [url, requestBody, config] = mockCall

    // Check URL
    expect(url).toBe("https://api.exa.ai/search")

    // Check request body
    expect(requestBody).toEqual({
      query: mockSearchQuery.query_string,
      num_results: 10,
      type: "auto",
      contents: {
        text: true,
        highlights: {
          num_sentences: 5,
        },
      },
    })

    // Check config
    expect(config?.headers).toEqual({
      "Content-Type": "application/json",
      "x-api-key": EXA_API_KEY_FROM_ENV,
    })
  })

  it("should build request body with different numResults values", async () => {
    // Setup
    mockedAxios.post.mockResolvedValueOnce(mockExaResponse)

    // Execute with different numResults
    await executeExaSearch(mockSearchQuery, 3, true, 2)

    // Verify
    const mockCall = mockedAxios.post.mock.calls[0]
    if (!mockCall) {
      throw new Error("Expected mock call")
    }
    const [, requestBody] = mockCall
    expect(requestBody.num_results).toBe(3)
    expect(requestBody.contents.highlights.num_sentences).toBe(2)
  })

  it("should build request body with fetchFullText false", async () => {
    // Setup
    mockedAxios.post.mockResolvedValueOnce(mockExaResponse)

    // Execute with fetchFullText false
    await executeExaSearch(mockSearchQuery, 5, false, 3)

    // Verify
    const mockCall = mockedAxios.post.mock.calls[0]
    if (!mockCall) {
      throw new Error("Expected mock call")
    }
    const [, requestBody] = mockCall
    expect(requestBody.contents.text).toBeUndefined()
    expect(requestBody.contents.highlights.num_sentences).toBe(3)
  })

  it("should correctly transform Exa API response to BAML SearchResultItem[]", async () => {
    // Setup
    mockedAxios.post.mockResolvedValueOnce(mockExaResponse)
    vi.spyOn(console, "log").mockImplementation(() => {
      // Silence console logs during test
    })

    // Set a fixed date for testing
    const fixedDate = new Date("2023-05-01T12:00:00Z")
    vi.spyOn(global, "Date").mockImplementation(
      () => fixedDate as unknown as Date
