})



import { describe, expect, it } from "vitest"

import { cn } from "@/lib/utils"

describe("cn utility function", () => {
  it("merges class names correctly", () => {
    const result = cn("class1", "class2")
    expect(result).toBe("class1 class2")
  })

  it("handles conditional classes", () => {
    const condition = true
    const result = cn("base-class", condition && "conditional-class")
    expect(result).toBe("base-class conditional-class")

    const falseCondition = false
    const result2 = cn("base-class", falseCondition && "conditional-class")
    expect(result2).toBe("base-class")
  })

  it("handles array of classes", () => {
    const result = cn(["class1", "class2"])
    expect(result).toBe("class1 class2")
  })

  it("handles object syntax", () => {
    const result = cn({
      "base-class": true,
      "disabled-class": false,
      "active-class": true,
    })
    expect(result).toBe("base-class active-class")
  })

  it("handles mixed inputs", () => {
    const result = cn(
      "base-class",
      { "conditional-class": true, "disabled-class": false },
      ["array-class1", "array-class2"]
    )
    expect(result).toBe(
      "base-class conditional-class array-class1 array-class2"
    )
  })

  it("handles undefined and null values", () => {
    const result = cn("base-class", undefined, null, "valid-class")
    expect(result).toBe("base-class valid-class")
  })

  it("handles Tailwind class merging", () => {
    // Tailwind classes with different variants of the same property
    const result = cn("p-2", "p-4", "sm:p-6")
    // The p-4 should override p-2, but sm:p-6 should be preserved
    expect(result).toBe("p-4 sm:p-6")
  })

  it("handles conflicting Tailwind classes based on specificity", () => {
    // Test that tailwind-merge correctly handles conflicting classes
    const result = cn("text-red-500", "text-blue-500")
    // The later class should win
    expect(result).toBe("text-blue-500")
  })
})



/**
 * Tests for API testing helper utilities
 * These tests validate the conditional test execution logic
 *
 * Note: This file uses the delete operator for environment variables, which is
 * the correct approach for test isolation. Environment variables in Node.js
 * are strings, and setting them to undefined converts to "undefined" string
 * which is still truthy. The delete operator is required to actually remove
 * them from process.env for proper test isolation.
 */

import { describe, expect, it, vi } from "vitest"

import {
  hasRequiredApiKeys,
  isCI,
  skipIfMissingApiKeys,
  skipInCiIfMissingApiKeys,
} from "../test-utils"
import { API_KEYS, logApiKeyStatus } from "./api-test-helpers"

describe("API Testing Utilities", () => {
  describe("hasRequiredApiKeys", () => {
    it("should return false for missing API keys", () => {
      expect(hasRequiredApiKeys(["DEFINITELY_MISSING_KEY"])).toBe(false)
    })

    it("should return false for empty API keys", () => {
      const originalKey = process.env.TEST_EMPTY_KEY
      process.env.TEST_EMPTY_KEY = ""

      expect(hasRequiredApiKeys(["TEST_EMPTY_KEY"])).toBe(false)

      // Restore
      if (originalKey !== undefined) {
        process.env.TEST_EMPTY_KEY = originalKey
      } else {
        process.env.TEST_EMPTY_KEY = undefined
      }
    })

    it("should return false for placeholder API keys", () => {
      const originalKey = process.env.TEST_PLACEHOLDER_KEY
      process.env.TEST_PLACEHOLDER_KEY = "[YOUR_API_KEY]"

      expect(hasRequiredApiKeys(["TEST_PLACEHOLDER_KEY"])).toBe(false)

      // Restore
      if (originalKey !== undefined) {
        process.env.TEST_PLACEHOLDER_KEY = originalKey
      } else {
        process.env.TEST_PLACEHOLDER_KEY = undefined
      }
    })

    it("should return false for masked API keys", () => {
      const originalKey = process.env.TEST_MASKED_KEY
      process.env.TEST_MASKED_KEY = "****"

      expect(hasRequiredApiKeys(["TEST_MASKED_KEY"])).toBe(false)

      // Restore
      if (originalKey !== undefined) {
        process.env.TEST_MASKED_KEY = originalKey
      } else {
        process.env.TEST_MASKED_KEY = undefined
      }
    })

    it("should return true for valid API keys", () => {
      const originalKey = process.env.TEST_VALID_KEY
      process.env.TEST_VALID_KEY = "sk-valid-api-key-123"

      expect(hasRequiredApiKeys(["TEST_VALID_KEY"])).toBe(true)

      // Restore
      if (originalKey !== undefined) {
        process.env.TEST_VALID_KEY = originalKey
      } else {
        process.env.TEST_VALID_KEY = undefined
      }
    })

    it("should return true for empty array", () => {
      expect(hasRequiredApiKeys([])).toBe(true)
    })

    it("should check all keys in array", () => {
      const originalKey1 = process.env.TEST_KEY_1
      const originalKey2 = process.env.TEST_KEY_2

      process.env.TEST_KEY_1 = "valid-key-1"
      process.env.TEST_KEY_2 = "" // Invalid

      expect(hasRequiredApiKeys(["TEST_KEY_1", "TEST_KEY_2"])).toBe(false)

      process.env.TEST_KEY_2 = "valid-key-2"
      expect(hasRequiredApiKeys(["TEST_KEY_1", "TEST_KEY_2"])).toBe(true)

      // Restore
      if (originalKey1 !== undefined) {
        process.env.TEST_KEY_1 = originalKey1
      } else {
        process.env.TEST_KEY_1 = undefined
      }
      if (originalKey2 !== undefined) {
        process.env.TEST_KEY_2 = originalKey2
      } else {
        process.env.TEST_KEY_2 = undefined
      }
    })
  })

  describe("skipIfMissingApiKeys", () => {
    it("should return false when keys are missing", () => {
      const consoleSpy = vi.spyOn(console, "warn").mockImplementation(() => {
        // Mock implementation
      })

      const result = skipIfMissingApiKeys(["DEFINITELY_MISSING_KEY"], "Test")

      expect(result).toBe(false)
      expect(consoleSpy).toHaveBeenCalledWith(
        'Skipping "Test" - Missing API keys: DEFINITELY_MISSING_KEY'
      )

      consoleSpy.mockRestore()
    })

    it("should return true when all keys are available", () => {
      const originalKey = process.env.TEST_AVAILABLE_KEY
      const consoleSpy = vi.spyOn(console, "warn").mockImplementation(() => {
        // Mock implementation
      })

      process.env.TEST_AVAILABLE_KEY = "valid-key"

      const result = skipIfMissingApiKeys(["TEST_AVAILABLE_KEY"], "Test")

      expect(result).toBe(true)
      expect(consoleSpy).not.toHaveBeenCalled()

      // Restore
      if (originalKey !== undefined) {
        process.env.TEST_AVAILABLE_KEY = originalKey
      } else {
        process.env.TEST_AVAILABLE_KEY = undefined
      }
      consoleSpy.mockRestore()
    })

    it("should handle missing test name", () => {
      const consoleSpy = vi.spyOn(console, "warn").mockImplementation(() => {
        // Mock implementation
      })

      const result = skipIfMissingApiKeys(["MISSING_KEY"])

      expect(result).toBe(false)
      expect(consoleSpy).toHaveBeenCalledWith(
        "Skipping test - Missing API keys: MISSING_KEY"
      )

      consoleSpy.mockRestore()
    })
  })

  describe("isCI", () => {
    it("should detect CI environment variables", () => {
      // Save all CI-related environment variables
      const ciEnvVars = [
        "CI",
        "GITHUB_ACTIONS",
        "GITLAB_CI",
        "CIRCLECI",
        "TRAVIS",
        "BUILDKITE",
        "VERCEL",
      ]
      const originalEnvVars = ciEnvVars.reduce(
        (acc, key) => {
          acc[key] = process.env[key]
          return acc
        },
        {} as Record
      )

      // Clear all CI environment variables first
      for (const key of ciEnvVars) {
        delete process.env[key]
      }

      // Test CI=true
      process.env.CI = "true"
      expect(isCI()).toBe(true)

      // Clear and test GitHub Actions
      // biome-ignore lint/performance/noDelete: Required for proper environment variable testing
      delete process.env.CI
      process.env.GITHUB_ACTIONS = "true"
      expect(isCI()).toBe(true)

      // Test no CI - clear all CI variables
      // biome-ignore lint/performance/noDelete: Required for proper environment variable testing
      delete process.env.GITHUB_ACTIONS
      expect(isCI()).toBe(false)

      // Restore all original environment variables
      for (const [key, value] of Object.entries(originalEnvVars)) {
        if (value !== undefined) {
          process.env[key] = value
        } else {
          delete process.env[key]
        }
      }
    })
  })

  describe("skipInCiIfMissingApiKeys", () => {
    it("should skip in CI when keys are missing", () => {
      // Save all CI-related environment variables
      const ciEnvVars = [
        "CI",
        "GITHUB_ACTIONS",
        "GITLAB_CI",
        "CIRCLECI",
        "TRAVIS",
        "BUILDKITE",
        "VERCEL",
      ]
      const originalEnvVars = ciEnvVars.reduce(
        (acc, key) => {
          acc[key] = process.env[key]
          return acc
        },
        {} as Record
      )

      const consoleSpy = vi.spyOn(console, "warn").mockImplementation(() => {
        // Mock implementation
      })

      // Clear all CI environment variables first, then set CI=true
      for (const key of ciEnvVars) {
        delete process.env[key]
      }
      process.env.CI = "true"

      const result = skipInCiIfMissingApiKeys(["MISSING_KEY"], "CI Test")

      expect(result).toBe(false)
      expect(consoleSpy).toHaveBeenCalled()

      // Restore all original environment variables
      for (const [key, value] of Object.entries(originalEnvVars)) {
        if (value !== undefined) {
          process.env[key] = value
        } else {
          delete process.env[key]
        }
      }
      consoleSpy.mockRestore()
    })

    it("should not skip in local development", () => {
      // Save all CI-related environment variables
      const ciEnvVars = [
        "CI",
        "GITHUB_ACTIONS",
        "GITLAB_CI",
        "CIRCLECI",
        "TRAVIS",
        "BUILDKITE",
        "VERCEL",
      ]
      const originalEnvVars = ciEnvVars.reduce(
        (acc, key) => {
          acc[key] = process.env[key]
          return acc
        },
        {} as Record
      )

      const consoleSpy = vi.spyOn(console, "warn").mockImplementation(() => {
        // Mock implementation
      })

      // Clear all CI environment variables to simulate local development
      for (const key of ciEnvVars) {
        delete process.env[key]
      }

      const result = skipInCiIfMissingApiKeys(["MISSING_KEY"], "Local Test")

      expect(result).toBe(true)
      expect(consoleSpy).not.toHaveBeenCalled()

      // Restore all original environment variables
      for (const [key, value] of Object.entries(originalEnvVars)) {
        if (value !== undefined) {
          process.env[key] = value
        } else {
          delete process.env[key]
        }
      }
      consoleSpy.mockRestore()
    })
  })

  describe("API_KEYS constant", () => {
    it("should have correct structure", () => {
      expect(API_KEYS.GOOGLE_AI).toEqual(["GOOGLE_API_KEY"])
      expect(API_KEYS.OPENAI).toEqual(["OPENAI_API_KEY"])
      expect(API_KEYS.EXA_SEARCH).toEqual(["EXA_API_KEY"])
      expect(API_KEYS.ALL_LLM).toContain("GOOGLE_API_KEY")
      expect(API_KEYS.ALL_LLM).toContain("OPENAI_API_KEY")
      expect(API_KEYS.ALL_LLM).toContain("ANTHROPIC_API_KEY")
    })

    it("should have string arrays", () => {
      for (const keys of Object.values(API_KEYS)) {
        expect(Array.isArray(keys)).toBe(true)
        for (const key of keys) {
          expect(typeof key).toBe("string")
        }
      }
    })
  })

  describe("logApiKeyStatus", () => {
    it("should log without throwing", () => {
      const consoleSpy = vi.spyOn(console, "log").mockImplementation(() => {
        // Mock implementation
      })

      expect(() => logApiKeyStatus(["GOOGLE_API_KEY"])).not.toThrow()
      expect(consoleSpy).toHaveBeenCalled()

      consoleSpy.mockRestore()
    })

    it("should handle empty key array", () => {
      const consoleSpy = vi.spyOn(console, "log").mockImplementation(() => {
        // Mock implementation
      })

      expect(() => logApiKeyStatus([])).not.toThrow()

      consoleSpy.mockRestore()
    })
  })
})



import { describe, it } from "vitest"

import {
  isCI,
  skipIfMissingApiKeys,
  skipInCiIfMissingApiKeys,
} from "../test-utils"

/**
 * Available API providers and their required environment variables
 */
export const API_KEYS = {
  GOOGLE_AI: ["GOOGLE_API_KEY"] as string[],
  OPENAI: ["OPENAI_API_KEY"] as string[],
  ANTHROPIC: ["ANTHROPIC_API_KEY"] as string[],
  XAI: ["XAI_API_KEY"] as string[],
  GROQ: ["GROQ_API_KEY"] as string[],
  EXA_SEARCH: ["EXA_API_KEY"] as string[],
  TAVILY_SEARCH: ["TAVILY_API_KEY"] as string[],
  LINKUP_SEARCH: ["LINKUP_API_KEY"] as string[],
  ALL_LLM: [
    "GOOGLE_API_KEY",
    "OPENAI_API_KEY",
    "ANTHROPIC_API_KEY",
  ] as string[],
  ALL_SEARCH: ["EXA_API_KEY", "TAVILY_API_KEY", "LINKUP_API_KEY"] as string[],
}

/**
 * Test runner that conditionally skips based on API key availability
 * @param testName - Name of the test
 * @param requiredApiKeys - Array of required API key environment variable names
 * @param testFn - Test function to run if keys are available
 * @param options - Configuration options
 */
export const itWithApiKeys = (
  testName: string,
  requiredApiKeys: string[],
  testFn: () => void | Promise,
  options: {
    skipInCI?: boolean
    timeout?: number
    only?: boolean
    skip?: boolean
  } = {}
) => {
  const { skipInCI = false, timeout, only = false, skip = false } = options

  const shouldSkip =
    skip ||
    (skipInCI
      ? !skipInCiIfMissingApiKeys(requiredApiKeys, testName)
      : !skipIfMissingApiKeys(requiredApiKeys, testName))

  const testRunner = only ? it.only : shouldSkip ? it.skip : it

  const titleWithRequirements = `${testName} [requires: ${requiredApiKeys.join(", ")}]`

  return testRunner(titleWithRequirements, testFn, timeout)
}

/**
 * Describe block that conditionally skips based on API key availability
 * @param suiteName - Name of the test suite
 * @param requiredApiKeys - Array of required API key environment variable names
 * @param suiteFn - Test suite function to run if keys are available
 * @param options - Configuration options
 */
export const describeWithApiKeys = (
  suiteName: string,
  requiredApiKeys: string[],
  suiteFn: () => void,
  options: {
    skipInCI?: boolean
    only?: boolean
    skip?: boolean
  } = {}
) => {
  const { skipInCI = false, only = false, skip = false } = options

  const shouldSkip =
    skip ||
    (skipInCI
      ? !skipInCiIfMissingApiKeys(requiredApiKeys, suiteName)
      : !skipIfMissingApiKeys(requiredApiKeys, suiteName))

  const describeRunner = only
    ? describe.only
    : shouldSkip
      ? describe.skip
      : describe

  const titleWithRequirements = `${suiteName} [requires: ${requiredApiKeys.join(", ")}]`

  return describeRunner(titleWithRequirements, suiteFn)
}

/**
 * Test runner specifically for BAML function tests
 * @param functionName - BAML function name
 * @param requiredApiKeys - Array of required API key environment variable names
 * @param testFn - Test function to run if keys are available
 * @param options - Configuration options
 */
export const itBamlFunction = (
  functionName: string,
  requiredApiKeys: string[],
  testFn: () => void | Promise,
  options: {
    skipInCI?: boolean
    timeout?: number
  } = {}
) => {
  const testTitle = `BAML function ${functionName}`

  return itWithApiKeys(testTitle, requiredApiKeys, testFn, {
    skipInCI: true, // Default to skipping BAML tests in CI
    timeout: 30000, // Default 30s timeout for BAML tests
    ...options,
  })
}

/**
 * Test runner specifically for E2E tests requiring API calls
 * @param testName - Name of the E2E test
 * @param requiredApiKeys - Array of required API key environment variable names
 * @param testFn - Test function to run if keys are available
 * @param options - Configuration options
 */
export const itE2eWithApi = (
  testName: string,
  requiredApiKeys: string[],
  testFn: () => void | Promise,
  options: {
    skipInCI?: boolean
    timeout?: number
  } = {}
) => {
  const e2eTestTitle = `E2E: ${testName}`

  return itWithApiKeys(e2eTestTitle, requiredApiKeys, testFn, {
    skipInCI: false, // E2E tests should run in CI if keys are available
    timeout: 60000, // Default 60s timeout for E2E tests
    ...options,
  })
}

/**
 * Utility to log API key availability status
 * Useful for debugging test skipping behavior
 */
export const logApiKeyStatus = (
  keys: string[] = Object.values(API_KEYS).flat()
) => {
  console.log("=== API Key Status ===")
  console.log(`CI Environment: ${isCI()}`)

  const uniqueKeys = [...new Set(keys)]
  for (const key of uniqueKeys) {
    const value = process.env[key]
    const hasKey =
      value &&
      value.trim() !== "" &&
      !value.includes("[YOUR_") &&
      !value.includes("****")
    const status = hasKey ? "✅ Available" : "❌ Missing/Invalid"
    console.log(`${key}: ${status}`)
  }
  console.log("====================")
}

/**
 * Custom matchers for API-dependent tests
 */
export const apiTestMatchers = {
  /**
   * Assert that a test was skipped due to missing API keys
   */
  toBeSkippedDueToMissingApiKeys: (
    _received: unknown,
    expectedKeys: string[]
  ) => {
    const hasKeys = expectedKeys.every(key => {
      const value = process.env[key]
      return (
        value &&
        value.trim() !== "" &&
        !value.includes("[YOUR_") &&
        !value.includes("****")
      )
    })

    return {
      pass: !hasKeys,
      message: () =>
        hasKeys
          ? `Expected test to be skipped due to missing API keys, but all keys are available: ${expectedKeys.join(", ")}`
          : `Test correctly skipped due to missing API keys: ${expectedKeys.join(", ")}`,
    }
  },
}

/**
 * Mock environment for testing API key validation logic
 */
export const withMockApiKeys = (
  mockKeys: Record,
  testFn: () => void
) => {
  const originalEnv = { ...process.env }

  // Set mock keys
  for (const [key, value] of Object.entries(mockKeys)) {
    process.env[key] = value
  }

  try {
    testFn()
  } finally {
    // Restore original environment
    process.env = originalEnv
  }
}

/**
 * Common test patterns for API-dependent functionality
 */
export const createApiTestSuite = (config: {
  suiteName: string
  requiredKeys: string[]
  mockTests: Array<{
    name: string
    fn: () => void | Promise
  }>
  realApiTests: Array<{
    name: string
    fn: () => void | Promise
    timeout?: number
  }>
}) => {
  const { suiteName, requiredKeys, mockTests, realApiTests } = config

  const mockedSuiteTitle = `${suiteName} (Mocked)`
  const realApiSuiteTitle = `${suiteName} (Real API)`

  describe(mockedSuiteTitle, () => {
    for (const test of mockTests) {
      it(test.name, test.fn)
    }
  })

  describeWithApiKeys(realApiSuiteTitle, requiredKeys, () => {
    for (const test of realApiTests) {
      itWithApiKeys(test.name, requiredKeys, test.fn, {
        skipInCI: true,
        timeout: test.timeout || 30000,
      })
    }
  })
}



# Claude Code Devtools Blueprint: TDD-Driven Development with Static Analysis

## Executive Summary

This blueprint provides Claude Code instances with a systematic approach to development using test-driven development (TDD) principles combined with comprehensive static analysis validation. The methodology emphasizes atomic changes, immediate validation, and continuous quality assurance through automated tooling.

## Core Philosophy

**"Code with Confidence, Validate Immediately, Progress Measurably"**

Every code change, no matter how small, must be validated through static analysis before proceeding. This approach catches issues at their source, maintains code quality, and ensures continuous progress toward objectives.

## Devtools Ecosystem Overview

### Quality Gates Hierarchy

```
Level 1: Format & Syntax     → bun run format
Level 2: Type Safety         → bun run typecheck
Level 3: Code Quality        → bun run lint
Level 4: Test Coverage       → bun run test
Level 5: Strict Validation   → bun run typecheck:strict
Level 6: Bundle Analysis     → bun run size
Level 7: Dependency Health   → bun run deps:check
```

### Validation Workflows

#### Quick Validation (Every Change)
```bash
bun run validate:quick  # typecheck + lint + format
```

#### Full Validation (Before Completion)
```bash
bun run validate:full   # All quality gates + tests + E2E + bundle analysis
```

#### CI Pipeline Simulation
```bash
bun run ci             # Complete validation suite for production readiness
```

## TDD Development Workflow

### Phase 1: Test-First Development

#### 1.1 Pre-Development Setup
```bash
# Verify clean starting state
bun run validate:quick
bun run test
bun run typecov
```

**Validation Rule**: All tools must pass before beginning new work.

#### 1.2 Write Failing Test
```bash
# Create test file or extend existing test
# Example: __tests__/components/new-feature.test.tsx

# Immediate validation
bun run typecheck      # Ensure test compiles
bun run test           # Verify test fails as expected
bun run lint           # Check test code quality
```

**Validation Checkpoint**: Test must fail for the right reason, with clean TypeScript compilation.

#### 1.3 Minimal Implementation
```bash
# Implement minimal code to make test pass
# Focus on single responsibility

# Atomic validation cycle
bun run typecheck      # Type safety first
bun run format         # Code formatting
bun run test           # Verify test passes
bun run lint           # Code quality
```

**Validation Rule**: Each atomic change must pass all Level 1-4 quality gates.

### Phase 2: Incremental Enhancement

#### 2.1 Feature Expansion
```typescript
// For each new capability:
// 1. Write test for new behavior
// 2. Run validation cycle
// 3. Implement minimal code
// 4. Run validation cycle
// 5. Refactor if needed
// 6. Run validation cycle
```

#### 2.2 Validation Pattern
```bash
# After every meaningful change (5-10 lines of code)
bun run typecheck && bun run test && bun run lint

# After every component/function completion
bun run validate:quick

# After every feature completion
bun run validate:full
```

### Phase 3: Quality Assurance

#### 3.1 Strict Validation
```bash
# Before marking work complete
bun run typecheck:strict    # Strictest TypeScript validation
bun run lint:strict         # Zero-warning linting
bun run test:coverage       # Verify test coverage
bun run typecov            # Type coverage analysis
```

#### 3.2 Production Readiness
```bash
# Final validation before completion
bun run size               # Bundle size analysis
bun run deps:check         # Dependency architecture
bun run audit              # Security vulnerabilities
bun run ci                 # Full CI simulation
```

## Tool-Specific Usage Guidelines

### TypeScript Validation

#### Immediate Type Checking
```bash
# After every file save/change
bun run typecheck
```

**When to Use**:
- After adding new types/interfaces
- After changing function signatures
- After importing new dependencies
- Before committing any change

#### Strict Mode Validation
```bash
# Before feature completion
bun run typecheck:strict
```

**When to Use**:
- Before marking tasks complete
- When aiming for maximum type safety
- Before production deployment

**Common Fixes**:
- Explicit type annotations for callback parameters
- Proper optional property handling
- `null` vs `undefined` alignment with external APIs

### Code Quality (Biome)

#### Continuous Linting
```bash
# After implementing logic
bun run lint
```

**Auto-Fix Pattern**:
```bash
bun run lint:fix           # Auto-fix simple issues
bun run lint               # Verify remaining issues
# Fix remaining issues manually
bun run lint:strict        # Zero-warning validation
```

**Common Issues & Solutions**:
- React Testing Library best practices
- Accessibility requirements
- Performance anti-patterns
- Security vulnerabilities

### Code Formatting

#### Format-First Approach
```bash
# Before reviewing code
bun run format             # Format code directly
```

**Integration Pattern**:
- Format after implementing each function
- Check formatting before validation cycles
- Auto-format before committing

### Testing Strategy

#### Test-Driven Cycle
```bash
# Red: Write failing test
bun run test

# Green: Make test pass
bun run test

# Refactor: Improve code
bun run test
bun run test:coverage      # Verify coverage
```

#### Test Categories
```bash
bun run test               # Unit & integration tests
bun run test:e2e          # End-to-end tests
bun run test:coverage     # Coverage analysis
```

### Bundle Analysis

#### Performance Monitoring
```bash
# After adding dependencies
bun run size

# For detailed analysis
bun run size:debug
bun run bundle:analyze
```

**Size Thresholds**:
- Main chunks: < 50KB
- Page chunks: < 100KB
- Layout chunks: < 50KB

### Dependency Management

#### Continuous Monitoring
```bash
# After dependency changes
bun run deps:check
bun run audit

# Automated cleanup
bun run knip              # Remove unused dependencies
```

## Atomic Change Methodology

### Change Size Guidelines

#### Micro-Changes (1-3 lines)
```bash
# Validation: Type check only
bun run typecheck
```

#### Small Changes (4-20 lines)
```bash
# Validation: Quick cycle
bun run typecheck && bun run test
```

#### Medium Changes (21-100 lines)
```bash
# Validation: Standard cycle
bun run validate:quick
```

#### Large Changes (100+ lines)
```bash
# Validation: Full cycle
bun run validate:full
```

### Validation Frequency

#### Every Code Change
1. Save file
2. Run `bun run typecheck`
3. Fix any type errors immediately
4. Continue development

#### Every Function/Component
1. Complete implementation
2. Run `bun run validate:quick`
3. Fix all issues before proceeding
4. Add/update tests

#### Every Feature
1. Complete feature implementation
2. Run `bun run validate:full`
3. Address all quality issues
4. Verify E2E functionality

## Error Resolution Patterns

### TypeScript Errors

#### Approach
1. **Understand the Error**: Read TypeScript error messages carefully
2. **Fix Root Cause**: Don't use `any` as a quick fix
3. **Validate Fix**: Ensure `typecheck:strict` passes
4. **Test Impact**: Run tests to verify functionality

#### Common Patterns
```typescript
// Instead of any, use proper typing
const handler = (event: React.ChangeEvent) => { ... }

// Handle optional properties correctly
const props = {
  ...baseProps,
  ...(optionalValue && { optionalProp: optionalValue })
}

// Use null for external API compatibility
const result = externalApiResult ?? null; // not undefined
```

### Biome Errors

#### Systematic Resolution
1. **Auto-fix first**: `bun run lint:fix`
2. **Understand remaining**: Read rule documentation
3. **Fix properly**: Follow best practices, don't disable rules
4. **Verify**: `bun run lint:strict`

#### Priority Order
1. Security issues (high priority)
2. Accessibility violations (high priority)
3. Performance issues (medium priority)
4. Style/consistency (low priority)

### Test Failures

#### Debug Process
1. **Isolate**: Run single test file
2. **Debug**: Add console.logs or use debugger
3. **Fix**: Address root cause
4. **Verify**: Run full test suite
5. **Coverage**: Check test coverage impact

## Performance Optimization Guidelines

### Bundle Size Management

#### Monitoring
```bash
# After every dependency addition
bun run size

# Weekly review
bun run size:analyze       # Generate detailed report
```

#### Optimization Strategies
1. **Lazy Loading**: Use dynamic imports for large components
2. **Tree Shaking**: Ensure proper ESM imports
3. **Bundle Splitting**: Optimize webpack chunks
4. **Dependency Audit**: Remove unused packages with `knip`

### Type Coverage Optimization

#### Target: 100% for Source Files
```bash
# Monitor coverage
bun run typecov

# Identify gaps
bun run typecov --detail
```

#### Improvement Strategies
1. **Explicit Types**: Add type annotations for complex expressions
2. **Generic Constraints**: Use proper generic bounds
3. **External Types**: Define types for external APIs
4. **Utility Types**: Leverage TypeScript utility types

## Automation Integration

### Pre-commit Hooks

#### Recommended Setup
```bash
# Auto-run before commit
bun run validate:quick
bun run test
```

#### Commit Message Validation
```bash
# Ensure conventional commits
bun run commitlint
```

### CI/CD Integration

#### Pull Request Pipeline
```bash
bun run validate:full      # Complete validation
bun run test:e2e          # E2E testing
bun run audit             # Security check
```

#### Deployment Pipeline
```bash
bun run ci                # Full CI validation
bun run build             # Production build
bun run size              # Bundle analysis
```

## Advanced Patterns

### Complex Feature Development

#### Multi-Component Features
1. **Plan**: Break down into atomic components
2. **Test Structure**: Create test hierarchy
3. **Incremental**: Build component by component
4. **Integration**: Validate component interactions
5. **E2E**: Test complete user workflows

#### API Integration
1. **Types First**: Define API types
2. **Mock Implementation**: Create mock for testing
3. **Test Cases**: Cover all scenarios
4. **Real Integration**: Replace mocks gradually
5. **Error Handling**: Test failure scenarios

### Refactoring Workflows

#### Safe Refactoring
1. **Test Coverage**: Ensure comprehensive tests
2. **Type Safety**: Use TypeScript for confidence
3. **Incremental**: Make small, verifiable changes
4. **Validation**: Run full test suite after each step
5. **Regression**: Test original functionality

## Troubleshooting Guide

### Common Issues

#### "Tests Pass But App Breaks"
1. Check E2E tests: `bun run test:e2e`
2. Verify type safety: `bun run typecheck:strict`
3. Check bundle issues: `bun run size`
4. Review dependencies: `bun run deps:check`

#### "TypeScript Errors in CI But Not Locally"
1. Clear cache: `rm -rf .next node_modules/.cache`
2. Reinstall: `bun install`
3. Check versions: `bun run typecheck:strict`
4. Verify environment: Check Node.js and bun versions

#### "Performance Regression"
1. Bundle analysis: `bun run size:analyze`
2. Dependency audit: `bun run deps:check`
3. Test performance: Check test execution time
4. Profile build: Use Next.js analyzer

### Recovery Procedures

#### From Broken State
1. **Assess**: `bun run validate:quick`
2. **Prioritize**: Fix TypeScript errors first
3. **Incremental**: Fix one issue type at a time
4. **Validate**: Run tools after each fix
5. **Test**: Ensure functionality intact

#### From Dependency Issues
1. **Audit**: `bun run audit`
2. **Clean**: `bun run knip`
3. **Update**: `bun run audit:fix`
4. **Validate**: `bun run validate:full`

## Best Practices Summary

### Golden Rules

1. **Never Skip Validation**: Every change must pass quality gates
2. **Fix Forward**: Address issues immediately, don't accumulate debt
3. **Test First**: Write tests before implementation
4. **Type Safety**: Maintain strict TypeScript standards
5. **Incremental Progress**: Make small, verifiable changes

### Quality Metrics

#### Minimum Thresholds
- TypeScript: 100% compilation success
- Type Coverage: >98.9% for source files
- Test Coverage: >90% for new code
- Lint: Zero errors in strict mode
- Bundle Size: Within defined limits

#### Excellence Targets
- Type Coverage: 100% for source files
- Test Coverage: >95%
- Performance: <100ms build changes
- Security: Zero vulnerabilities

### Time Investment

#### Development Phases
- **Setup**: 5% (Initial validation)
- **Implementation**: 70% (Code + immediate validation)
- **Quality Assurance**: 20% (Comprehensive validation)
- **Documentation**: 5% (Update docs/tests)

#### ROI Expectations
- **Short-term**: Catch issues early (save debugging time)
- **Medium-term**: Maintain code quality (reduce technical debt)
- **Long-term**: Enable confident refactoring (increase velocity)

## Conclusion

This blueprint ensures that Claude Code instances can maintain the highest code quality standards while developing efficiently through TDD principles. The key is immediate validation of every change, comprehensive tool utilization, and systematic quality assurance.

By following this methodology, development becomes predictable, reliable, and maintains consistent quality throughout the project lifecycle. The investment in static analysis and testing pays dividends in reduced debugging time, increased confidence in changes, and long-term maintainability.

Remember: **The goal is not just working code, but provably correct, maintainable, and high-quality code that passes all static analysis checks.**



