//docs.boundaryml.com/docs/snippets/clients/retry\nretry_policy Constant {\n  max_retries 3\n  // Strategy is optional\n  strategy {\n    type constant_delay\n    delay_ms 200\n  }\n}\n\nretry_policy TestSafely {\n  max_retries 1\n  strategy {\n    type exponential_backoff\n    delay_ms 200\n    multiplier 1.5\n    max_delay_ms 10000\n  }\n}\n",
  "core_loop.baml": "// For assessing research sufficiency and planning next steps\nenum NextActionType {\n  REFINE_QUERIES\n  NEW_QUERIES\n  DEEPER_ANALYSIS_OF_EXISTING_DOCS\n  GENERATE_REPORT\n  REQUEST_HUMAN_REVIEW\n}\n\n// 4. Assess Research Sufficiency and Plan Next Iteration\n//    Purpose: Decides if more research is needed or if the agent can proceed to report generation.\nfunction AssessResearchAndPlanNextSteps(\n  original_legal_question: string,\n  initial_queries_analysis: LegalQueryAnalysis,\n  current_synthesis: OverallSynthesis?\n) -> ResearchAssessment {\n  client DecidesNextStep // Using a potentially faster/cheaper client for decision-making\n  prompt #\"\nYou are a managing legal researcher overseeing a research project. Your task is to review the progress, assess if the current information is sufficient to answer the original legal question, and plan the next steps. Follow these instructions carefully:\n\n1. Review the original legal question:\n\n    {{ original_legal_question }}\n\n\n2. Review the initial query generation reasoning:\n\n    1. Analyze Legal Question Summary: {{ initial_queries_analysis.reasoning.analyze_legal_question.summary | default(\"N/A\") }}\n    2. Consider Legal Principles Summary: {{ initial_queries_analysis.reasoning.consider_relevant_legal_principles.summary | default(\"N/A\") }}\n    3. Formulate Queries Strategy Summary: {{ initial_queries_analysis.reasoning.formulate_search_queries_strategy.summary | default(\"N/A\") }}\n    4. Specify Expected Info Strategy Summary: {{ initial_queries_analysis.reasoning.specify_expected_information_strategy.summary | default(\"N/A\") }}\n    5. Ensure Coverage Strategy Summary: {{ initial_queries_analysis.reasoning.ensure_comprehensive_coverage_strategy.summary | default(\"N/A\") }}\n\n\n3. Review the current synthesis of findings:\n\n    {% if current_synthesis %}\n      Key Synthesized Topics:\n      {% for topic in current_synthesis.key_synthesized_topics %}\n      {#\n        Removed | truncate(150).\n        If topic.synthesis is too long, the OverallSynthesis should ideally contain\n        a briefer summary per topic, or your application code should prepare this.\n        Alternatively, instruct the SynthesizeAllFindings function to make its topic.synthesis concise.\n        For this assessment prompt, a very short excerpt or just the title might be enough.\n      #}\n      - {{ topic.topic_title }}: (Confidence: {{ topic.confidence_score }}/10)\n        Summary: {{ topic.synthesis | default(\"No synthesis content.\") }}\n        Supporting Documents: {{ topic.supporting_document_ids | join(\", \") }}\n      {% else %}\n      No topics synthesized yet.\n      {% endfor %}\n      Unanswered Aspects: {{ current_synthesis.unanswered_aspects | default([\"None identified.\"]) | join(\", \") }}\n      Emerging Questions: {{ current_synthesis.emerging_questions | default([\"None identified.\"]) | join(\", \") }}\n    {% else %}\n      No synthesis has been performed yet. This is likely the first assessment after initial query generation or if previous searches yielded no relevant documents.\n    {% endif %}\n\n\n4. Assess Sufficiency:\nMANDATORY: You MUST evaluate each criterion explicitly and state YES or NO for each:\n\na) Confidence Scores: Are they 7+ for key topics? Answer: [YES/NO]\nb) Unanswered Aspects: Is the list empty or contains only very minor items? Answer: [YES/NO]\nc) Emerging Questions: Is the list empty or contains only non-critical items? Answer: [YES/NO]\nd) Actionable Information: Does the synthesis provide practical, actionable information to answer the core question? Answer: [YES/NO]\n\nSTRICT RULE: If ALL FOUR answers are \"YES\", you MUST set is_sufficient = true and next_action = \"GENERATE_REPORT\". \nDO NOT second-guess this rule. DO NOT add additional requirements beyond these four criteria.\n\nCRITICAL SUFFICIENCY STANDARD: You are REQUIRED to follow ONLY the 4-step criteria above. Do NOT add additional legal analysis beyond those 4 criteria.\n\nIf the 4 criteria are met (confidence 7+, empty unanswered aspects, empty emerging questions, actionable info), the research IS SUFFICIENT regardless of what additional details you might personally want as a lawyer.\n\nEXAMPLES OF SUFFICIENT SCENARIOS:\n- Confidence scores 8-9/10 + empty unanswered_aspects + empty emerging_questions + core question answered = SUFFICIENT\n- Basic legal rule provided + application guidance + high confidence = SUFFICIENT\n\nFORBIDDEN: Do NOT require additional exceptions, edge cases, tolling doctrines, or comprehensive coverage if the 4 criteria are already met. Your job is assessment, not legal practice.\n\n5. Summarize Assessment:\nBriefly explain your reasoning for sufficiency/insufficiency. This will be used to populate the assessment_summary field.\n\n6. Identify Gaps:\nIf not sufficient, list the specific information gaps. This will be used to populate the identified_gaps field.\n\n7. Recommend Next Action:\nFollow this MANDATORY decision tree step-by-step:\n\nSTEP A: Check for extensive research indicators\nLook at the Initial Query Generation Reasoning summaries. Do they contain ANY of these phrases: \"incomplete\", \"missing\", \"partial coverage\", \"current research incomplete\", \"need comprehensive\", \"homestead focus but missing\", or similar?\n- If YES → Go to STEP B\n- If NO → Go to STEP C\n\nSTEP B: Extensive research detected - LIMITED OPTIONS ONLY\nYou may ONLY choose from:\n- DEEPER_ANALYSIS_OF_EXISTING_DOCS (if Supporting Documents exist)\n- REQUEST_HUMAN_REVIEW (if complexity suggests research limits reached)\n- GENERATE_REPORT (if somehow sufficient despite gaps)\nYOU ARE FORBIDDEN from choosing REFINE_QUERIES or NEW_QUERIES\n\nSTEP C: Normal decision process\nFirst, evaluate the initial query effectiveness:\n\nCHECK: Do the Initial Query Generation Reasoning summaries contain any of these ineffectiveness indicators?\n- \"too broad\", \"ineffective\", \"completely missed\", \"wrong approach\", \"fundamentally flawed\", \"inappropriate strategy\"\n- If YES → Choose NEW_QUERIES\n\nCHECK: Do the Initial Query Generation Reasoning summaries suggest minor improvements needed?\n- \"need adjustment\", \"slightly off\", \"partially effective\", \"good direction but\", \"mostly correct but\"\n- If YES → Choose REFINE_QUERIES\n\nIf neither above applies, choose from:\n- DEEPER_ANALYSIS_OF_EXISTING_DOCS: Choose this if Supporting Documents are listed AND any of these conditions: (1) confidence scores below 6/10, (2) synthesis mentions \"surface-level\" or similar phrases, (3) reasoning mentions \"need detailed analysis\", (4) extensive research has been conducted but gaps remain and documents exist for re-analysis. Do not choose this if the question involves complexity requiring specialized expertise.\n- GENERATE_REPORT: If the information gathered is sufficient.\n- REQUEST_HUMAN_REVIEW: Prioritize this for complex multi-jurisdictional issues, conflicting legal frameworks, strategic business decisions, or when initial reasoning indicates \"complexity beyond automated analysis\". Also choose this when extensive research has been conducted but significant gaps remain and complexity suggests automated research has reached its limits.\n\n8. Provide Conditional Details:\n- If next_action is REFINE_QUERIES or NEW_QUERIES, provide a list of SearchQueryItem objects for suggested_queries_for_refinement.\n- If next_action is DEEPER_ANALYSIS_OF_EXISTING_DOCS, provide specific document IDs from the \"Supporting Documents\" for document_ids_for_deeper_analysis.\n- For other next_action types, omit these fields.\n\n9. Reasoning:\nProvide your detailed thought process for this assessment and plan. Explain why you chose the next action and how you identified gaps or formulated new queries/plans. Use the ReasoningStep structure for each of these steps:\na) analyze_legal_question\nb) consider_relevant_legal_principles\nc) formulate_search_queries_strategy\nd) specify_expected_information_strategy\ne) ensure_comprehensive_coverage_strategy\n\n10. Output Format:\nProvide your final output in JSON format using the following schema:\n\n{{ ctx.output_format }}\n\nYour final output should consist of only the JSON object on the schema described above. Do not include any additional text, explanations, or formatting outside of this JSON structure.\n  \"#\n}",
  "core_loop.test.baml": "// ----- Comprehensive Test Cases for AssessResearchAndPlanNextSteps -----\n\ntest AssessmentWithNoSynthesis {\n  functions [AssessResearchAndPlanNextSteps]\n  args {\n    original_legal_question \"What is the statute of limitations for personal injury in California?\"\n    initial_queries_analysis {\n      reasoning {\n        analyze_legal_question { summary \"Initial analysis of personal injury limitation question\" }\n        consider_relevant_legal_principles { summary \"Identified statute of limitations principles\" }\n        formulate_search_queries_strategy { summary \"Strategy for statutory and case law research\" }\n        specify_expected_information_strategy { summary \"Expected California-specific limitation periods\" }\n        ensure_comprehensive_coverage_strategy { summary \"Comprehensive coverage of limitation rules\" }\n      }\n      search_queries [\n        {\n          query_string \"California personal injury statute of limitations CCP 335.1\"\n          expected_information [\"Statutory limitation period\", \"Accrual rules\", \"Discovery rule exceptions\"]\n        }\n      ]\n    }\n    current_synthesis none\n  }\n  // First pass assessment should identify need for research\n  @@assert( {{ this.is_sufficient == false }} )\n  @@assert( {{ (this.assessment_summary or \"\") | length > 10 }} )\n  @@assert( {{ this.next_action in [\"NEW_QUERIES\", \"REFINE_QUERIES\"] }} )\n  // Should provide suggested queries for first research\n  @@assert( {{ this.suggested_queries_for_refinement != none and ((this.suggested_queries_for_refinement or []) | length > 0) }} )\n  // document_ids_for_deeper_analysis should be none for NEW_QUERIES action\n  @@assert( {{ this.reasoning.analyze_legal_question.summary | length > 0 }} )\n  @@assert( {{ this.reasoning.consider_relevant_legal_principles.summary | length > 0 }} )\n  @@assert( {{ this.reasoning.formulate_search_queries_strategy.summary | length > 0 }} )\n}\n\ntest AssessmentSufficientForReport {\n  functions [AssessResearchAndPlanNextSteps]\n  args {\n    original_legal_question \"What is the statute of limitations for personal injury in California?\"\n    initial_queries_analysis {\n      reasoning {\n        analyze_legal_question { summary \"Comprehensive analysis of personal injury limitation periods\" }\n        consider_relevant_legal_principles { summary \"Accrual rules and discovery doctrine\" }\n        formulate_search_queries_strategy { summary \"Statutory and case law research\" }\n        specify_expected_information_strategy { summary \"Time limits and exceptions\" }\n        ensure_comprehensive_coverage_strategy { summary \"Multiple sources and perspectives\" }\n      }\n      search_queries [\n        {\n          query_string \"California personal injury statute of limitations CCP 335.1\"\n          expected_information [\"Statutory limitation period\", \"Accrual rules\"]\n        },\n        {\n          query_string \"discovery rule personal injury California accrual\"\n          expected_information [\"Discovery rule application\", \"Latent injury cases\"]\n        }\n      ]\n    }\n    current_synthesis {\n      key_synthesized_topics [\n        {\n          topic_title \"California Personal Injury Statute of Limitations\"\n          synthesis \"California Code of Civil Procedure § 335.1 establishes a 2-year statute of limitations for personal injury actions. The limitation period begins when the cause of action accrues, which is generally when the injury occurs. However, the discovery rule applies in cases where the injury is not immediately apparent, starting the clock when the plaintiff discovers or reasonably should have discovered the injury and its cause.\"\n          confidence_score 9\n          supporting_document_ids [\"statute_335\", \"case_discovery_rule\", \"appellate_interpretation\"]\n        },\n        {\n          topic_title \"Discovery Rule Application\"\n          synthesis \"Courts apply the discovery rule to delay accrual of the statute of limitations until the plaintiff knows or should know of the injury and its wrongful cause. This rule is particularly important in medical malpractice, toxic exposure, and latent injury cases.\"\n          confidence_score 8\n          supporting_document_ids [\"case_discovery_rule\", \"medical_malpractice_cases\", \"toxic_exposure_precedent\"]\n        }\n      ]\n      unanswered_aspects []\n      emerging_questions []\n      reasoning {\n        analyze_legal_question { summary \"Comprehensive analysis of limitation periods\" }\n        consider_relevant_legal_principles { summary \"Accrual rules and discovery doctrine\" }\n        formulate_search_queries_strategy { summary \"Statutory and case law research\" }\n        specify_expected_information_strategy { summary \"Time limits and exceptions\" }\n        ensure_comprehensive_coverage_strategy { summary \"Multiple sources and perspectives\" }\n      }\n    }\n  }\n  @@assert( {{ this.is_sufficient == true }} )\n  @@assert( {{ this.next_action == \"GENERATE_REPORT\" }} )\n  @@assert( {{ (this.assessment_summary or \"\") | length > 10 }} )\n  // Should not provide refinement suggestions when sufficient\n  @@assert( {{ not this.suggested_queries_for_refinement }} )\n  // document_ids_for_deeper_analysis should be none for GENERATE_REPORT action\n  // Assessment should reference the synthesis quality\n  @@assert( {{ (\"sufficient\" in ((this.assessment_summary or \"\") | lower)) or (\"comprehensive\" in ((this.assessment_summary or \"\") | lower)) or (\"adequate\" in ((this.assessment_summary or \"\") | lower)) }} )\n}\n\ntest AssessmentNeedsRefinement {\n  functions [AssessResearchAndPlanNextSteps]\n  args {\n    original_legal_question \"What are the requirements for adverse possession in Texas?\"\n    initial_queries_analysis {\n      reasoning {\n        analyze_legal_question { summary \"General adverse possession principles identified\" }\n        consider_relevant_legal_principles { summary \"Common law elements found\" }\n        formulate_search_queries_strategy { summary \"Broad search conducted\" }\n        specify_expected_information_strategy { summary \"Texas-specific information lacking\" }\n        ensure_comprehensive_coverage_strategy { summary \"Need jurisdiction-specific research\" }\n      }\n      search_queries [\n        {\n          query_string \"adverse possession elements requirements\"\n          expected_information [\"General elements\", \"Common law principles\"]\n        },\n        {\n          query_string \"adverse possession statute of limitations\"\n          expected_information [\"Time periods\", \"Statutory requirements\"]\n        }\n      ]\n    }\n    current_synthesis {\n      key_synthesized_topics [\n        {\n          topic_title \"Basic Adverse Possession Elements\"\n          synthesis \"Adverse possession generally requires open, notorious, exclusive, and continuous possession for a statutory period. However, specific requirements may vary by jurisdiction.\"\n          confidence_score 4\n          supporting_document_ids [\"general_law_overview\"]\n        }\n      ]\n      unanswered_aspects [\"Texas-specific statutory requirements\", \"Required time period in Texas\", \"Good faith vs. bad faith requirements\", \"Tacking provisions\", \"Payment of taxes requirement\"]\n      emerging_questions [\"What is the exact statutory period in Texas?\", \"Are there different rules for rural vs. urban property?\", \"What constitutes 'open and notorious' use in Texas?\"]\n      reasoning {\n        analyze_legal_question { summary \"General adverse possession principles identified\" }\n        consider_relevant_legal_principles { summary \"Common law elements found\" }\n        formulate_search_queries_strategy { summary \"Broad search conducted\" }\n        specify_expected_information_strategy { summary \"Texas-specific information lacking\" }\n        ensure_comprehensive_coverage_strategy { summary \"Need jurisdiction-specific research\" }\n      }\n    }\n  }\n  @@assert( {{ this.is_sufficient == false }} )\n  @@assert( {{ this.next_action == \"REFINE_QUERIES\" }} )\n  @@assert( {{ (this.assessment_summary or \"\") | length > 10 }} )\n  // Should provide Texas-specific refinement suggestions\n  @@assert( {{ this.suggested_queries_for_refinement != none and ((this.suggested_queries_for_refinement or []) | length > 0) }} )\n  @@assert( {{ (\"texas\" in (((this.suggested_queries_for_refinement or []) | join(\" \")) | lower)) }} )\n  // document_ids_for_deeper_analysis should be none for REFINE_QUERIES action\n  // Assessment should identify the gaps\n  @@assert( {{ (\"texas\" in ((this.assessment_summary or \"\") | lower)) or (\"specific\" in ((this.assessment_summary or \"\") | lower)) or (\"jurisdiction\" in ((this.assessment_summary or \"\") | lower)) }} )\n}\n\ntest AssessmentNeedsNewQueries {\n  functions [AssessResearchAndPlanNextSteps]\n  args {\n    original_legal_question \"What are the elements of a valid prenuptial agreement in New York?\"\n    initial_queries_analysis {\n      reasoning {\n        analyze_legal_question { summary \"Basic contract law principles identified\" }\n        consider_relevant_legal_principles { summary \"General formation requirements found\" }\n        formulate_search_queries_strategy { summary \"Initial search too broad\" }\n        specify_expected_information_strategy { summary \"State-specific requirements needed\" }\n        ensure_comprehensive_coverage_strategy { summary \"Current queries ineffective for jurisdiction\" }\n      }\n      search_queries [\n        {\n          query_string \"prenuptial agreement requirements contract law\"\n          expected_information [\"General contract principles\", \"Formation requirements\"]\n        },\n        {\n          query_string \"prenup validity contract formation\"\n          expected_information [\"Validity standards\", \"Formation elements\"]\n        }\n      ]\n    }\n    current_synthesis {\n      key_synthesized_topics [\n        {\n          topic_title \"General Contract Principles\"\n          synthesis \"Prenuptial agreements are contracts and must meet basic contract formation requirements including offer, acceptance, and consideration.\"\n          confidence_score 6\n          supporting_document_ids [\"general_contract_law\"]\n        }\n      ]\n      unanswered_aspects [\"New York specific statutory requirements\", \"Financial disclosure requirements\", \"Independent counsel requirements\", \"Unconscionability standards\", \"Property division restrictions\"]\n      emerging_questions [\"What are the formal execution requirements in New York?\", \"Are there mandatory waiting periods?\", \"What disclosures must be made?\"]\n      reasoning {\n        analyze_legal_question { summary \"Basic contract law principles identified\" }\n        consider_relevant_legal_principles { summary \"General formation requirements found\" }\n        formulate_search_queries_strategy { summary \"Initial search too broad\" }\n        specify_expected_information_strategy { summary \"State-specific requirements needed\" }\n        ensure_comprehensive_coverage_strategy { summary \"Current queries ineffective for jurisdiction\" }\n      }\n    }\n  }\n  @@assert( {{ this.is_sufficient == false }} )\n  @@assert( {{ this.next_action == \"NEW_QUERIES\" }} )\n  @@assert( {{ (this.assessment_summary or \"\") | length > 10 }} )\n  // Should suggest completely new query approach\n  @@assert( {{ this.suggested_queries_for_refinement != none and ((this.suggested_queries_for_refinement or []) | length > 0) }} )\n  @@assert( {{ (\"new york\" in (((this.suggested_queries_for_refinement or []) | join(\" \")) | lower)) }} )\n  // document_ids_for_deeper_analysis should be none for NEW_QUERIES action\n  // Assessment should identify ineffective current approach\n  @@assert( {{ (\"new\" in ((this.assessment_summary or \"\") | lower)) or (\"different\" in ((this.assessment_summary or \"\") | lower)) or (\"specific\" in ((this.assessment_summary or \"\") | lower)) }} )\n}\n\ntest AssessmentNeedsDeeperAnalysis {\n  functions [AssessResearchAndPlanNextSteps]\n  args {\n    original_legal_question \"What is the standard for attorney-client privilege waiver in federal court?\"\n    initial_queries_analysis {\n      reasoning {\n        analyze_legal_question { summary \"Privilege waiver concept identified\" }\n        consider_relevant_legal_principles { summary \"General waiver principles found\" }\n        formulate_search_queries_strategy { summary \"Located relevant documents\" }\n        specify_expected_information_strategy { summary \"Need detailed analysis of standards\" }\n        ensure_comprehensive_coverage_strategy { summary \"Current documents lack sufficient detail\" }\n      }\n      search_queries [\n        {\n          query_string \"attorney client privilege waiver federal court\"\n          expected_information [\"Federal waiver standards\", \"Court interpretations\"]\n        },\n        {\n          query_string \"privilege waiver inadvertent disclosure\"\n          expected_information [\"Inadvertent disclosure rules\", \"Protective measures\"]\n        }\n      ]\n    }\n    current_synthesis {\n      key_synthesized_topics [\n        {\n          topic_title \"Privilege Waiver Standards\"\n          synthesis \"Federal courts apply various tests for privilege waiver, but documents provide only surface-level summaries without detailed analysis of the controlling standards.\"\n          confidence_score 3\n          supporting_document_ids [\"case_summary_123\", \"brief_overview_456\", \"practice_guide_789\"]\n        }\n      ]\n      unanswered_aspects [\"Specific test elements\", \"Subject matter waiver scope\", \"Inadvertent disclosure standards\", \"Claw-back provisions effectiveness\"]\n      emerging_questions [\"What are the exact elements of the controlling federal test?\", \"How do courts determine scope of subject matter waiver?\"]\n      reasoning {\n        analyze_legal_question { summary \"Privilege waiver concept identified\" }\n        consider_relevant_legal_principles { summary \"General waiver principles found\" }\n        formulate_search_queries_strategy { summary \"Located relevant documents\" }\n        specify_expected_information_strategy { summary \"Need detailed analysis of standards\" }\n        ensure_comprehensive_coverage_strategy { summary \"Current documents lack sufficient detail\" }\n      }\n    }\n  }\n  @@assert( {{ this.is_sufficient == false }} )\n  @@assert( {{ this.next_action == \"DEEPER_ANALYSIS_OF_EXISTING_DOCS\" }} )\n  @@assert( {{ (this.assessment_summary or \"\") | length > 10 }} )\n  // Should identify specific documents for deeper analysis\n  @@assert( {{ this.document_ids_for_deeper_analysis != none and ((this.document_ids_for_deeper_analysis or []) | length > 0) }} )\n  @@assert( {{ (\"case_summary_123\" in (this.document_ids_for_deeper_analysis or [])) }} )\n  @@assert( {{ not this.suggested_queries_for_refinement }} ) // Focus on analysis, not new queries\n  // Assessment should identify need for more detailed examination\n  @@assert( {{ (\"deeper\" in ((this.assessment_summary or \"\") | lower)) or (\"detail\" in ((this.assessment_summary or \"\") | lower)) or (\"analysis\" in ((this.assessment_summary or \"\") | lower)) or (\"examine\" in ((this.assessment_summary or \"\") | lower)) }} )\n}\n\ntest AssessmentRequiresHumanReview {\n  functions [AssessResearchAndPlanNextSteps]\n  args {\n    original_legal_question \"How should we structure this complex international joint venture to minimize tax exposure while ensuring regulatory compliance across multiple jurisdictions?\"\n    initial_queries_analysis {\n      reasoning {\n        analyze_legal_question { summary \"Highly complex multi-jurisdictional question\" }\n        consider_relevant_legal_principles { summary \"Multiple conflicting legal frameworks\" }\n        formulate_search_queries_strategy { summary \"Research reveals complexity beyond automated analysis\" }\n        specify_expected_information_strategy { summary \"Requires specialized expertise\" }\n        ensure_comprehensive_coverage_strategy { summary \"Automated research insufficient for strategic decisions\" }\n      }\n      search_queries [\n        {\n          query_string \"international joint venture tax structure\"\n          expected_information [\"Tax structuring options\", \"Cross-border implications\"]\n        },\n        {\n          query_string \"cross border regulatory compliance\"\n          expected_information [\"Regulatory frameworks\", \"Compliance requirements\"]\n        }\n      ]\n    }\n    current_synthesis {\n      key_synthesized_topics [\n        {\n          topic_title \"International Tax Considerations\"\n          synthesis \"Tax implications vary significantly across jurisdictions with conflicting requirements and uncertain regulatory interpretations.\"\n          confidence_score 2\n          supporting_document_ids [\"tax_guide_intl\", \"conflicting_regs\"]\n        },\n        {\n          topic_title \"Regulatory Compliance Issues\"\n          synthesis \"Multiple regulatory frameworks apply with potentially conflicting requirements that may require specialized analysis.\"\n          confidence_score 2\n          supporting_document_ids [\"reg_framework_a\", \"reg_framework_b\"]\n        }\n      ]\n      unanswered_aspects [\"Specific jurisdictional requirements\", \"Tax treaty implications\", \"Regulatory approval processes\", \"Compliance coordination mechanisms\"]\n      emerging_questions [\"Which jurisdiction should be primary?\", \"How do conflicting regulations get resolved?\", \"What are the optimal structuring alternatives?\"]\n      reasoning {\n        analyze_legal_question { summary \"Highly complex multi-jurisdictional question\" }\n        consider_relevant_legal_principles { summary \"Multiple conflicting legal frameworks\" }\n        formulate_search_queries_strategy { summary \"Research reveals complexity beyond automated analysis\" }\n        specify_expected_information_strategy { summary \"Requires specialized expertise\" }\n        ensure_comprehensive_coverage_strategy { summary \"Automated research insufficient for strategic decisions\" }\n      }\n    }\n  }\n  @@assert( {{ this.is_sufficient == false }} )\n  @@assert( {{ this.next_action == \"REQUEST_HUMAN_REVIEW\" }} )\n  @@assert( {{ (this.assessment_summary or \"\") | length > 10 }} )\n  // Should not provide additional queries or analysis suggestions\n  @@assert( {{ not this.suggested_queries_for_refinement }} )\n  // document_ids_for_deeper_analysis should be none for REQUEST_HUMAN_REVIEW action\n  // Assessment should identify complexity requiring human expertise\n  @@assert( {{ (\"complex\" in ((this.assessment_summary or \"\") | lower)) or (\"expert\" in ((this.assessment_summary or \"\") | lower)) or (\"human\" in ((this.assessment_summary or \"\") | lower)) or (\"specialized\" in ((this.assessment_summary or \"\") | lower)) or (\"review\" in ((this.assessment_summary or \"\") | lower)) }} )\n}\n\ntest AssessmentWithExtensiveQueryHistory {\n  functions [AssessResearchAndPlanNextSteps]\n  args {\n    original_legal_question \"What are the bankruptcy exemptions available to individuals in Florida?\"\n    initial_queries_analysis {\n      reasoning {\n        analyze_legal_question { summary \"Partial coverage of exemption types\" }\n        consider_relevant_legal_principles { summary \"Federal and state exemption interplay\" }\n        formulate_search_queries_strategy { summary \"Homestead focus but missing other categories\" }\n        specify_expected_information_strategy { summary \"Need comprehensive exemption catalog\" }\n        ensure_comprehensive_coverage_strategy { summary \"Current research incomplete\" }\n      }\n      search_queries [\n        {\n          query_string \"Florida bankruptcy exemptions individual debtor\"\n          expected_information [\"Available exemptions\", \"Individual debtor rights\"]\n        },\n        {\n          query_string \"Florida homestead exemption bankruptcy\"\n          expected_information [\"Homestead protections\", \"Property exemptions\"]\n        }\n      ]\n    }\n    current_synthesis {\n      key_synthesized_topics [\n        {\n          topic_title \"Florida Homestead Exemption\"\n          synthesis \"Florida provides unlimited homestead exemption for primary residence, subject to certain acreage limitations.\"\n          confidence_score 7\n          supporting_document_ids [\"fl_const_homestead\", \"bankruptcy_code_522\"]\n        }\n      ]\n      unanswered_aspects [\"Personal property exemptions\", \"Wage exemptions\", \"Retirement account protections\", \"Vehicle exemptions\"]\n      emerging_questions [\"What personal property can be exempted?\", \"Are there income limitations on exemptions?\"]\n      reasoning {\n        analyze_legal_question { summary \"Partial coverage of exemption types\" }\n        consider_relevant_legal_principles { summary \"Federal and state exemption interplay\" }\n        formulate_search_queries_strategy { summary \"Homestead focus but missing other categories\" }\n        specify_expected_information_strategy { summary \"Need comprehensive exemption catalog\" }\n        ensure_comprehensive_coverage_strategy { summary \"Current research incomplete\" }\n      }\n    }\n  }\n  // With extensive query history, should either be sufficient or need human review\n  @@assert( {{ this.next_action in [\"GENERATE_REPORT\", \"REQUEST_HUMAN_REVIEW\", \"DEEPER_ANALYSIS_OF_EXISTING_DOCS\"] }} )\n  @@assert( {{ (this.assessment_summary or \"\") | length > 10 }} )\n  // Should recognize extensive prior research effort\n  @@assert( {{ (\"extensive\" in ((this.assessment_summary or \"\") | lower)) or (\"multiple\" in ((this.assessment_summary or \"\") | lower)) or (\"previous\" in ((this.assessment_summary or \"\") | lower)) or (\"prior\" in ((this.assessment_summary or \"\") | lower)) }} )\n  // If not sufficient, should explain why despite extensive research\n  @@assert( {{ this.is_sufficient == true or ((\"despite\" in ((this.assessment_summary or \"\") | lower)) or (\"although\" in ((this.assessment_summary or \"\") | lower)) or (\"extensive\" in ((this.assessment_summary or \"\") | lower))) }} )\n}\n\n// NEW TEST: Live data scenario - Employment discrimination with comprehensive synthesis\ntest AssessLiveEmploymentDiscriminationResearch {\n  functions [AssessResearchAndPlanNextSteps]\n  args {\n    original_legal_question \"What constitutes 'adverse employment action' under Title VII discrimination law?\"\n    initial_queries_analysis {\n      reasoning {\n        analyze_legal_question { summary \"The legal question is about what constitutes an 'adverse employment action' under Title VII. Key issues are: defining the term; identifying specific actions that qualify; and understanding any differing interpretations by courts.\" }\n        consider_relevant_legal_principles { summary \"Relevant legal principles include: statutory interpretation of Title VII; the role of the EEOC in enforcement; case law interpreting 'adverse employment action'; and the potential for varying interpretations across jurisdictions.\" }\n        formulate_search_queries_strategy { summary \"Search queries would use exact phrases and boolean operators. Examples: 'adverse employment action' AND 'Title VII'; 'adverse employment action' AND 'definition'.\" }\n        specify_expected_information_strategy { summary \"Each query is expected to yield: 1) Statutory definitions and interpretations from Title VII, 2) Examples of adverse employment actions from EEOC guidance, 3) Case law defining and interpreting the term 'adverse employment action'.\" }\n        ensure_comprehensive_coverage_strategy { summary \"The queries would be designed to cover all aspects of the legal question and avoid redundancy by: starting with broad searches and then refining them; using a combination of keywords and phrases.\" }\n      }\n      search_queries [\n        {\n          query_string \"employment discrimination Title VII adverse action\"\n          expected_information [\"adverse employment action definition\", \"Title VII cases\", \"discrimination law\"]\n        },\n        {\n          query_string \"tangible employment action Title VII harassment\"\n          expected_information [\"tangible employment action\", \"employer liability\", \"harassment defense\"]\n        }\n      ]\n    }\n    current_synthesis {\n      key_synthesized_topics [\n        {\n          topic_title \"Definition and Scope of Adverse Employment Action\"\n          synthesis \"The primary focus of the documents revolves around defining 'adverse employment action' under Title VII. The term is not explicitly defined in Title VII but is established through judicial interpretations. It highlights that discrimination is prohibited concerning the 'terms, conditions, or privileges of employment.' Examples of adverse actions include firing, demotion, pay cuts, failure to promote, and hiring. Some courts require a 'materially adverse consequence.'\"\n          confidence_score 9\n          supporting_document_ids [\"https://natlawreview.com/article/what-counts-adverse-employment-action-discrimination-and-retaliation-cases\", \"https://www.law.cornell.edu/wex/tangible_employment_action\"]\n        },\n        {\n          topic_title \"Distinction between Adverse Employment Action and Tangible Employment Action\"\n          synthesis \"A crucial divergence emerges between the concepts of 'adverse employment action' and 'tangible employment action'. Tangible employment action represents a subset, specifically a significant change, of adverse employment actions. Tangible employment actions, like hiring, firing, or significant benefit changes, are pivotal in determining employer liability, especially in cases of supervisor misconduct.\"\n          confidence_score 8\n          supporting_document_ids [\"https://natlawreview.com/article/what-counts-adverse-employment-action-discrimination-and-retaliation-cases\", \"https://www.law.cornell.edu/wex/tangible_employment_action\"]\n        },\n        {\n          topic_title \"Examples and Application of Adverse Employment Action\"\n          synthesis \"Both documents provide examples of what constitutes adverse employment action. The EEOC lists firing, demotion, pay cuts, failure to promote, and hiring decisions as examples. Other examples include denial of a raise, loss of negotiated benefits, threats of discharge, and withholding promotions. The documents also provide examples of actions that do not constitute such actions, creating more contrast and guidance.\"\n          confidence_score 9\n          supporting_document_ids [\"https://natlawreview.com/article/what-counts-adverse-employment-action-discrimination-and-retaliation-cases\", \"https://www.law.cornell.edu/wex/tangible_employment_action\"]\n        }\n      ]\n      unanswered_aspects [\"Specific judicial standards or tests used by courts to determine 'materially adverse consequence' of an action\", \"Jurisdictional variations in how adverse employment action is interpreted\"]\n      emerging_questions [\"What is the prevailing standard courts use to determine whether an action has a 'materially adverse consequence?'\", \"How do courts differentiate between actions considered merely annoying or inconvenient versus those with materially adverse consequences?\"]\n      reasoning {\n        analyze_legal_question { summary \"The legal question is about the definition of 'adverse employment action' under Title VII discrimination law. The key issues involve understanding the scope and range of actions covered by this term, and how it is determined in court.\" }\n        consider_relevant_legal_principles { summary \"Relevant legal principles include Title VII's prohibition against discrimination and court interpretations of 'adverse employment action.' The analysis should also consider the distinction between adverse employment action and tangible employment action.\" }\n        formulate_search_queries_strategy { summary \"Initial search queries will focus on the definition and examples of 'adverse employment action' under Title VII. Boolean operators (AND, OR) and exact phrase searching will be used.\" }\n        specify_expected_information_strategy { summary \"Each query will target specific types of information: statutes, case law, legal principles, and expert analysis. The search will expect to find definitions, examples, court precedents, and commentary on the legal standards.\" }\n        ensure_comprehensive_coverage_strategy { summary \"To ensure comprehensive coverage, the search will begin with broad queries and then narrow down to specific areas, such as the standards used to determine 'materially adverse consequence' and potential jurisdictional variations.\" }\n      }\n    }\n  }\n  @@assert( {{ this.is_sufficient == true }} )\n  @@assert( {{ this.next_action == \"GENERATE_REPORT\" }} )\n  @@assert( {{ (this.assessment_summary or \"\") | length > 20 }} )\n  // Should recognize comprehensive coverage of the topic\n  @@assert( {{ (\"comprehensive\" in ((this.assessment_summary or \"\") | lower)) or (\"sufficient\" in ((this.assessment_summary or \"\") | lower)) or (\"adequate\" in ((this.assessment_summary or \"\") | lower)) }} )\n  // Should not suggest additional queries when sufficient\n  @@assert( {{ not this.suggested_queries_for_refinement }} )\n  @@assert( {{ not this.document_ids_for_deeper_analysis }} )\n  // Should recognize high confidence in synthesis topics\n  @@assert( {{ (\"high confidence\" in ((this.assessment_summary or \"\") | lower)) or (\"strong\" in ((this.assessment_summary or \"\") | lower)) or (\"reliable\" in ((this.assessment_summary or \"\") | lower)) }} )\n}\n\n// NEW TEST: Live data scenario - Patent law with some gaps requiring refinement\ntest AssessLivePatentResearchNeedsRefinement {\n  functions [AssessResearchAndPlanNextSteps]\n  args {\n    original_legal_question \"What are the requirements for a valid patent application under 35 U.S.C. § 112?\"\n    initial_queries_analysis {\n      reasoning {\n        analyze_legal_question { summary \"The legal question focuses on the requirements for a valid patent application under 35 U.S.C. § 112. This involves identifying the specific elements that must be present in a patent application to meet the statutory requirements for patentability.\" }\n        consider_relevant_legal_principles { summary \"Relevant legal principles include statutory interpretation of 35 U.S.C. § 112, which addresses the specification requirements, as well as any relevant case law that interprets and applies this statute.\" }\n        formulate_search_queries_strategy { summary \"Given the focus on 35 U.S.C. § 112, the search query strategy would prioritize direct references to the statute and its specific subsections.\" }\n        specify_expected_information_strategy { summary \"The search queries are expected to yield information that precisely explains the different elements of 35 U.S.C. § 112, including the written description, enablement, best mode, and claims requirements.\" }\n        ensure_comprehensive_coverage_strategy { summary \"To ensure comprehensive coverage, the search strategy would begin with a broad search of 35 U.S.C. § 112, then narrow the focus by searching for each individual component.\" }\n      }\n      search_queries [\n        {\n          query_string \"patent application requirements 35 USC 112 specification\"\n          expected_information [\"patent specification requirements\", \"USPTO guidelines\", \"written description\"]\n        }\n      ]\n    }\n    current_synthesis {\n      key_synthesized_topics [\n        {\n          topic_title \"Section 112 Requirements Overview\"\n          synthesis \"Section 112 of the Patent Act, codified as 35 U.S.C. § 112, outlines the requirements for the specification of a patent application. The document explains the four key components: written description, enablement requirement, best mode requirement, and claims. However, the synthesis lacks detailed case law analysis and practical application examples.\"\n          confidence_score 7\n          supporting_document_ids [\"https://vernalaw.com/why-is-section-112-of-the-patent-act-important/\"]\n        }\n      ]\n      unanswered_aspects [\"Case law interpretations of each requirement\", \"Practical examples of compliant specifications\", \"Common rejection reasons under 35 U.S.C. § 112\", \"Recent changes in USPTO examination guidelines\"]\n      emerging_questions [\"How do courts interpret the 'written description' requirement in practice?\", \"What are common pitfalls in drafting claims under Section 112?\", \"How has the America Invents Act affected best mode requirements?\"]\n      reasoning {\n        analyze_legal_question { summary \"The legal question focuses on the requirements for a valid patent application under 35 U.S.C. § 112. This involves identifying the specific elements that must be present in a patent application to meet the statutory requirements for patentability.\" }\n        consider_relevant_legal_principles { summary \"Relevant legal principles include statutory interpretation of 35 U.S.C. § 112, which addresses the specification requirements, as well as any relevant case law that interprets and applies this statute.\" }\n        formulate_search_queries_strategy { summary \"Given the focus on 35 U.S.C. § 112, the search query strategy would prioritize direct references to the statute and its specific subsections.\" }\n        specify_expected_information_strategy { summary \"The search queries are expected to yield information that precisely explains the different elements of 35 U.S.C. § 112, including the written description, enablement, best mode, and claims requirements.\" }\n        ensure_comprehensive_coverage_strategy { summary \"To ensure comprehensive coverage, the search strategy would begin with a broad search of 35 U.S.C. § 112, then narrow the focus by searching for each individual component.\" }\n      }\n    }\n  }\n  @@assert( {{ this.is_sufficient == false }} )\n  @@assert( {{ this.next_action == \"REFINE_QUERIES\" }} )\n  @@assert( {{ (this.assessment_summary or \"\") | length > 20 }} )\n  // Should identify need for case law and practical examples\n  @@assert( {{ (\"case law\" in ((this.assessment_summary or \"\") | lower)) or (\"practical\" in ((this.assessment_summary or \"\") | lower)) or (\"examples\" in ((this.assessment_summary or \"\") | lower)) }} )\n  // Should provide refined queries targeting case law and applications\n  @@assert( {{ this.suggested_queries_for_refinement != none and ((this.suggested_queries_for_refinement or []) | length > 0) }} )\n  @@assert( {{ (\"case\" in (((this.suggested_queries_for_refinement or []) | join(\" \")) | lower)) or (\"precedent\" in (((this.suggested_queries_for_refinement or []) | join(\" \")) | lower)) }} )\n  @@assert( {{ not this.document_ids_for_deeper_analysis }} )\n  // Should recognize statutory coverage but need for judicial interpretation\n  @@assert( {{ (\"statutory\" in ((this.assessment_summary or \"\") | lower)) or (\"judicial\" in ((this.assessment_summary or \"\") | lower)) or (\"interpretation\" in ((this.assessment_summary or \"\") | lower)) }} )\n}",
  "functions/1-generate_queries.baml": "// 1. GenerateInitialSearchQueries\n//    Input: legal_question: string\n//    Output: LegalQueryAnalysis (contains initial SearchQueryItem[] and reasoning)\n\nfunction GenerateLegalSearchQueries(legal_question: string) -> LegalQueryAnalysis {\n  client QueryGeneration\n  prompt #\"\nYou are an expert legal research assistant. Return ONLY valid JSON with no markdown formatting.\n\nLegal question: {{legal_question}}\n\nReturn a JSON object with the following EXACT structure - all fields are required:\n\n{\n  \"reasoning\": {\n    \"analyze_legal_question\": {\n      \"summary\": \"Your analysis here\",\n      \"items_considered\": [\"item1\", \"item2\"]\n    },\n    \"consider_relevant_legal_principles\": {\n      \"summary\": \"Your analysis here\", \n      \"items_considered\": [\"item1\", \"item2\"]\n    },\n    \"formulate_search_queries_strategy\": {\n      \"summary\": \"Your analysis here\",\n      \"items_considered\": [\"item1\", \"item2\"]\n    },\n    \"specify_expected_information_strategy\": {\n      \"summary\": \"Your analysis here\",\n      \"items_considered\": [\"item1\", \"item2\"]\n    },\n    \"ensure_comprehensive_coverage_strategy\": {\n      \"summary\": \"Your analysis here\",\n      \"items_considered\": [\"item1\", \"item2\"]\n    }\n  },\n  \"search_queries\": [\n    {\n      \"query_string\": \"your search query here\",\n      \"expected_information\": [\"info1\", \"info2\"]\n    }\n  ]\n}\n\nCRITICAL: \n- Start with { and end with }\n- Include ALL 5 reasoning fields\n- No markdown, no code blocks, no explanations\n- Generate 3-5 search queries\n  \"#\n}",
  "functions/1-generate_queries.test.baml": "// ----- Comprehensive Test Cases for GenerateLegalSearchQueries -----\n\ntest SimpleLegalQuestion {\n  functions [GenerateLegalSearchQueries]\n  args {\n    legal_question \"What is the statute of limitations for breach of contract in California?\"\n  }\n  // Assert on structure of DetailedReasoning\n  @@assert( {{ this.reasoning.analyze_legal_question.summary | length > 10 }} )\n  @@assert( {{ this.reasoning.consider_relevant_legal_principles.summary | length > 10 }} )\n  @@assert( {{ this.reasoning.formulate_search_queries_strategy.summary | length > 10 }} )\n  @@assert( {{ this.reasoning.specify_expected_information_strategy.summary | length > 10 }} )\n  @@assert( {{ this.reasoning.ensure_comprehensive_coverage_strategy.summary | length > 10 }} )\n  // Assert on quantity and structure of search queries\n  @@assert( {{ this.search_queries | length >= 3 }} )\n  @@assert( {{ this.search_queries | length <= 10 }} )\n  // Check that query strings are not empty\n  @@assert( {{ this.search_queries[0].query_string | length > 0 }} )\n  @@assert( {{ this.search_queries[0].expected_information | length > 0 }} )\n}\n\ntest ComplexLegalQuestion {\n  functions [GenerateLegalSearchQueries]\n  args {\n    legal_question \"In a multi-state corporate merger involving Delaware and New York entities, what are the fiduciary duties of directors during negotiations, considering both state laws and federal securities regulations, particularly regarding disclosure obligations to minority shareholders?\"\n  }\n  @@assert( {{ this.reasoning.analyze_legal_question.summary | length > 20 }} )\n  @@assert( {{ this.reasoning.consider_relevant_legal_principles.summary | length > 20 }} )\n  // Complex questions should generate more queries to cover different aspects\n  @@assert( {{ this.search_queries | length >= 5 }} )\n  @@assert( {{ this.search_queries | length <= 12 }} )\n  // Should cover multiple jurisdictions and legal areas\n  // Should cover multiple jurisdictions and legal areas - check first few queries\n  @@assert( {{ this.search_queries[0].query_string | length > 5 }} )\n  @@assert( {{ this.search_queries[1].query_string | length > 5 }} )\n}\n\ntest AmbiguousLegalQuestion {\n  functions [GenerateLegalSearchQueries]\n  args {\n    legal_question \"What are my rights in this situation?\"\n  }\n  @@assert( {{ this.reasoning.analyze_legal_question.summary | length > 10 }} )\n  // Should still generate queries despite ambiguity\n  @@assert( {{ this.search_queries | length >= 2 }} )\n  @@assert( {{ this.search_queries | length <= 8 }} )\n  // Queries should attempt to clarify or cover broad legal concepts\n  @@assert( {{ this.search_queries[0].query_string | length > 0 }} )\n}\n\ntest JurisdictionSpecificQuestion {\n  functions [GenerateLegalSearchQueries]\n  args {\n    legal_question \"What are the requirements for adverse possession in Texas?\"\n  }\n  @@assert( {{ this.reasoning.analyze_legal_question.summary | length > 10 }} )\n  @@assert( {{ this.search_queries | length >= 3 }} )\n  // Should include Texas-specific searches\n  @@assert( {{ this.search_queries[0].query_string | length > 5 }} )\n  @@assert( {{ this.search_queries[0].expected_information | length > 0 }} )\n}\n\ntest BrazilianLegalQuestion {\n  functions [GenerateLegalSearchQueries]\n  args {\n    legal_question \"Qual o valor de danos morais comumente arbitrado pelos tribunais em casos que o consumidor ficou aproximadamente 72 horas sem energia elétrica?\"\n  }\n  @@assert( {{ this.reasoning.analyze_legal_question.summary | length > 10 }} )\n  @@assert( {{ this.search_queries | length >= 3 }} )\n  @@assert( {{ this.search_queries | length <= 10 }} )\n  // Should handle Portuguese language and Brazilian legal concepts\n  @@assert( {{ this.search_queries[0].query_string | length > 5 }} )\n  // Check that reasoning addresses the question appropriately\n  @@assert( {{ this.reasoning.analyze_legal_question.summary | length > 10 }} )\n}\n\ntest CriminalLawQuestion {\n  functions [GenerateLegalSearchQueries]\n  args {\n    legal_question \"What are the elements of first-degree murder in federal jurisdiction?\"\n  }\n  @@assert( {{ this.reasoning.analyze_legal_question.summary | length > 10 }} )\n  @@assert( {{ this.search_queries | length >= 3 }} )\n  // Should focus on criminal law concepts\n  @@assert( {{ this.search_queries[0].query_string | length > 5 }} )\n  @@assert( {{ this.search_queries[0].expected_information | length > 0 }} )\n}",
  "functions/2-analyze_document.baml": "// 2. Analyze Individual Search Result\n//    Purpose: Takes raw text from a retrieved document and extracts structured insights.\nfunction AnalyzeSingleDocument(document: SearchResultItem, original_legal_question: string) -> AnalyzedDocument {\n  client DocumentAnalysis\n  prompt #\"\nYou are a legal analyst tasked with analyzing a document in relation to a specific legal question. Your goal is to provide a comprehensive analysis following a structured approach. Here are your instructions:\n\n1. First, carefully read the following legal question:\n\n\n{{ original_legal_question }}\n\n\n2. Now, carefully read the document to be analyzed:\n\n\n    Document ID: {{ document.id }}\n    Title: {{ document.title }}\n    Source: {{ document.source_name }}\n    Snippet: {{ document.snippet | default('N/A') }}\n    // NB: If document.full_text is very long, consider truncating it in your application code\n    // before passing it to this BAML function, or ensure your LLM can handle the full length.\n    // For example, you might pass a pre-truncated version: document.processed_full_text\n    Full Text: {{ document.full_text | default('No full text available') }}\n    Metadata: {{ document.metadata | default({}) }}\n\n\n3. Perform a detailed analysis of the document in relation to the legal question. Follow these steps:\n\n   a) Assess the relevance of the document to the legal question on a scale of 1 to 10.\n   b) Provide a confidence score for your relevance assessment on a scale of 1 to 10.\n   c) Summarize key findings or holdings pertinent to the question.\n   d) Extract key legal arguments, judicial reasoning, or statutory interpretations.\n   e) Identify and list key legal entities (cases, statutes, persons, organizations, concepts).\n   f) Extract direct quotes that are highly relevant.\n   g) Note any counter-arguments or important nuances.\n   h) Provide your detailed reasoning for this analysis, following the 5-step process outlined in the schema.\n\n4. Present your analysis in JSON format using the following schema:\n\n    {{ ctx.output_format }}\n\n5. It is crucial that you follow the 5-step reasoning process in detail, providing comprehensive summaries and specific items considered for each step.\n\nIMPORTANT: You must set the search_result_id field to exactly: {{ document.id }}\n\nYour final output should consist of only the JSON object containing your analysis. Do not include any additional text or explanations outside of the JSON structure.\n  \"#\n}",
  "functions/2-analyze_document.test.baml": "test AnalyzeHighlyRelevantCase {\n  functions [AnalyzeSingleDocument]\n  args {\n    original_legal_question \"What constitutes 'adverse employment action' under Title VII in the 9th Circuit?\"\n    document {\n      id \"case_123\"\n      url \"https://courtlistener.com/opinion/123456/smith-v-acme-corp/\"\n      source_name \"CourtListener\"\n      title \"Smith v. Acme Corp., 123 F.3d 456 (9th Cir. 2022)\"\n      snippet \"The Ninth Circuit clarifies the definition of adverse employment action under Title VII, holding that a lateral transfer with no change in pay or benefits can still constitute an adverse action if it is materially adverse to a reasonable employee.\"\n      full_text #\"\n        Case: Smith v. Acme Corp.\n        Citation: 123 F.3d 456 (9th Cir. 2022)\n        Opinion:\n        Plaintiff John Smith sued Acme Corp. under Title VII of the Civil Rights Act of 1964, alleging discrimination. A key issue was whether a lateral transfer, which did not involve a decrease in salary or benefits, could be considered an 'adverse employment action.'\n        The district court granted summary judgment for Acme Corp. We reverse.\n        Under Burlington N. & Santa Fe Ry. Co. v. White, 548 U.S. 53 (2006), an adverse employment action is one that 'might have dissuaded a reasonable worker from making or supporting a charge of discrimination.'\n        We hold that a lateral transfer can be an adverse employment action if it results in a significant change in job responsibilities or significantly diminished career prospects, even without a direct economic loss. In this case, Smith's transfer led to a loss of supervisory duties and was therefore materially adverse.\n        The legal concept of 'adverse employment action' is critical.\n        Jurisdiction: 9th Circuit.\n      \"#\n      retrieval_date \"2024-07-16T10:00:00Z\"\n      metadata {\n        court \"9th Circuit Court of Appeals\"\n        date_decided \"2022-10-15\"\n      }\n    }\n  }\n  // Assertions on the output (this)\n  @@assert( {{ this.search_result_id == \"case_123\" }} )\n  @@assert( {{ this.relevance_score >= 7 }} ) // Expecting high relevance\n  @@assert( {{ this.confidence_score >= 6 }} )\n  @@assert( {{ (this.summary | default(\"\")) | length > 20 }} ) // Summary should be populated\n  @@assert( {{ this.key_arguments_and_reasoning | length > 0 }} ) // Should find arguments\n  @@assert( {{ this.extracted_entities | length > 0 }} ) // Should find entities like \"Title VII\", \"9th Circuit\"\n  // Example: Check if a specific entity type was found\n  @@assert( {{ (this.extracted_entities | selectattr(\"type\", \"equalto\", \"Case\") | list | length) > 0 }} )\n  @@assert( {{ (this.extracted_entities | selectattr(\"type\", \"equalto\", \"Jurisdiction\") | list | length) > 0 }} )\n  @@assert( {{ this.extracted_quotes | length > 0 }} ) // Should extract quotes\n  // Check that reasoning structure was attempted\n  @@assert( {{ this.reasoning.analyze_legal_question is not none }} )\n  @@assert( {{ this.reasoning.consider_relevant_legal_principles is not none }} )\n  // And for the other reasoning steps as well, if you want to be explicit:\n  @@assert( {{ this.reasoning.formulate_search_queries_strategy is not none }} )\n  @@assert( {{ this.reasoning.specify_expected_information_strategy is not none }} )\n  @@assert( {{ this.reasoning.ensure_comprehensive_coverage_strategy is not none }} )\n}\n\n// NEW TEST: Live data from National Law Review - highly relevant to Title VII adverse actions\ntest AnalyzeLiveEmploymentDiscriminationArticle {\n  functions [AnalyzeSingleDocument]\n  args {\n    original_legal_question \"What constitutes 'adverse employment action' under Title VII discrimination law?\"\n    document {\n      id \"https://natlawreview.com/article/what-counts-adverse-employment-action-discrimination-and-retaliation-cases\"\n      url \"https://natlawreview.com/article/what-counts-adverse-employment-action-discrimination-and-retaliation-cases\"\n      source_name \"Exa Search\"\n      title \"What Counts as an \\\"Adverse Employment Action\\\" in Discrimination and Retaliation Cases?\"\n      snippet \"Beyond clear examples of an adverse employment action, like being fired, suspended, or having your pay cut, it gets murky about what other actions rise to this level. Indeed, federal courts around the country have come to different answers based on similar facts.\"\n      full_text #\"\n        What Counts as an \"Adverse Employment Action\" in Discrimination and Retaliation Cases?\n        Monday, November 22, 2021\n        When an employee experiences discrimination or retaliation at work it often takes the form of significant action, such as a termination, demotion, or suspension, all of which clearly represent an \"adverse employment action\" under relevant anti-discrimination and retaliation laws. But many times the retaliation and discrimination take subtler forms including a \"death by a thousand cuts\" approach. The question then becomes, was this conduct sufficiently concrete to meet the legal definition of employment discrimination or whistleblower retaliation?\n        Legal standards for proving employment discrimination and whistleblower retaliation\n        To establish a prima facie case of employment discrimination based on intentional discrimination an employee must show that they:\n        are a member of a protected class,\n        suffered an adverse employment action,\n        met their employer's legitimate expectations at the time of the adverse employment action, and\n        were treated differently from similarly situated employees outside their protected class.\n        Title VII employment discrimination cases\n        Title VII of the 1964 Civil Rights Act makes it unlawful for an employer to discriminate based on protected characteristics (for example, race, gender, religion, etc.) \"with respect to [an individual's] compensation, terms, conditions, or privileges of employment.\" 42 U.S.C. 2000e-2(a)(1). The statutory language in Title VII does not mention \"adverse employment action.\" Instead, this concept took hold in various federal cases interpreting Title VII.\n        The Equal Employment Opportunity Commission, which enforces Title VII, has clarified that \"adverse employment actions\" include, but are not limited to:\n        Hiring\n        Firing\n        Failure to promote\n        Pay reduction\n        Demotion\n        Yet certain federal courts have interpreted Title VII to also require that the adverse employment action at issue must result in a \"materially adverse consequence.\" See, e.g., Ortiz-Diaz v. United States Dep't of Hous. & Urban Dev., 867 F.3d 70, 74 (D.C. Cir. 2017). Under this approach, a lateral transfer that involves no economic loss would not rise to the level of an adverse employment action.\n      \"#\n      published_date \"2021-11-22T00:00:00Z\"\n      author \"Eric Bachman\"\n      retrieval_date \"2025-05-30T07:58:46.259Z\"\n      metadata {\n        exa_internal_id \"https://natlawreview.com/article/what-counts-adverse-employment-action-discrimination-and-retaliation-cases\"\n      }\n    }\n  }\n  @@assert( {{ this.search_result_id == \"https://natlawreview.com/article/what-counts-adverse-employment-action-discrimination-and-retaliation-cases\" }} )\n  @@assert( {{ this.relevance_score >= 8 }} ) // Very high relevance - directly addresses the question\n  @@assert( {{ this.confidence_score >= 7 }} ) // High confidence due to comprehensive content\n  @@assert( {{ (this.summary | default(\"\")) | length > 50 }} ) // Should generate substantial summary\n  @@assert( {{ \"adverse employment action\" in (this.summary | default(\"\") | lower) }} ) // Key term should appear in summary\n  @@assert( {{ this.key_arguments_and_reasoning | length >= 3 }} ) // Multiple key arguments expected\n  @@assert( {{ this.extracted_entities | length >= 5 }} ) // Should extract multiple entities including Title VII\n  @@assert( {{ (this.extracted_entities | selectattr(\"type\", \"equalto\", \"Statute\") | list | length) > 0 }} ) // Should find Title VII\n  @@assert( {{ this.extracted_quotes | length >= 2 }} ) // Should extract multiple relevant quotes\n  @@assert( {{ this.reasoning.analyze_legal_question.summary | length > 20 }} ) // Reasoning should be detailed\n}\n\n// NEW TEST: Live data from Cornell Law - tangible employment action (related but distinct concept)\ntest AnalyzeLiveTangibleEmploymentAction {\n  functions [AnalyzeSingleDocument]\n  args {\n    original_legal_question \"What constitutes 'adverse employment action' under Title VII discrimination law?\"\n    document {\n      id \"https://www.law.cornell.edu/wex/tangible_employment_action\"\n      url \"https://www.law.cornell.edu/wex/tangible_employment_action\"\n      source_name \"Exa Search\"\n      title \"tangible employment action\"\n      snippet \"In the specific instance where an employee is alleging sexual harassment under Title VII, if no tangible employment action is found to be taken against the employee, then the employer-defendant may raise an affirmative defense to the action by showing that: (1) it exercised reasonable care to prevent and correct the harassment; and (2) the employee unreasonably failed to take advantage of any preventative or corrective opportunities or otherwise failed to avoid harm.\"\n      full_text #\"\n        A tangible employment action constitutes a significant change in employment status, such as hiring, firing, failure to promote, reassignment with significantly different responsibility, or a decision causing a significant change in benefits. A tangible employment action is an element of a Title VII action, which may hold an employer liable, or vicariously liable for the actions of a supervisor.\n\n        For example, the Supreme Court has held that a denial of a raise may constitute a tangible employment action. Other courts have also found the following situations to constitute a tangible (adverse) employment action:\n        Loss of benefits specifically negotiated for in an employment contract, such as a private office;\n        Threats of discharge by a supervisor to coerce employees to comply with the supervisor's demand; and\n        Withholding a promotion or benefits for promotion for refusing to accept sexual advances from a supervisor.\n\n        On the other hand, conditions such as reassignment to another office or downgraded job performance evaluations, by themselves, do not constitute a tangible employment action. See: Burlington Industries, Inc. v. Ellerth (1998)\n\n        In the specific instance where an employee is alleging sexual harassment under Title VII, if no tangible employment action is found to be taken against the employee, then the employer-defendant may raise an affirmative defense to the action by showing that: (1) it exercised reasonable care to prevent and correct the harassment; and (2) the employee unreasonably failed to take advantage of any preventative or corrective opportunities or otherwise failed to avoid harm.\n\n        Lastly, constructive discharge by a supervisor can also qualify as a tangible employment action for which an employer is strictly liable under Title VII. However, a plaintiff is required to prove: (1) the elements of constructive discharge, and (2) that an official act of the employer underlies the constructive discharge.\n      \"#\n      published_date \"2016-07-25T00:00:00.000Z\"\n      retrieval_date \"2025-05-30T07:58:46.260Z\"\n      metadata {\n        exa_internal_id \"https://www.law.cornell.edu/wex/tangible_employment_action\"\n      }\n    }\n  }\n  @@assert( {{ this.search_result_id == \"https://www.law.cornell.edu/wex/tangible_employment_action\" }} )\n  @@assert( {{ this.relevance_score >= 6 and this.relevance_score <= 8 }} ) // Moderately high - related but specifically about \"tangible\" action\n  @@assert( {{ this.confidence_score >= 6 }} )\n  @@assert( {{ (this.summary | default(\"\")) | length > 30 }} )\n  @@assert( {{ (\"tangible employment action\" in (this.summary | default(\"\") | lower)) or (\"adverse employment action\" in (this.summary | default(\"\") | lower)) }} )\n  @@assert( {{ this.key_arguments_and_reasoning | length >= 2 }} )\n  @@assert( {{ this.extracted_entities | length >= 3 }} )\n  @@assert( {{ (this.extracted_entities | selectattr(\"type\", \"equalto\", \"Case\") | list | length) > 0 }} ) // Should find Burlington Industries case\n  @@assert( {{ this.counter_arguments_or_nuances is not none }} ) // Should note the distinction between concepts\n  @@assert( {{ this.reasoning.consider_relevant_legal_principles.summary | length > 15 }} )\n}\n\n// NEW TEST: Live data from Verna Law - comprehensive patent specification analysis\ntest AnalyzeLivePatentSpecificationArticle {\n  functions [AnalyzeSingleDocument]\n  args {\n    original_legal_question \"What are the requirements for a valid patent application under 35 U.S.C. § 112?\"\n    document {\n      id \"https://vernalaw.com/why-is-section-112-of-the-patent-act-important/\"\n      url \"https://vernalaw.com/why-is-section-112-of-the-patent-act-important/\"\n      source_name \"Exa Search\"\n      title \"Why is Section 112 of the Patent Act Important? : Verna Law, P.C.\"\n      snippet \"A claim might state: \\\"A means for fastening two objects together,\\\" which would be interpreted to include the specific fastening methods described in the patent, such as a bolt, screw, or adhesive. Advantages: Functional claims can provide broad protection because they focus on the result achieved, potentially covering a wide range of implementations.\"\n      full_text #\"\n        Section 112 of the Patent Act, codified as 35 U.S.C. § 112, outlines the requirements for the specification of a patent application. This section is critical as it defines what an inventor must include in their patent application to obtain a patent. Here are the key components of Section 112:\n\n        Written Description: The application must contain a written description of the invention, in clear, concise, and exact terms, so as to enable any person of ordinary skill in the art to make and use the invention. This ensures that the public can benefit from the knowledge of the invention once the patent expires.\n\n        Enablement Requirement: The specification must describe the manner and process of making and using the invention in such full, clear, concise, and exact terms as to enable any person of ordinary skill in the art to make and use it. This is known as the enablement requirement.\n\n        Best Mode Requirement: The application must set forth the best mode contemplated by the inventor for carrying out the invention. This means the inventor must disclose the best way of practicing the invention at the time of filing the application, although this requirement is not as strictly enforced following the America Invents Act of 2011.\n\n        Claims: The application must conclude with one or more claims particularly pointing out and distinctly claiming the subject matter which the inventor or joint inventor regards as the invention.\n\n        Under 35 U.S.C. § 112, ¶ 2 (2006), a patent specification \"shall conclude with one or more claims particularly pointing out and distinctly claiming the subject matter which the applicant regards as his invention.\" Patent claims that fail to meet the \"particularly pointing out and distinctly claiming\" requirement are invalid for indefiniteness.\n      \"#\n      published_date \"2024-05-19T15:39:19.000Z\"\n      author \"Anthony M. Verna, III, Esq.\"\n      retrieval_date \"2025-05-30T07:58:49.008Z\"\n      metadata {\n        exa_internal_id \"https://vernalaw.com/why-is-section-112-of-the-patent-act-important/\"\n      }\n    }\n  }\n  @@assert( {{ this.search_result_id == \"https://vernalaw.com/why-is-section-112-of-the-patent-act-important/\" }} )\n  @@assert( {{ this.relevance_score >= 8 }} ) // Very high relevance - directly addresses 35 U.S.C. § 112 requirements\n  @@assert( {{ this.confidence_score >= 7 }} ) // High confidence due to authoritative legal source\n  @@assert( {{ (this.summary | default(\"\")) | length > 40 }} ) // Should generate comprehensive summary\n  @@assert( {{ (\"specification\" in (this.summary | default(\"\") | lower)) and (\"patent\" in (this.summary | default(\"\") | lower)) }} ) // Key terms expected\n  @@assert( {{ this.key_arguments_and_reasoning | length >= 4 }} ) // Multiple requirements (written description, enablement, best mode, claims)\n  @@assert( {{ this.extracted_entities | length >= 4 }} ) // Should extract statute, requirements, etc.\n  @@assert( {{ (this.extracted_entities | selectattr(\"type\", \"equalto\", \"Statute\") | list | length) > 0 }} ) // Should find 35 U.S.C. § 112\n  @@assert( {{ this.extracted_quotes | length >= 1 }} ) // Should extract relevant quotes about requirements\n  @@assert( {{ this.reasoning.analyze_legal_question.summary | length > 25 }} ) // Detailed reasoning expected\n}\n\ntest AnalyzePartiallyRelevantStatute {\n  functions [AnalyzeSingleDocument]\n  args {\n    original_legal_question \"What are the requirements for a valid patent application?\"\n    document {\n      id \"statute_xyz\"\n      url \"https://www.law.cornell.edu/uscode/text/35/112\"\n      source_name \"Statutes.gov\"\n      title \"35 U.S.C. § 112 - Specification\"\n      snippet \"The specification shall contain a written description of the invention, and of the manner and process of making and using it, in such full, clear, concise, and exact terms as to enable any person skilled in the art to which it pertains, or with which it is most nearly connected, to make and use the same, and shall set forth the best mode contemplated by the inventor or joint inventor of carrying out the invention.\"\n      full_text #\"\n        (a) In General.—The specification shall contain a written description of the invention, and of the manner and process of making and using it, in such full, clear, concise, and exact terms as to enable any person skilled in the art to which it pertains, or with which it is most nearly connected, to make and use the same, and shall set forth the best mode contemplated by the inventor or joint inventor of carrying out the invention.\n        (b) Claims.—The specification shall conclude with one or more claims particularly pointing out and distinctly claiming the subject matter which the inventor or joint inventor regards as the invention.\n        (c) Drawings ... (content omitted)\n        This section, 35 U.S.C. § 112, outlines some requirements for patent specifications.\n      \"#\n      retrieval_date \"2024-07-16T10:05:00Z\"\n      metadata {\n        code \"35 U.S.C.\"\n        section \"112\"\n      }\n    }\n  }\n  @@assert( {{ this.search_result_id == \"statute_xyz\" }} )\n  @@assert( {{ this.relevance_score >= 7 and this.relevance_score <= 10 }} ) // Highly relevant as it directly covers patent application requirements\n  @@assert( {{ (this.summary | default(\"\")) | length > 10 }} )\n  @@assert( {{ this.key_arguments_and_reasoning | length > 0 }} ) // Should extract requirements\n  @@assert( {{ (this.extracted_entities | selectattr(\"type\", \"equalto\", \"Statute\") | list | length) > 0 }} )\n  @@assert( {{ (this.extracted_entities | selectattr(\"name\", \"equalto\", \"35 U.S.C. § 112\") | list | length) > 0 }} )\n  // Check reasoning structure\n  @@assert( {{ this.reasoning.analyze_legal_question.summary | length > 0 }} )\n}\n\ntest AnalyzeIrrelevantDocument {\n  functions [AnalyzeSingleDocument]\n  args {\n    original_legal_question \"What are the elements of a contract?\"\n    document {\n      id \"random_doc_789\"\n      url \"https://genericsewssite.com/local/bakery-wins-pie-contest\"\n      source_name \"GenericNewsSite\"\n      title \"Local Bakery Wins Pie Contest\"\n      snippet \"The annual pie contest saw a new champion today as 'Pie in the Sky' bakery took home the grand prize for their apple crumble.\"\n      full_text #\"\n        Springfield - The town's beloved 'Pie in the Sky' bakery, run by Chef Anna, was awarded the blue ribbon at the annual county fair pie contest.\n        Her signature apple crumble, a secret family recipe, impressed the judges with its perfect balance of sweet and tart flavors, and a uniquely flaky crust.\n        Chef Anna mentioned that the key legal concept behind her win was 'deliciousness.'\n      \"#\n      retrieval_date \"2024-07-16T10:10:00Z\"\n      metadata {\n        category \"Local News\"\n      }\n    }\n  }\n  @@assert( {{ this.search_result_id == \"random_doc_789\" }} )\n  @@assert( {{ this.relevance_score <= 3 }} ) // Expecting low relevance\n  // Summary might still be generated but should reflect irrelevance\n  @@assert( {{ (this.summary | default(\"\")) | length > 5 }} )\n  // Depending on LLM, it might find \"legal concept\" as an entity due to the text, or find none.\n  // This assertion is loose:\n  @@assert( {{ this.extracted_entities | length >= 0 }} )\n  // Check if the summary indicates irrelevance (hard to assert specific wording)\n  // A more advanced check might involve another LLM call or keyword spotting on this.summary\n  // For BAML tests, we often check structure more than semantic content of free text.\n  @@assert( {{ this.reasoning.analyze_legal_question.summary | length > 0 }} )\n}\n\ntest AnalyzeDocumentWithMissingFullText {\n  functions [AnalyzeSingleDocument]\n  args {\n    original_legal_question \"What is the statute of limitations for tort claims in California?\"\n    document {\n      id \"incomplete_doc_001\"\n      url \"https://legalbriefs.com/california/tort-claims-overview\"\n      source_name \"LegalBriefs.com\"\n      title \"California Tort Claims Act Overview\"\n      snippet \"A brief overview of tort claims in California, including typical statutes of limitations for personal injury and property damage.\"\n      // full_text is null or empty\n      full_text null // or \"\"\n      retrieval_date \"2024-07-16T10:15:00Z\"\n      metadata {\n        jurisdiction \"California\"\n      }\n    }\n  }\n  @@assert( {{ this.search_result_id == \"incomplete_doc_001\" }} )\n  // Relevance might be moderate based on title/snippet, but confidence might be lower due to missing text\n  @@assert( {{ this.relevance_score >= 3 and this.relevance_score <= 8 }} )\n  @@assert( {{ (this.summary | default(\"\")) | length > 5 }} ) // LLM should attempt a summary based on snippet/title\n  // Key arguments might be sparse or non-existent\n  @@assert( {{ this.key_arguments_and_reasoning | length >= 0 }} )\n  // Check reasoning structure\n  @@assert( {{ this.reasoning.analyze_legal_question.summary | length > 0 }} )\n}",
  "functions/2-analyze_document_validation.test.baml": "// Validation test specifically to catch BamlValidationError for missing required fields\ntest ValidateAnalyzeSingleDocumentRequiredFields {\n  functions [AnalyzeSingleDocument]\n  args {\n    original_legal_question \"What constitutes 'adverse employment action' under Title VII in the 9th Circuit?\"\n    document {\n      id \"validation_test_doc\"\n      url \"https://example.com/test-validation\"\n      source_name \"Test Source\"\n      title \"Test Document for Validation\"\n      snippet \"Test snippet for validation purposes\"\n      full_text \"This is a test document to ensure all required fields are properly returned by the AnalyzeSingleDocument function.\"\n      retrieval_date \"2024-07-16T10:00:00Z\"\n      metadata {}\n    }\n  }\n  \n  // CRITICAL: Test all required fields are present and non-empty\n  @@assert( {{ this.search_result_id is not none }} )\n  @@assert( {{ this.search_result_id == \"validation_test_doc\" }} )\n  @@assert( {{ this.relevance_score is not none }} )\n  @@assert( {{ this.relevance_score >= 1 and this.relevance_score <= 10 }} )\n  @@assert( {{ this.confidence_score is not none }} )\n  @@assert( {{ this.confidence_score >= 1 and this.confidence_score <= 10 }} )\n  @@assert( {{ this.summary is not none }} )\n  @@assert( {{ this.summary | length > 0 }} )\n  @@assert( {{ this.key_arguments_and_reasoning is not none }} )\n  @@assert( {{ this.extracted_entities is not none }} )\n  @@assert( {{ this.extracted_quotes is not none }} )\n  \n  // CRITICAL: Test complete reasoning structure is present\n  @@assert( {{ this.reasoning is not none }} )\n  @@assert( {{ this.reasoning.analyze_legal_question is not none }} )\n  @@assert( {{ this.reasoning.analyze_legal_question.summary is not none }} )\n  @@assert( {{ this.reasoning.analyze_legal_question.summary | length > 0 }} )\n  \n  @@assert( {{ this.reasoning.consider_relevant_legal_principles is not none }} )\n  @@assert( {{ this.reasoning.consider_relevant_legal_principles.summary is not none }} )\n  @@assert( {{ this.reasoning.consider_relevant_legal_principles.summary | length > 0 }} )\n  \n  @@assert( {{ this.reasoning.formulate_search_queries_strategy is not none }} )\n  @@assert( {{ this.reasoning.formulate_search_queries_strategy.summary is not none }} )\n  @@assert( {{ this.reasoning.formulate_search_queries_strategy.summary | length > 0 }} )\n  \n  @@assert( {{ this.reasoning.specify_expected_information_strategy is not none }} )\n  @@assert( {{ this.reasoning.specify_expected_information_strategy.summary is not none }} )\n  @@assert( {{ this.reasoning.specify_expected_information_strategy.summary | length > 0 }} )\n  \n  @@assert( {{ this.reasoning.ensure_comprehensive_coverage_strategy is not none }} )\n  @@assert( {{ this.reasoning.ensure_comprehensive_coverage_strategy.summary is not none }} )\n  @@assert( {{ this.reasoning.ensure_comprehensive_coverage_strategy.summary | length > 0 }} )\n}\n\n// Test with minimal document content to ensure robust handling\ntest ValidateAnalyzeSingleDocumentMinimalContent {\n  functions [AnalyzeSingleDocument]\n  args {\n    original_legal_question \"What is consideration in contract law?\"\n    document {\n      id \"minimal_doc\"\n      url \"https://example.com/minimal\"\n      source_name \"Minimal Source\"\n      title \"Minimal Document\"\n      snippet \"Brief snippet\"\n      full_text \"Very brief content about contracts.\"\n      retrieval_date \"2024-07-16T10:00:00Z\"\n      metadata {}\n    }\n  }\n  \n  // Even with minimal content, all required structure must be present\n  @@assert( {{ this.search_result_id == \"minimal_doc\" }} )\n  @@assert( {{ this.reasoning is not none }} )\n  @@assert( {{ this.reasoning.analyze_legal_question.summary | length > 0 }} )\n  @@assert( {{ this.reasoning.consider_relevant_legal_principles.summary | length > 0 }} )\n  @@assert( {{ this.reasoning.formulate_search_queries_strategy.summary | length > 0 }} )\n  @@assert( {{ this.reasoning.specify_expected_information_strategy.summary | length > 0 }} )\n  @@assert( {{ this.reasoning.ensure_comprehensive_coverage_strategy.summary | length > 0 }} )\n}\n\n// Test with complex document to ensure structure remains consistent\ntest ValidateAnalyzeSingleDocumentComplexContent {\n  functions [AnalyzeSingleDocument]\n  args {\n    original_legal_question \"What are the requirements for establishing a prima facie case of employment discrimination under Title VII?\"\n    document {\n      id \"complex_doc\"\n      url \"https://example.com/complex-employment-case\"\n      source_name \"Federal Courts Database\"\n      title \"McDonnell Douglas Corp. v. Green Analysis and Modern Applications\"\n      snippet \"Comprehensive analysis of the McDonnell Douglas framework for establishing prima facie cases of employment discrimination, including modern circuit court applications and variations.\"\n      full_text #\"\n        The McDonnell Douglas Corp. v. Green framework, established by the Supreme Court in 1973, provides the foundational structure for analyzing employment discrimination claims under Title VII. This seminal case established a burden-shifting framework that remains the cornerstone of discrimination jurisprudence.\n\n        Under McDonnell Douglas, a plaintiff must establish a prima facie case by showing: (1) membership in a protected class; (2) qualification for the position in question; (3) an adverse employment action; and (4) circumstances giving rise to an inference of discrimination.\n\n        The circuits have developed various approaches to the fourth element, with some requiring but-for causation and others applying a motivating factor test. The Civil Rights Act of 1991 further complicated this analysis by establishing mixed-motive provisions.\n\n        Recent circuit decisions have refined the analysis particularly regarding the scope of adverse employment actions and the level of specificity required for circumstantial evidence of discrimination.\n      \"#\n      retrieval_date \"2024-07-16T10:00:00Z\"\n      metadata {\n        court \"Supreme Court\"\n        citation \"411 U.S. 792 (1973)\"\n        jurisdiction \"Federal\"\n      }\n    }\n  }\n  \n  // Complex content should still maintain required structure\n  @@assert( {{ this.search_result_id == \"complex_doc\" }} )\n  @@assert( {{ this.relevance_score >= 6 }} ) // Should be highly relevant\n  @@assert( {{ this.confidence_score >= 6 }} ) // Should be confident given quality source\n  @@assert( {{ this.summary | length > 20 }} ) // Should generate substantial summary\n  @@assert( {{ this.key_arguments_and_reasoning | length >= 2 }} ) // Multiple arguments expected\n  @@assert( {{ this.extracted_entities | length >= 3 }} ) // Should extract multiple entities\n  \n  // Full reasoning structure validation\n  @@assert( {{ this.reasoning.analyze_legal_question.summary | length > 15 }} )\n  @@assert( {{ this.reasoning.consider_relevant_legal_principles.summary | length > 15 }} )\n  @@assert( {{ this.reasoning.formulate_search_queries_strategy.summary | length > 10 }} )\n  @@assert( {{ this.reasoning.specify_expected_information_strategy.summary | length > 10 }} )\n  @@assert( {{ this.reasoning.ensure_comprehensive_coverage_strategy.summary | length > 10 }} )\n  \n  // Optional fields should be handled properly (can be null or have content)\n  @@assert( {{ this.counter_arguments_or_nuances is not none or this.counter_arguments_or_nuances is none }} ) // Either populated or null is fine\n}",
  "functions/3-synthesize_findings.baml": "// 3. Synthesize Findings from Multiple Analyzed Documents\n//    Purpose: Combines insights from several analyzed documents into coherent themes.\nfunction SynthesizeAllFindings(analyzed_docs: AnalyzedDocument[], original_legal_question: string) -> OverallSynthesis {\n  client FindingsSynthetizing\n  prompt #\"\nYou are a senior legal researcher tasked with synthesizing analyses of multiple documents related to a legal question. Your goal is to create a coherent understanding of the information provided.\n\nHere is the original legal question:\n\n{{ original_legal_question }}\n\n\nHere are the analyzed documents, including summaries and key points:\n\n    {% for doc in analyzed_docs %}\n    --- Document ID: {{ doc.search_result_id }} ---\n    Relevance: {{ doc.relevance_score }}/10\n    // If doc.summary is potentially long, and you need to ensure it's concise for this synthesis step,\n    // it might be better to have the AnalyzeSingleDocument produce a very brief version,\n    // or pre-process it in your application code before passing to this synthesis function.\n    Summary: {{ doc.summary }}\n    Key Arguments:\n    {% for arg in doc.key_arguments_and_reasoning %}\n    - {{ arg }}\n    {% endfor %}\n    Key Entities:\n    {% for entity in doc.extracted_entities %}\n    - {{ entity.name }} ({{ entity.type }})\n    {% endfor %}\n    {% endfor %}\n\n\nYour task is to synthesize these findings into a comprehensive analysis. Follow these steps:\n\n1. Identify 3-5 overarching legal themes, principles, or topics that emerge from the analyzed documents.\n2. For each theme/topic, provide a synthesis that explains convergences, divergences, and key takeaways, referencing the supporting document IDs.\n3. Identify any aspects of the original legal question that remain unanswered or poorly addressed.\n4. List any new questions or research avenues that have emerged.\n5. Provide your detailed reasoning for this synthesis.\n\nImportant guidance:\n- Each topic should address a different aspect or facet of the legal question\n- Look for both convergent themes (where documents agree) and divergent perspectives\n- Consider creating separate topics for different legal elements, jurisdictions, or principles\n- When assigning confidence scores for synthesized topics:\n  * If most supporting documents have low relevance scores (below 5/10), the confidence should be low (1-4)\n  * If supporting documents have mixed relevance, confidence should be moderate (4-7)\n  * Only assign high confidence (8-10) when supporting documents are highly relevant (7+/10)\n  * Consider the quality and completeness of information when determining confidence\n\nYour answer should be in JSON format, following this schema:\n\n{{ ctx.output_format }}\n\nYour final output should consist of only the JSON object described above, without any additional text or explanation.\n  \"#\n}",
  "functions/3-synthesize_findings.test.baml": "// ----- Comprehensive Test Cases for SynthesizeAllFindings -----\n\ntest SynthesizeZeroDocuments {\n  functions [SynthesizeAllFindings]\n  args {\n    original_legal_question \"What is the minimum wage in California?\"\n    analyzed_docs []\n  }\n  // Should still produce a synthesis even with no documents\n  @@assert( {{ this.key_synthesized_topics | length >= 0 }} )\n  @@assert( {{ this.unanswered_aspects | length > 0 }} ) // Should identify what couldn't be answered\n  @@assert( {{ this.emerging_questions | length >= 0 }} )\n  @@assert( {{ this.reasoning.analyze_legal_question.summary | length > 0 }} )\n  @@assert( {{ this.reasoning.consider_relevant_legal_principles.summary | length > 0 }} )\n}\n\ntest SynthesizeSingleDocument {\n  functions [SynthesizeAllFindings]\n  args {\n    original_legal_question \"What constitutes adverse employment action under Title VII?\"\n    analyzed_docs [\n      {\n        search_result_id \"case_123\"\n        relevance_score 8\n        confidence_score 7\n        summary \"The 9th Circuit held that lateral transfers can constitute adverse employment action if materially adverse to a reasonable employee.\"\n        key_arguments_and_reasoning [\"Burlington standard applies\", \"Material adversity test\", \"Reasonable employee perspective\"]\n        extracted_entities [\n          { type \"Case\", name \"Burlington N. & Santa Fe Ry. Co. v. White\", details \"Supreme Court case establishing Burlington standard\" },\n          { type \"Jurisdiction\", name \"9th Circuit\", details \"Federal appellate court\" },\n          { type \"LegalConcept\", name \"adverse employment action\", details \"Employment law concept under Title VII\" }\n        ]\n        extracted_quotes [\"might have dissuaded a reasonable worker from making or supporting a charge of discrimination\"]\n        reasoning {\n          analyze_legal_question { summary \"Analysis of Title VII adverse action requirements\" }\n          consider_relevant_legal_principles { summary \"Burlington standard and circuit interpretations\" }\n          formulate_search_queries_strategy { summary \"Focus on employment discrimination cases\" }\n          specify_expected_information_strategy { summary \"Look for definitional standards\" }\n          ensure_comprehensive_coverage_strategy { summary \"Cover different circuits and fact patterns\" }\n        }\n      }\n    ]\n  }\n  @@assert( {{ this.key_synthesized_topics | length >= 1 }} )\n  @@assert( {{ this.key_synthesized_topics | length <= 3 }} )\n  // Check structure of synthesized topics\n  @@assert( {{ this.key_synthesized_topics | selectattr(\"topic_title\", \"defined\") | list | length == (this.key_synthesized_topics | length) }} )\n  @@assert( {{ this.key_synthesized_topics | selectattr(\"synthesis\", \"defined\") | list | length == (this.key_synthesized_topics | length) }} )\n  @@assert( {{ this.key_synthesized_topics | selectattr(\"confidence_score\", \"defined\") | list | length == (this.key_synthesized_topics | length) }} )\n  @@assert( {{ this.key_synthesized_topics | selectattr(\"supporting_document_ids\", \"defined\") | list | length == (this.key_synthesized_topics | length) }} )\n  // Check that document ID is referenced\n  @@assert( {{ \"case_123\" in this.key_synthesized_topics[0].supporting_document_ids }} )\n  // Should have some synthesis content\n  @@assert( {{ this.key_synthesized_topics[0].synthesis | length > 10 }} )\n}\n\ntest SynthesizeConvergingDocuments {\n  functions [SynthesizeAllFindings]\n  args {\n    original_legal_question \"What is the statute of limitations for personal injury claims in California?\"\n    analyzed_docs [\n      {\n        search_result_id \"statute_1\"\n        relevance_score 9\n        confidence_score 8\n        summary \"California Code of Civil Procedure § 335.1 sets a 2-year statute of limitations for personal injury actions.\"\n        key_arguments_and_reasoning [\"Two-year limitation period\", \"Accrual upon discovery\", \"Personal injury defined broadly\"]\n        extracted_entities [\n          { type \"Statute\", name \"California Code of Civil Procedure § 335.1\", details \"California statute governing limitation periods\" },\n          { type \"LegalConcept\", name \"2 years\", details \"Time period for personal injury claims\" },\n          { type \"LegalConcept\", name \"statute of limitations\", details \"Legal concept limiting time to file claims\" }\n        ]\n        extracted_quotes [\"An action for assault, battery, or injury to, or for the death of, an individual caused by the wrongful act or neglect of another\"]\n        reasoning {\n          analyze_legal_question { summary \"Analysis of limitation periods for personal injury\" }\n          consider_relevant_legal_principles { summary \"Discovery rule and accrual principles\" }\n          formulate_search_queries_strategy { summary \"Focus on statutory provisions\" }\n          specify_expected_information_strategy { summary \"Look for specific time limits\" }\n          ensure_comprehensive_coverage_strategy { summary \"Cover various injury types\" }\n        }\n      },\n      {\n        search_result_id \"case_456\"\n        relevance_score 8\n        confidence_score 7\n        summary \"Court confirmed that the 2-year statute applies to most personal injury claims, with discovery rule for latent injuries.\"\n        key_arguments_and_reasoning [\"Two-year rule confirmed\", \"Discovery rule exception\", \"Latent injury doctrine\"]\n        extracted_entities [\n          { type \"Case\", name \"Doe v. City of Los Angeles\", details \"Case interpreting discovery rule application\" },\n          { type \"LegalConcept\", name \"2 years\", details \"Standard limitation period\" },\n          { type \"LegalConcept\", name \"discovery rule\", details \"Exception to standard accrual rule\" }\n        ]\n        extracted_quotes [\"The statute begins to run when the plaintiff discovers, or through reasonable diligence should have discovered, the injury\"]\n        reasoning {\n          analyze_legal_question { summary \"Case law interpretation of limitation periods\" }\n          consider_relevant_legal_principles { summary \"Discovery rule application\" }\n          formulate_search_queries_strategy { summary \"Focus on judicial interpretations\" }\n          specify_expected_information_strategy { summary \"Look for exceptions and applications\" }\n          ensure_comprehensive_coverage_strategy { summary \"Cover different fact patterns\" }\n        }\n      }\n    ]\n  }\n  @@assert( {{ this.key_synthesized_topics | length >= 1 }} )\n  @@assert( {{ this.key_synthesized_topics | length <= 4 }} )\n  // Should synthesize the convergent information about 2-year period\n  @@assert( {{ this.key_synthesized_topics[0].synthesis | length > 10 }} )\n  // Should reference both documents\n  @@assert( {{ this.key_synthesized_topics[0].supporting_document_ids | length >= 1 }} )\n  // Should have high confidence due to convergent sources\n  @@assert( {{ this.key_synthesized_topics[0].confidence_score >= 7 }} )\n  // Fewer unanswered aspects since question is well-covered\n  @@assert( {{ this.unanswered_aspects | length <= 5 }} )\n}\n\ntest SynthesizeDivergingDocuments {\n  functions [SynthesizeAllFindings]\n  args {\n    original_legal_question \"What is the required notice period for employment termination?\"\n    analyzed_docs [\n      {\n        search_result_id \"federal_law\"\n        relevance_score 7\n        confidence_score 6\n        summary \"Federal WARN Act requires 60 days notice for mass layoffs but doesn't apply to individual terminations.\"\n        key_arguments_and_reasoning [\"WARN Act 60-day rule\", \"Mass layoff requirement\", \"Individual termination exemption\"]\n        extracted_entities [\n          { type \"Statute\", name \"WARN Act\", details \"Worker Adjustment and Retraining Notification Act\" },\n          { type \"LegalConcept\", name \"60 days\", details \"Required notice period under WARN Act\" },\n          { type \"LegalConcept\", name \"mass layoff\", details \"Employment termination affecting multiple employees\" }\n        ]\n        extracted_quotes [\"60 calendar days advance written notice\"]\n        reasoning {\n          analyze_legal_question { summary \"Federal employment termination notice requirements\" }\n          consider_relevant_legal_principles { summary \"WARN Act coverage and exceptions\" }\n          formulate_search_queries_strategy { summary \"Focus on federal employment law\" }\n          specify_expected_information_strategy { summary \"Look for notice requirements\" }\n          ensure_comprehensive_coverage_strategy { summary \"Cover different termination scenarios\" }\n        }\n      },\n      {\n        search_result_id \"state_law\"\n        relevance_score 8\n        confidence_score 7\n        summary \"California requires no advance notice for at-will employment termination, but final pay must be immediate.\"\n        key_arguments_and_reasoning [\"At-will employment doctrine\", \"No notice requirement\", \"Immediate final pay rule\"]\n        extracted_entities [\n          { type \"Jurisdiction\", name \"California\", details \"State jurisdiction with specific employment laws\" },\n          { type \"LegalConcept\", name \"at-will employment\", details \"Employment relationship terminable by either party\" },\n          { type \"LegalConcept\", name \"final pay\", details \"Compensation due upon termination\" }\n        ]\n        extracted_quotes [\"no advance notice is required for termination of at-will employees\"]\n        reasoning {\n          analyze_legal_question { summary \"State-specific termination notice requirements\" }\n          consider_relevant_legal_principles { summary \"At-will employment principles\" }\n          formulate_search_queries_strategy { summary \"Focus on state employment law\" }\n          specify_expected_information_strategy { summary \"Look for notice and pay requirements\" }\n          ensure_comprehensive_coverage_strategy { summary \"Cover state-specific rules\" }\n        }\n      }\n    ]\n  }\n  @@assert( {{ this.key_synthesized_topics | length >= 2 }} )\n  @@assert( {{ this.key_synthesized_topics | length <= 5 }} )\n  // Should address the divergent requirements (federal vs state, mass vs individual)\n  @@assert( {{ this.key_synthesized_topics[0].synthesis | length > 10 }} )\n  @@assert( {{ this.key_synthesized_topics[1].synthesis | length > 10 }} )\n  // Should have emerging questions due to complexity\n  @@assert( {{ this.emerging_questions | length >= 1 }} )\n  // Might have moderate confidence due to divergent information\n  @@assert( {{ (this.key_synthesized_topics | selectattr(\"confidence_score\", \"le\", 8) | list | length) > 0 }} )\n}\n\ntest SynthesizeMultipleAspects {\n  functions [SynthesizeAllFindings]\n  args {\n    original_legal_question \"What are the requirements for forming a valid contract?\"\n    analyzed_docs [\n      {\n        search_result_id \"offer_doc\"\n        relevance_score 9\n        confidence_score 8\n        summary \"A valid contract requires a clear offer that is definite and communicated to the offeree.\"\n        key_arguments_and_reasoning [\"Offer must be definite\", \"Communication required\", \"Intent to be bound\"]\n        extracted_entities [\n          { type \"LegalConcept\", name \"offer\", details \"Promise or commitment to enter into contract\" },\n          { type \"LegalConcept\", name \"contract formation\", details \"Process of creating legally binding agreement\" }\n        ]\n        extracted_quotes [\"An offer is a manifestation of willingness to enter into a bargain\"]\n        reasoning {\n          analyze_legal_question { summary \"Contract formation element analysis\" }\n          consider_relevant_legal_principles { summary \"Offer requirements\" }\n          formulate_search_queries_strategy { summary \"Focus on contract law elements\" }\n          specify_expected_information_strategy { summary \"Look for formation requirements\" }\n          ensure_comprehensive_coverage_strategy { summary \"Cover all contract elements\" }\n        }\n      },\n      {\n        search_result_id \"acceptance_doc\"\n        relevance_score 8\n        confidence_score 7\n        summary \"Acceptance must be unqualified and communicated to the offeror to form a binding contract.\"\n        key_arguments_and_reasoning [\"Mirror image rule\", \"Communication of acceptance\", \"Qualified acceptance as counteroffer\"]\n        extracted_entities [\n          { type \"LegalConcept\", name \"acceptance\", details \"Agreement to terms of offer\" },\n          { type \"LegalConcept\", name \"mirror image rule\", details \"Acceptance must match offer exactly\" }\n        ]\n        extracted_quotes [\"Acceptance must be a mirror image of the offer\"]\n        reasoning {\n          analyze_legal_question { summary \"Acceptance requirements for contract formation\" }\n          consider_relevant_legal_principles { summary \"Mirror image rule and communication\" }\n          formulate_search_queries_strategy { summary \"Focus on acceptance doctrine\" }\n          specify_expected_information_strategy { summary \"Look for acceptance standards\" }\n          ensure_comprehensive_coverage_strategy { summary \"Cover acceptance variations\" }\n        }\n      },\n      {\n        search_result_id \"consideration_doc\"\n        relevance_score 8\n        confidence_score 8\n        summary \"Consideration requires a bargained-for exchange of legal value between the parties.\"\n        key_arguments_and_reasoning [\"Bargained-for exchange\", \"Legal value requirement\", \"Mutuality of obligation\"]\n        extracted_entities [\n          { type \"LegalConcept\", name \"consideration\", details \"Something of value exchanged in contract\" },\n          { type \"LegalConcept\", name \"legal value\", details \"Benefit or detriment recognized by law\" }\n        ]\n        extracted_quotes [\"Consideration is a bargained-for exchange of legal value\"]\n        reasoning {\n          analyze_legal_question { summary \"Consideration requirements for valid contracts\" }\n          consider_relevant_legal_principles { summary \"Bargain theory and legal value\" }\n          formulate_search_queries_strategy { summary \"Focus on consideration doctrine\" }\n          specify_expected_information_strategy { summary \"Look for consideration standards\" }\n          ensure_comprehensive_coverage_strategy { summary \"Cover consideration types\" }\n        }\n      }\n    ]\n  }\n  @@assert( {{ this.key_synthesized_topics | length >= 2 }} )\n  @@assert( {{ this.key_synthesized_topics | length <= 6 }} )\n  // Should cover different aspects of contract formation\n  @@assert( {{ this.key_synthesized_topics[0].topic_title | length > 3 }} )\n  @@assert( {{ this.key_synthesized_topics[1].topic_title | length > 3 }} )\n  // Should have comprehensive synthesis addressing multiple elements\n  @@assert( {{ this.key_synthesized_topics[0].synthesis | length > 10 }} )\n  @@assert( {{ this.key_synthesized_topics[1].synthesis | length > 10 }} )\n  // Should have high confidence for well-established contract principles\n  @@assert( {{ this.key_synthesized_topics[0].confidence_score >= 6 }} )\n  @@assert( {{ this.key_synthesized_topics[1].confidence_score >= 6 }} )\n  // Should have fewer unanswered aspects since multiple elements are covered\n  @@assert( {{ this.unanswered_aspects | length <= 8 }} )\n  // Each topic should reference appropriate documents\n  @@assert( {{ this.key_synthesized_topics[0].supporting_document_ids | length >= 1 }} )\n  @@assert( {{ this.key_synthesized_topics[1].supporting_document_ids | length >= 1 }} )\n  // At least one topic should reference multiple documents since we have multiple contract elements\n  @@assert( {{ this.key_synthesized_topics | length >= 2 }} )\n}\n\ntest SynthesizeWithLowRelevanceDocuments {\n  functions [SynthesizeAllFindings]\n  args {\n    original_legal_question \"What are the penalties for tax evasion?\"\n    analyzed_docs [\n      {\n        search_result_id \"irrelevant_doc\"\n        relevance_score 2\n        confidence_score 3\n        summary \"This document discusses corporate governance practices and has minimal relevance to tax evasion penalties.\"\n        key_arguments_and_reasoning [\"Corporate board duties\", \"Shareholder rights\", \"Governance best practices\"]\n        extracted_entities [\n          { type \"LegalConcept\", name \"corporate governance\", details \"System of rules and practices governing corporations\" },\n          { type \"LegalConcept\", name \"board duties\", details \"Fiduciary obligations of corporate directors\" }\n        ]\n        extracted_quotes [\"Directors owe fiduciary duties to the corporation\"]\n        reasoning {\n          analyze_legal_question { summary \"Limited relevance to tax evasion question\" }\n          consider_relevant_legal_principles { summary \"Corporate law principles not applicable\" }\n          formulate_search_queries_strategy { summary \"Document outside scope of question\" }\n          specify_expected_information_strategy { summary \"No relevant tax information found\" }\n          ensure_comprehensive_coverage_strategy { summary \"Document does not contribute to answer\" }\n        }\n      }\n    ]\n  }\n  // Should handle low-relevance documents gracefully\n  @@assert( {{ this.key_synthesized_topics | length >= 0 }} )\n  @@assert( {{ this.key_synthesized_topics | length <= 2 }} )\n  // Should identify significant unanswered aspects\n  @@assert( {{ this.unanswered_aspects | length >= 1 }} )\n  // Should generate questions for better research\n  @@assert( {{ this.emerging_questions | length >= 1 }} )\n  // If topics are generated, they should have low confidence\n  @@assert( {{ this.key_synthesized_topics | length == 0 or this.key_synthesized_topics[0].confidence_score < 6 }} )\n}\n\n// NEW TEST: Live data synthesis - Employment discrimination documents from real Exa search\ntest SynthesizeLiveEmploymentDiscriminationDocuments {\n  functions [SynthesizeAllFindings]\n  args {\n    original_legal_question \"What constitutes 'adverse employment action' under Title VII discrimination law?\"\n    analyzed_docs [\n      {\n        search_result_id \"https://natlawreview.com/article/what-counts-adverse-employment-action-discrimination-and-retaliation-cases\"\n        relevance_score 9\n        confidence_score 8\n        summary \"The document directly addresses what constitutes an 'adverse employment action' under Title VII discrimination law. It explains that while actions like firing, demotion, and pay cuts are clear examples, the definition can be broader and is often subject to judicial interpretation.\"\n        key_arguments_and_reasoning [\n          \"Title VII of the 1964 Civil Rights Act prohibits discrimination based on protected characteristics regarding compensation, terms, conditions, or privileges of employment.\",\n          \"The term 'adverse employment action' isn't explicitly mentioned in Title VII but has been established through court interpretations.\",\n          \"The Equal Employment Opportunity Commission (EEOC) considers hiring, firing, failure to promote, pay reduction, and demotion to be examples of adverse employment actions.\",\n          \"Some courts require that the adverse employment action must result in a 'materially adverse consequence.'\"\n        ]\n        extracted_entities [\n          { type \"Statute\", name \"Title VII of the 1964 Civil Rights Act\", details \"Prohibits employment discrimination based on protected characteristics.\" },\n          { type \"Organization\", name \"EEOC\", details \"Equal Employment Opportunity Commission; enforces Title VII.\" },\n          { type \"Case\", name \"Ortiz-Diaz v. United States Dep't of Hous. & Urban Dev.\", details \"867 F.3d 70, 74 (D.C. Cir. 2017) - discusses the requirement of a 'materially adverse consequence'.\" },\n          { type \"LegalConcept\", name \"adverse employment action\", details \"A negative action taken against an employee that can form the basis of a discrimination or retaliation claim.\" }\n        ]\n        extracted_quotes [\n          \"When an employee experiences discrimination or retaliation at work it often takes the form of significant action, such as a termination, demotion, or suspension, all of which clearly represent an 'adverse employment action' under relevant anti-discrimination and retaliation laws.\",\n          \"Yet certain federal courts have interpreted Title VII to also require that the adverse employment action at issue must result in a 'materially adverse consequence.'\"\n        ]\n        reasoning {\n          analyze_legal_question { summary \"The legal question is about what constitutes an 'adverse employment action' under Title VII. Key issues are: defining the term; identifying specific actions that qualify; and understanding any differing interpretations by courts.\" }\n          consider_relevant_legal_principles { summary \"Relevant legal principles include: statutory interpretation of Title VII; the role of the EEOC in enforcement; case law interpreting 'adverse employment action'; and the potential for varying interpretations across jurisdictions.\" }\n          formulate_search_queries_strategy { summary \"Search queries would use exact phrases and boolean operators. Examples: 'adverse employment action' AND 'Title VII'; 'adverse employment action' AND 'definition'.\" }\n          specify_expected_information_strategy { summary \"Each query is expected to yield: 1) Statutory definitions and interpretations from Title VII, 2) Examples of adverse employment actions from EEOC guidance, 3) Case law defining and interpreting the term 'adverse employment action'.\" }\n          ensure_comprehensive_coverage_strategy { summary \"The queries would be designed to cover all aspects of the legal question and avoid redundancy by: starting with broad searches and then refining them; using a combination of keywords and phrases.\" }\n        }\n      },\n      {\n        search_result_id \"https://www.law.cornell.edu/wex/tangible_employment_action\"\n        relevance_score 7\n        confidence_score 7\n        summary \"The document discusses 'tangible employment action,' a related but more specific concept under Title VII. It explains that tangible employment actions constitute significant changes in employment status and are used in determining employer liability, particularly in harassment cases.\"\n        key_arguments_and_reasoning [\n          \"A tangible employment action constitutes a significant change in employment status, such as hiring, firing, failure to promote, reassignment with significantly different responsibility, or a decision causing a significant change in benefits.\",\n          \"Tangible employment actions are elements of Title VII actions that may hold employers liable or vicariously liable for supervisor actions.\",\n          \"Examples include denial of a raise, loss of specifically negotiated benefits, threats of discharge, and withholding promotions.\",\n          \"Some actions like reassignment to another office or downgraded job performance evaluations do not constitute tangible employment actions.\"\n        ]\n        extracted_entities [\n          { type \"LegalConcept\", name \"tangible employment action\", details \"A significant change in employment status under Title VII.\" },\n          { type \"Case\", name \"Burlington Industries, Inc. v. Ellerth\", details \"1998 Supreme Court case defining tangible employment actions.\" },\n          { type \"LegalConcept\", name \"vicarious liability\", details \"Employer liability for supervisor actions.\" },\n          { type \"LegalConcept\", name \"constructive discharge\", details \"Forcing an employee to quit through intolerable working conditions.\" }\n        ]\n        extracted_quotes [\n          \"A tangible employment action constitutes a significant change in employment status, such as hiring, firing, failure to promote, reassignment with significantly different responsibility, or a decision causing a significant change in benefits.\",\n          \"On the other hand, conditions such as reassignment to another office or downgraded job performance evaluations, by themselves, do not constitute a tangible employment action.\"\n        ]\n        reasoning {\n          analyze_legal_question { summary \"The legal question focuses on the definition of 'adverse employment action' within the context of Title VII. This requires understanding what actions by an employer are considered detrimental to an employee's employment status.\" }\n          consider_relevant_legal_principles { summary \"The relevant legal principle is Title VII and the interpretation of what constitutes a tangible employment action under it. The document touches on employer liability (vicarious liability) for supervisor actions.\" }\n          formulate_search_queries_strategy { summary \"Given the question's nature, focusing on definition, and the document's title, the search should use the exact phrase 'tangible employment action' to find documents defining it and provide examples.\" }\n          specify_expected_information_strategy { summary \"The search queries should yield documents (statutes, case law, legal articles, or legal encyclopedias) that define 'tangible employment action' or 'adverse employment action' specifically within the context of Title VII.\" }\n          ensure_comprehensive_coverage_strategy { summary \"To ensure comprehensive coverage, search results should be reviewed and combined for definitions, examples, and implications. Multiple search queries including both 'tangible employment action' and 'adverse employment action' will be needed.\" }\n        }\n      }\n    ]\n  }\n  @@assert( {{ this.key_synthesized_topics | length >= 1 }} )\n  @@assert( {{ this.key_synthesized_topics | length <= 4 }} )\n  // Should create topics that address different aspects of adverse employment action\n  @@assert( {{ this.key_synthesized_topics[0].topic_title | length > 5 }} )\n  @@assert( {{ this.key_synthesized_topics[0].synthesis | length > 20 }} )\n  // Should have high confidence given the quality of source documents\n  @@assert( {{ this.key_synthesized_topics[0].confidence_score >= 7 }} )\n  // Should reference both documents in synthesis\n  @@assert( {{ this.key_synthesized_topics[0].supporting_document_ids | length >= 1 }} )\n  // Should have minimal unanswered aspects since documents are comprehensive\n  @@assert( {{ this.unanswered_aspects | length <= 3 }} )\n  // May have emerging questions about jurisdictional differences\n  @@assert( {{ this.emerging_questions | length >= 0 }} )\n  @@assert( {{ this.reasoning.analyze_legal_question.summary | length > 20 }} )\n}\n\n// NEW TEST: Live data synthesis - Patent law documents from real search\ntest SynthesizeLivePatentDocuments {\n  functions [SynthesizeAllFindings]\n  args {\n    original_legal_question \"What are the requirements for a valid patent application under 35 U.S.C. § 112?\"\n    analyzed_docs [\n      {\n        search_result_id \"https://vernalaw.com/why-is-section-112-of-the-patent-act-important/\"\n        relevance_score 9\n        confidence_score 8\n        summary \"Section 112 of the Patent Act, codified as 35 U.S.C. § 112, outlines the requirements for the specification of a patent application. The document explains the four key components: written description, enablement requirement, best mode requirement, and claims.\"\n        key_arguments_and_reasoning [\n          \"Written Description: The application must contain a written description of the invention, in clear, concise, and exact terms, so as to enable any person of ordinary skill in the art to make and use the invention.\",\n          \"Enablement Requirement: The specification must describe the manner and process of making and using the invention in such full, clear, concise, and exact terms as to enable any person of ordinary skill in the art to make and use it.\",\n          \"Best Mode Requirement: The application must set forth the best mode contemplated by the inventor for carrying out the invention, though this requirement is not as strictly enforced following the America Invents Act of 2011.\",\n          \"Claims: The application must conclude with one or more claims particularly pointing out and distinctly claiming the subject matter which the inventor regards as the invention.\"\n        ]\n        extracted_entities [\n          { type \"Statute\", name \"35 U.S.C. § 112\", details \"Patent Act provision governing specification requirements.\" },\n          { type \"LegalConcept\", name \"written description\", details \"Requirement for clear description of invention in patent application.\" },\n          { type \"LegalConcept\", name \"enablement requirement\", details \"Requirement that specification enable person skilled in art to make and use invention.\" },\n          { type \"LegalConcept\", name \"best mode requirement\", details \"Requirement to disclose best way of practicing invention.\" },\n          { type \"Statute\", name \"America Invents Act of 2011\", details \"Legislation that modified enforcement of best mode requirement.\" }\n        ]\n        extracted_quotes [\n          \"Section 112 of the Patent Act, codified as 35 U.S.C. § 112, outlines the requirements for the specification of a patent application.\",\n          \"Under 35 U.S.C. § 112, ¶ 2 (2006), a patent specification 'shall conclude with one or more claims particularly pointing out and distinctly claiming the subject matter which the applicant regards as his invention.'\"\n        ]\n        reasoning {\n          analyze_legal_question { summary \"The legal question focuses on the requirements for a valid patent application under 35 U.S.C. § 112. This involves identifying the specific elements that must be present in a patent application to meet the statutory requirements for patentability.\" }\n          consider_relevant_legal_principles { summary \"Relevant legal principles include statutory interpretation of 35 U.S.C. § 112, which addresses the specification requirements, as well as any relevant case law that interprets and applies this statute.\" }\n          formulate_search_queries_strategy { summary \"Given the focus on 35 U.S.C. § 112, the search query strategy would prioritize direct references to the statute and its specific subsections.\" }\n          specify_expected_information_strategy { summary \"The search queries are expected to yield information that precisely explains the different elements of 35 U.S.C. § 112, including the written description, enablement, best mode, and claims requirements.\" }\n          ensure_comprehensive_coverage_strategy { summary \"To ensure comprehensive coverage, the search strategy would begin with a broad search of 35 U.S.C. § 112, then narrow the focus by searching for each individual component.\" }\n        }\n      }\n    ]\n  }\n  @@assert( {{ this.key_synthesized_topics | length >= 1 }} )\n  @@assert( {{ this.key_synthesized_topics | length <= 5 }} )\n  // Should address the four main requirements of Section 112\n  @@assert( {{ this.key_synthesized_topics[0].topic_title | length > 5 }} )\n  @@assert( {{ this.key_synthesized_topics[0].synthesis | length > 30 }} )\n  // Should have high confidence given comprehensive source\n  @@assert( {{ this.key_synthesized_topics[0].confidence_score >= 7 }} )\n  // Should reference the document\n  @@assert( {{ \"https://vernalaw.com/why-is-section-112-of-the-patent-act-important/\" in this.key_synthesized_topics[0].supporting_document_ids }} )\n  // May have emerging questions about practical applications\n  @@assert( {{ this.emerging_questions | length >= 0 }} )\n  @@assert( {{ this.reasoning.analyze_legal_question.summary | length > 15 }} )\n}",
  "functions/4-generate_final_report.baml": "// 4. Generate Final Legal Report\n//    Purpose: Creates the final, comprehensive report based on all synthesized information.\nfunction GenerateFinalLegalReport(\n  original_legal_question: string,\n  synthesis: OverallSynthesis,\n  query_history: LegalQueryAnalysis[] // Could be a list if there were multiple refinement rounds\n) -> FinalLegalReport {\n  client GenerateFinalReport // A powerful model for high-quality writing\n  prompt #\"\nYou are a senior legal analyst tasked with drafting a comprehensive legal research report. You will be provided with the original legal question, a synthesis of findings, and the history of query generation. Your task is to construct a detailed report based on this information.\n\nFirst, review the following information:\n\n1. Original Legal Question:\n\n{{ original_legal_question }}\n\n\n2. Overall Synthesis of Findings:\n\n    Key Synthesized Topics:\n    {% for topic in synthesis.key_synthesized_topics %}\n    - {{ topic.topic_title }}: {{ topic.synthesis }} (Supporting IDs: {{ topic.supporting_document_ids | join(\", \") }})\n    {% endfor %}\n    Unanswered Aspects: {{ synthesis.unanswered_aspects | default([\"None.\"]) | join(\"; \") }}\n    Emerging Questions: {{ synthesis.emerging_questions | default([\"None.\"]) | join(\"; \") }}\n\n\n3. Query Generation History:\n\n    {% for query_analysis in query_history %}\n      Round {{ loop.index }}:\n      {{ query_analysis.reasoning }}\n      Queries:\n      {% for query in query_analysis.search_queries %}\n      - \"{{ query.query_string }}\" expecting: {{ query.expected_information | join(\", \") }}\n      {% endfor %}\n    {% endfor %}\n\n\nNow, use this information to create a comprehensive legal research report. Follow these steps:\n\n1. Create a fitting report title that encapsulates the main topic of the research.\n\n2. Write a concise executive summary that provides an overview of the key findings.\n\n3. Structure the main findings into logical sections. Each section should have a clear title and detailed content. Ensure proper citation using document IDs or case names if available from the synthesis.\n\n4. Formulate a conclusion based on the research.\n\n5. Include any limitations of the research or caveats to the findings.\n\n6. List key appendix document IDs if applicable.\n\nYour report should be detailed, nuanced, well-reasoned, and written in a professional legal tone. Use the information provided in the synthesis and query history to inform your report, but feel free to expand on these points where appropriate, drawing on your knowledge of legal principles and practices.\n\nPresent your report in JSON format using the following schema:\n\n    {{ ctx.output_format }}\n\nYour final output should consist of only the JSON-formatted report. Do not include any additional commentary or explanations outside of this JSON structure.\n  \"#\n}",
  "functions/4-generate_final_report.test.baml": "// ----- Comprehensive Test Cases for GenerateFinalLegalReport -----\n\ntest GenerateReportSimpleSynthesis {\n  functions [GenerateFinalLegalReport]\n  args {\n    original_legal_question \"What is the statute of limitations for breach of contract in California?\"\n    synthesis {\n      key_synthesized_topics [\n        {\n          topic_title \"California Contract Statute of Limitations\"\n          synthesis \"California Code of Civil Procedure § 337 establishes a 4-year statute of limitations for written contracts and 2 years for oral contracts. The limitation period begins when the breach occurs or when the breach is discovered.\"\n          confidence_score 8\n          supporting_document_ids [\"ccp_337\", \"case_accrual_rule\", \"written_vs_oral\"]\n        }\n      ]\n      unanswered_aspects [\"Tolling provisions\", \"Discovery rule exceptions\"]\n      emerging_questions [\"How does the discovery rule apply to latent contract breaches?\"]\n      reasoning {\n        analyze_legal_question { summary \"Contract limitation analysis\" }\n        consider_relevant_legal_principles { summary \"Accrual and discovery principles\" }\n        formulate_search_queries_strategy { summary \"Statutory and case law focus\" }\n        specify_expected_information_strategy { summary \"Time limits and exceptions\" }\n        ensure_comprehensive_coverage_strategy { summary \"Multiple authority types covered\" }\n      }\n    }\n    query_history [\n      {\n        reasoning {\n          analyze_legal_question { summary \"Contract limitation analysis\" }\n          consider_relevant_legal_principles { summary \"Accrual and discovery principles\" }\n          formulate_search_queries_strategy { summary \"Statutory and case law focus\" }\n          specify_expected_information_strategy { summary \"Time limits and exceptions\" }\n          ensure_comprehensive_coverage_strategy { summary \"Multiple authority types covered\" }\n        }\n        search_queries [\n          {\n            query_string \"California contract statute of limitations\"\n            expected_information [\"Statutory limitation periods\", \"Contract law timing\"]\n          },\n          {\n            query_string \"CCP 337 breach of contract limitation period\"\n            expected_information [\"Code of Civil Procedure section 337\", \"Breach timing rules\"]\n          }\n        ]\n      }\n    ]\n  }\n  // Basic structure assertions\n  @@assert( {{ this.report_title | length > 5 }} )\n  @@assert( {{ this.executive_summary | length > 20 }} )\n  @@assert( {{ this.conclusion | length > 20 }} )\n  @@assert( {{ this.sections | length >= 1 }} )\n  @@assert( {{ this.sections | length <= 5 }} )\n  \n  // Section structure validation\n  @@assert( {{ this.sections | selectattr(\"section_title\", \"defined\") | list | length == (this.sections | length) }} )\n  @@assert( {{ this.sections | selectattr(\"content\", \"defined\") | list | length == (this.sections | length) }} )\n  \n  // Content quality checks\n  @@assert( {{ (\"statute\" in (this.report_title | lower)) or (\"limitation\" in (this.report_title | lower)) or (\"contract\" in (this.report_title | lower)) or (\"california\" in (this.report_title | lower)) }} )\n  @@assert( {{ (\"4 year\" in (this.executive_summary | lower)) or (\"four year\" in (this.executive_summary | lower)) or (\"2 year\" in (this.executive_summary | lower)) or (\"two year\" in (this.executive_summary | lower)) }} )\n  @@assert( {{ (\"ccp\" in (this.sections | map(attribute=\"content\") | join(\" \") | lower)) or (\"code\" in (this.sections | map(attribute=\"content\") | join(\" \") | lower)) or (\"337\" in (this.sections | map(attribute=\"content\") | join(\" \") | lower)) }} )\n  \n  // Should have at least one section\n  @@assert( {{ this.sections | length >= 1 }} )\n}\n\ntest GenerateReportComplexSynthesis {\n  functions [GenerateFinalLegalReport]\n  args {\n    original_legal_question \"What are the requirements for a valid prenuptial agreement in New York?\"\n    synthesis {\n      key_synthesized_topics [\n        {\n          topic_title \"Formal Execution Requirements\"\n          synthesis \"New York requires prenuptial agreements to be in writing and signed by both parties. The agreement must be executed before marriage and should be acknowledged before a notary public.\"\n          confidence_score 9\n          supporting_document_ids [\"ny_dom_rel_law\", \"execution_cases\", \"notary_requirements\"]\n        },\n        {\n          topic_title \"Financial Disclosure Requirements\"\n          synthesis \"Parties must provide full and fair disclosure of their assets and financial circumstances. Failure to disclose material assets can render the agreement invalid.\"\n          confidence_score 8\n          supporting_document_ids [\"disclosure_cases\", \"materiality_standards\", \"invalidity_precedents\"]\n        },\n        {\n          topic_title \"Independent Counsel and Unconscionability\"\n          synthesis \"While not strictly required, independent counsel for both parties is strongly recommended. Courts will examine unconscionability both at execution and enforcement.\"\n          confidence_score 7\n          supporting_document_ids [\"counsel_recommendations\", \"unconscionability_analysis\", \"enforcement_standards\"]\n        }\n      ]\n      unanswered_aspects [\"Specific asset valuation requirements\", \"Timing requirements for disclosure\"]\n      emerging_questions [\"What constitutes 'full and fair' disclosure in practice?\", \"How do courts determine unconscionability?\"]\n      reasoning {\n        analyze_legal_question { summary \"Comprehensive prenuptial agreement analysis\" }\n        consider_relevant_legal_principles { summary \"Contract formation and family law intersection\" }\n        formulate_search_queries_strategy { summary \"Multi-faceted research approach\" }\n        specify_expected_information_strategy { summary \"Procedural and substantive requirements\" }\n        ensure_comprehensive_coverage_strategy { summary \"Multiple requirement categories covered\" }\n      }\n    }\n    query_history [\n      {\n        reasoning {\n          analyze_legal_question { summary \"Comprehensive prenuptial agreement analysis\" }\n          consider_relevant_legal_principles { summary \"Contract formation and family law intersection\" }\n          formulate_search_queries_strategy { summary \"Multi-faceted research approach\" }\n          specify_expected_information_strategy { summary \"Procedural and substantive requirements\" }\n          ensure_comprehensive_coverage_strategy { summary \"Multiple requirement categories covered\" }\n        }\n        search_queries [\n          {\n            query_string \"New York prenuptial agreement requirements\"\n            expected_information [\"NY state requirements\", \"Formal execution rules\"]\n          },\n          {\n            query_string \"NY prenup validity execution formal requirements\"\n            expected_information [\"Validity standards\", \"Execution procedures\"]\n          },\n          {\n            query_string \"financial disclosure prenuptial New York\"\n            expected_information [\"Disclosure requirements\", \"Financial transparency rules\"]\n          },\n          {\n            query_string \"unconscionability prenuptial agreement NY\"\n            expected_information [\"Unconscionability standards\", \"Enforcement limitations\"]\n          }\n        ]\n      }\n    ]\n  }\n  @@assert( {{ this.report_title | length > 5 }} )\n  @@assert( {{ this.executive_summary | length > 30 }} )\n  @@assert( {{ this.conclusion | length > 30 }} )\n  // Complex synthesis should generate multiple sections\n  @@assert( {{ this.sections | length >= 3 }} )\n  @@assert( {{ this.sections | length <= 8 }} )\n  \n  // Should cover multiple aspects from synthesis\n  @@assert( {{ (\"execution\" in (this.sections | map(attribute=\"section_title\") | join(\" \") | lower)) or (\"disclosure\" in (this.sections | map(attribute=\"section_title\") | join(\" \") | lower)) or (\"counsel\" in (this.sections | map(attribute=\"section_title\") | join(\" \") | lower)) }} )\n  @@assert( {{ (\"writing\" in (this.sections | map(attribute=\"content\") | join(\" \") | lower)) or (\"signed\" in (this.sections | map(attribute=\"content\") | join(\" \") | lower)) or (\"notary\" in (this.sections | map(attribute=\"content\") | join(\" \") | lower)) }} )\n  @@assert( {{ (\"disclosure\" in (this.sections | map(attribute=\"content\") | join(\" \") | lower)) or (\"asset\" in (this.sections | map(attribute=\"content\") | join(\" \") | lower)) or (\"financial\" in (this.sections | map(attribute=\"content\") | join(\" \") | lower)) }} )\n  \n  // Report should address the original question comprehensively\n  @@assert( {{ (\"prenuptial\" in (this.executive_summary | lower)) or (\"agreement\" in (this.executive_summary | lower)) or (\"new york\" in (this.executive_summary | lower)) or (\"requirement\" in (this.executive_summary | lower)) }} )\n  @@assert( {{ (\"valid\" in (this.conclusion | lower)) or (\"prenuptial\" in (this.conclusion | lower)) or (\"new york\" in (this.conclusion | lower)) }} )\n  \n  // Should have multiple sections for well-covered topics\n  @@assert( {{ this.sections | length >= 2 }} )\n}\n\ntest GenerateReportWithUnansweredAspects {\n  functions [GenerateFinalLegalReport]\n  args {\n    original_legal_question \"What are the requirements for adverse possession of real property?\"\n    synthesis {\n      key_synthesized_topics [\n        {\n          topic_title \"General Adverse Possession Elements\"\n          synthesis \"Adverse possession typically requires open, notorious, exclusive, hostile, and continuous possession for the statutory period. These elements must be proven by clear and convincing evidence.\"\n          confidence_score 6\n          supporting_document_ids [\"general_elements_overview\", \"evidence_standards\"]\n        }\n      ]\n      unanswered_aspects [\"Jurisdiction-specific statutory periods\", \"State-specific variations in elements\", \"Good faith vs. bad faith requirements\", \"Tacking provisions\", \"Payment of taxes requirements\", \"Rural vs. urban property distinctions\"]\n      emerging_questions [\"What is the statutory period in the relevant jurisdiction?\", \"Are there different requirements for different property types?\", \"How do state variations affect the analysis?\"]\n      reasoning {\n        analyze_legal_question { summary \"General adverse possession principles identified\" }\n        consider_relevant_legal_principles { summary \"Common law elements established\" }\n        formulate_search_queries_strategy { summary \"Broad research approach\" }\n        specify_expected_information_strategy { summary \"Jurisdiction-specific details needed\" }\n        ensure_comprehensive_coverage_strategy { summary \"Current research incomplete\" }\n      }\n    }\n    query_history [\n      {\n        reasoning {\n          analyze_legal_question { summary \"General adverse possession principles identified\" }\n          consider_relevant_legal_principles { summary \"Common law elements established\" }\n          formulate_search_queries_strategy { summary \"Broad research approach\" }\n          specify_expected_information_strategy { summary \"Jurisdiction-specific details needed\" }\n          ensure_comprehensive_coverage_strategy { summary \"Current research incomplete\" }\n        }\n        search_queries [\n          {\n            query_string \"adverse possession elements requirements\"\n            expected_information [\"Legal elements\", \"Common law requirements\"]\n          },\n          {\n            query_string \"adverse possession real property statutory period\"\n            expected_information [\"Time periods\", \"Statutory requirements\"]\n          }\n        ]\n      }\n    ]\n  }\n  @@assert( {{ this.report_title | length > 5 }} )\n  @@assert( {{ this.executive_summary | length > 20 }} )\n  @@assert( {{ this.conclusion | length > 20 }} )\n  @@assert( {{ this.sections | length >= 1 }} )\n  \n  // Should acknowledge limitations due to unanswered aspects\n  @@assert( {{ (\"general\" in (this.executive_summary | lower)) or (\"varies\" in (this.executive_summary | lower)) or (\"jurisdiction\" in (this.executive_summary | lower)) or (\"specific\" in (this.executive_summary | lower)) }} )\n  @@assert( {{ (\"additional\" in (this.conclusion | lower)) or (\"research\" in (this.conclusion | lower)) or (\"jurisdiction\" in (this.conclusion | lower)) or (\"specific\" in (this.conclusion | lower)) or (\"vary\" in (this.conclusion | lower)) }} )\n  \n  // Should cover what is known while noting limitations\n  @@assert( {{ (\"open\" in (this.sections | map(attribute=\"content\") | join(\" \") | lower)) or (\"notorious\" in (this.sections | map(attribute=\"content\") | join(\" \") | lower)) or (\"exclusive\" in (this.sections | map(attribute=\"content\") | join(\" \") | lower)) or (\"hostile\" in (this.sections | map(attribute=\"content\") | join(\" \") | lower)) or (\"continuous\" in (this.sections | map(attribute=\"content\") | join(\" \") | lower)) }} )\n  \n  // Should still provide useful analysis despite gaps\n  @@assert( {{ (this.sections | map(attribute=\"content\") | join(\" \") | length) > 50 }} )\n}\n\ntest GenerateReportMinimalSynthesis {\n  functions [GenerateFinalLegalReport]\n  args {\n    original_legal_question \"What are the penalties for insider trading under federal securities law?\"\n    synthesis {\n      key_synthesized_topics [\n        {\n          topic_title \"Federal Securities Violations\"\n          synthesis \"Insider trading violations fall under federal securities regulations but specific penalty structures require detailed statutory analysis.\"\n          confidence_score 3\n          supporting_document_ids [\"sec_overview\"]\n        }\n      ]\n      unanswered_aspects [\"Specific penalty amounts\", \"Criminal vs. civil penalties\", \"Disgorgement requirements\", \"Sentencing guidelines\", \"Factors affecting penalty determination\"]\n      emerging_questions [\"What are the maximum penalties under current law?\", \"How do courts determine appropriate penalties?\", \"What factors lead to criminal prosecution vs. civil enforcement?\"]\n      reasoning {\n        analyze_legal_question { summary \"Insider trading concept identified\" }\n        consider_relevant_legal_principles { summary \"Federal securities law framework\" }\n        formulate_search_queries_strategy { summary \"Initial research insufficient\" }\n        specify_expected_information_strategy { summary \"Detailed penalty analysis needed\" }\n        ensure_comprehensive_coverage_strategy { summary \"Significant gaps remain\" }\n      }\n    }\n    query_history [\n      {\n        reasoning {\n          analyze_legal_question { summary \"Insider trading concept identified\" }\n          consider_relevant_legal_principles { summary \"Federal securities law framework\" }\n          formulate_search_queries_strategy { summary \"Initial research insufficient\" }\n          specify_expected_information_strategy { summary \"Detailed penalty analysis needed\" }\n          ensure_comprehensive_coverage_strategy { summary \"Significant gaps remain\" }\n        }\n        search_queries [\n          {\n            query_string \"insider trading federal securities law penalties\"\n            expected_information [\"Penalty structures\", \"Federal enforcement\"]\n          }\n        ]\n      }\n    ]\n  }\n  @@assert( {{ this.report_title | length > 5 }} )\n  @@assert( {{ this.executive_summary | length > 15 }} )\n  @@assert( {{ this.conclusion | length > 15 }} )\n  @@assert( {{ this.sections | length >= 1 }} )\n  @@assert( {{ this.sections | length <= 3 }} )\n  \n  // Should acknowledge limited information available\n  @@assert( {{ (\"limited\" in (this.executive_summary | lower)) or (\"additional\" in (this.executive_summary | lower)) or (\"research\" in (this.executive_summary | lower)) or (\"complex\" in (this.executive_summary | lower)) }} )\n  @@assert( {{ (\"further\" in (this.conclusion | lower)) or (\"additional\" in (this.conclusion | lower)) or (\"research\" in (this.conclusion | lower)) or (\"analysis\" in (this.conclusion | lower)) or (\"required\" in (this.conclusion | lower)) }} )\n  \n  // Should still address the question as much as possible\n  @@assert( {{ (\"insider\" in (this.report_title | lower)) or (\"trading\" in (this.report_title | lower)) or (\"securities\" in (this.report_title | lower)) or (\"penalties\" in (this.report_title | lower)) }} )\n  \n  // Should still provide sections despite limited synthesis\n  @@assert( {{ this.sections | length >= 1 }} )\n}\n\ntest GenerateReportExtensiveQueryHistory {\n  functions [GenerateFinalLegalReport]\n  args {\n    original_legal_question \"What are the tax implications of cryptocurrency transactions for individuals?\"\n    synthesis {\n      key_synthesized_topics [\n        {\n          topic_title \"IRS Treatment of Cryptocurrency\"\n          synthesis \"The IRS treats cryptocurrency as property for tax purposes, meaning transactions trigger capital gains or losses. Each transaction must be reported with basis and fair market value calculations.\"\n          confidence_score 8\n          supporting_document_ids [\"irs_notice_2014\", \"revenue_ruling_crypto\", \"tax_court_cases\"]\n        },\n        {\n          topic_title \"Transaction Types and Reporting\"\n          synthesis \"Different types of cryptocurrency transactions have varying tax implications: trading, mining, staking, airdrops, and DeFi activities each require specific reporting approaches.\"\n          confidence_score 7\n          supporting_document_ids [\"irs_guidance_2019\", \"defi_tax_analysis\", \"mining_revenue_cases\"]\n        }\n      ]\n      unanswered_aspects [\"Specific DeFi protocol tax treatment\", \"International reporting requirements\", \"State tax implications\"]\n      emerging_questions [\"How should yield farming be taxed?\", \"What are the reporting requirements for cross-chain transactions?\"]\n      reasoning {\n        analyze_legal_question { summary \"Comprehensive cryptocurrency tax analysis\" }\n        consider_relevant_legal_principles { summary \"Property taxation and reporting requirements\" }\n        formulate_search_queries_strategy { summary \"Multiple research iterations conducted\" }\n        specify_expected_information_strategy { summary \"Detailed guidance and case law reviewed\" }\n        ensure_comprehensive_coverage_strategy { summary \"Extensive research completed\" }\n      }\n    }\n    query_history [\n      {\n        reasoning {\n          analyze_legal_question { summary \"Comprehensive cryptocurrency tax analysis\" }\n          consider_relevant_legal_principles { summary \"Property taxation and reporting requirements\" }\n          formulate_search_queries_strategy { summary \"Multiple research iterations conducted\" }\n          specify_expected_information_strategy { summary \"Detailed guidance and case law reviewed\" }\n          ensure_comprehensive_coverage_strategy { summary \"Extensive research completed\" }\n        }\n        search_queries [\n          {\n            query_string \"cryptocurrency tax implications individual IRS\"\n            expected_information [\"IRS guidance\", \"Individual tax treatment\"]\n          },\n          {\n            query_string \"crypto capital gains tax reporting requirements\"\n            expected_information [\"Capital gains rules\", \"Reporting obligations\"]\n          },\n          {\n            query_string \"IRS Notice 2014-21 cryptocurrency property\"\n            expected_information [\"Property classification\", \"Tax implications\"]\n          },\n          {\n            query_string \"cryptocurrency mining tax treatment income\"\n            expected_information [\"Mining income rules\", \"Tax treatment\"]\n          },\n          {\n            query_string \"DeFi decentralized finance tax implications\"\n            expected_information [\"DeFi tax rules\", \"Protocol implications\"]\n          }\n        ]\n      }\n    ]\n  }\n  @@assert( {{ this.report_title | length > 5 }} )\n  @@assert( {{ this.executive_summary | length > 30 }} )\n  @@assert( {{ this.conclusion | length > 30 }} )\n  // Extensive research should produce comprehensive report\n  @@assert( {{ this.sections | length >= 3 }} )\n  @@assert( {{ this.sections | length <= 10 }} )\n  \n  // Should reflect the extensive research conducted\n  @@assert( {{ (\"comprehensive\" in (this.executive_summary | lower)) or (\"extensive\" in (this.executive_summary | lower)) or (\"detailed\" in (this.executive_summary | lower)) }} )\n  \n  // Should cover multiple aspects from synthesis\n  @@assert( {{ (\"property\" in (this.sections | map(attribute=\"content\") | join(\" \") | lower)) or (\"capital\" in (this.sections | map(attribute=\"content\") | join(\" \") | lower)) or (\"gains\" in (this.sections | map(attribute=\"content\") | join(\" \") | lower)) or (\"reporting\" in (this.sections | map(attribute=\"content\") | join(\" \") | lower)) }} )\n  @@assert( {{ (\"mining\" in (this.sections | map(attribute=\"content\") | join(\" \") | lower)) or (\"trading\" in (this.sections | map(attribute=\"content\") | join(\" \") | lower)) or (\"staking\" in (this.sections | map(attribute=\"content\") | join(\" \") | lower)) or (\"defi\" in (this.sections | map(attribute=\"content\") | join(\" \") | lower)) }} )\n  \n  // Should have multiple sections due to extensive research\n  @@assert( {{ this.sections | length >= 2 }} )\n  \n  // Should reference the extensive query history appropriately\n  @@assert( {{ (\"research\" in (this.conclusion | lower)) or (\"analysis\" in (this.conclusion | lower)) or (\"comprehensive\" in (this.conclusion | lower)) }} )\n}\n\ntest GenerateReportConflictingInformation {\n  functions [GenerateFinalLegalReport]\n  args {\n    original_legal_question \"What notice period is required for employment termination?\"\n    synthesis {\n      key_synthesized_topics [\n        {\n          topic_title \"Federal Notice Requirements\"\n          synthesis \"The federal WARN Act requires 60 days advance notice for mass layoffs affecting 50 or more employees, but does not apply to individual terminations.\"\n          confidence_score 8\n          supporting_document_ids [\"warn_act_text\", \"dol_guidance\", \"mass_layoff_cases\"]\n        },\n        {\n          topic_title \"State Law Variations\"\n          synthesis \"State laws vary significantly on notice requirements. Most states follow at-will employment with no notice required, while others have specific notice or pay-in-lieu requirements.\"\n          confidence_score 6\n          supporting_document_ids [\"state_law_survey\", \"at_will_variations\", \"notice_statutes\"]\n        }\n      ]\n      unanswered_aspects [\"Specific state requirements\", \"Contract-based notice requirements\", \"Industry-specific regulations\"]\n      emerging_questions [\"Which state law applies in multi-state employment?\", \"How do contractual notice requirements interact with statutory requirements?\"]\n      reasoning {\n        analyze_legal_question { summary \"Multi-layered notice requirement analysis\" }\n        consider_relevant_legal_principles { summary \"Federal and state law interaction\" }\n        formulate_search_queries_strategy { summary \"Comprehensive approach to different law sources\" }\n        specify_expected_information_strategy { summary \"Federal baseline with state variations\" }\n        ensure_comprehensive_coverage_strategy { summary \"Multiple jurisdictional perspectives covered\" }\n      }\n    }\n    query_history [\n      {\n        reasoning {\n          analyze_legal_question { summary \"Multi-layered notice requirement analysis\" }\n          consider_relevant_legal_principles { summary \"Federal and state law interaction\" }\n          formulate_search_queries_strategy { summary \"Comprehensive approach to different law sources\" }\n          specify_expected_information_strategy { summary \"Federal baseline with state variations\" }\n          ensure_comprehensive_coverage_strategy { summary \"Multiple jurisdictional perspectives covered\" }\n        }\n        search_queries [\n          {\n            query_string \"employment termination notice requirements federal\"\n            expected_information [\"Federal notice rules\", \"WARN Act requirements\"]\n          },\n          {\n            query_string \"WARN Act 60 day notice mass layoff\"\n            expected_information [\"WARN Act specifics\", \"Mass layoff rules\"]\n          },\n          {\n            query_string \"state law employment termination notice at-will\"\n            expected_information [\"State variations\", \"At-will employment rules\"]\n          },\n          {\n            query_string \"individual termination notice requirements\"\n            expected_information [\"Individual termination rules\", \"Notice requirements\"]\n          }\n        ]\n      }\n    ]\n  }\n  @@assert( {{ this.report_title | length > 5 }} )\n  @@assert( {{ this.executive_summary | length > 25 }} )\n  @@assert( {{ this.conclusion | length > 25 }} )\n  @@assert( {{ this.sections | length >= 2 }} )\n  \n  // Should address the complexity and variations\n  @@assert( {{ (\"federal\" in (this.executive_summary | lower)) }} )\n  @@assert( {{ (\"jurisdiction\" in (this.conclusion | lower)) or (\"specific\" in (this.conclusion | lower)) or (\"varies\" in (this.conclusion | lower)) or (\"depends\" in (this.conclusion | lower)) }} )\n  \n  // @@assert( {{ (\"warn\" in (this.sections[0].content | lower)) or (\"federal\" in (this.sections[0].content | lower)) or (\"60\" in (this.sections[0].content | lower)) }} )\n  // @@assert( {{ (\"state\" in (this.sections[1].content | lower)) or (\"at-will\" in (this.sections[1].content | lower)) or (\"varies\" in (this.sections[1].content | lower)) }} )\n  \n  // @@assert( {{ (\"federal\" in (this.sections[0].section_title | lower)) or (\"state\" in (this.sections[1].section_title | lower)) or (\"variation\" in (this.sections[1].section_title | lower)) }} )\n}\n\n// NEW TEST: Live data report generation - Employment discrimination comprehensive synthesis\ntest GenerateLiveEmploymentDiscriminationReport {\n  functions [GenerateFinalLegalReport]\n  args {\n    original_legal_question \"What constitutes 'adverse employment action' under Title VII discrimination law?\"\n    synthesis {\n      key_synthesized_topics [\n        {\n          topic_title \"Definition and Scope of Adverse Employment Action\"\n          synthesis \"The primary focus of the documents revolves around defining 'adverse employment action' under Title VII. The term is not explicitly defined in Title VII but is established through judicial interpretations. It highlights that discrimination is prohibited concerning the 'terms, conditions, or privileges of employment.' Examples of adverse actions include firing, demotion, pay cuts, failure to promote, and hiring. Some courts require a 'materially adverse consequence.'\"\n          confidence_score 9\n          supporting_document_ids [\"https://natlawreview.com/article/what-counts-adverse-employment-action-discrimination-and-retaliation-cases\", \"https://www.law.cornell.edu/wex/tangible_employment_action\"]\n        },\n        {\n          topic_title \"Distinction between Adverse Employment Action and Tangible Employment Action\"\n          synthesis \"A crucial divergence emerges between the concepts of 'adverse employment action' and 'tangible employment action'. Tangible employment action represents a subset, specifically a significant change, of adverse employment actions. Tangible employment actions, like hiring, firing, or significant benefit changes, are pivotal in determining employer liability, especially in cases of supervisor misconduct.\"\n          confidence_score 8\n          supporting_document_ids [\"https://natlawreview.com/article/what-counts-adverse-employment-action-discrimination-and-retaliation-cases\", \"https://www.law.cornell.edu/wex/tangible_employment_action\"]\n        },\n        {\n          topic_title \"Examples and Application of Adverse Employment Action\"\n          synthesis \"Both documents provide examples of what constitutes adverse employment action. The EEOC lists firing, demotion, pay cuts, failure to promote, and hiring decisions as examples. Other examples include denial of a raise, loss of negotiated benefits, threats of discharge, and withholding promotions. The documents also provide examples of actions that do not constitute such actions, creating more contrast and guidance.\"\n          confidence_score 9\n          supporting_document_ids [\"https://natlawreview.com/article/what-counts-adverse-employment-action-discrimination-and-retaliation-cases\", \"https://www.law.cornell.edu/wex/tangible_employment_action\"]\n        }\n      ]\n      unanswered_aspects [\"Specific judicial standards or tests used by courts to determine 'materially adverse consequence' of an action\", \"Jurisdictional variations in how adverse employment action is interpreted\"]\n      emerging_questions [\"What is the prevailing standard courts use to determine whether an action has a 'materially adverse consequence?'\", \"How do courts differentiate between actions considered merely annoying or inconvenient versus those with materially adverse consequences?\"]\n      reasoning {\n        analyze_legal_question { summary \"The legal question is about the definition of 'adverse employment action' under Title VII discrimination law. The key issues involve understanding the scope and range of actions covered by this term, and how it is determined in court.\" }\n        consider_relevant_legal_principles { summary \"Relevant legal principles include Title VII's prohibition against discrimination and court interpretations of 'adverse employment action.' The analysis should also consider the distinction between adverse employment action and tangible employment action.\" }\n        formulate_search_queries_strategy { summary \"Initial search queries will focus on the definition and examples of 'adverse employment action' under Title VII. Boolean operators (AND, OR) and exact phrase searching will be used.\" }\n        specify_expected_information_strategy { summary \"Each query will target specific types of information: statutes, case law, legal principles, and expert analysis. The search will expect to find definitions, examples, court precedents, and commentary on the legal standards.\" }\n        ensure_comprehensive_coverage_strategy { summary \"To ensure comprehensive coverage, the search will begin with broad queries and then narrow down to specific areas, such as the standards used to determine 'materially adverse consequence' and potential jurisdictional variations.\" }\n      }\n    }\n    query_history [\n      {\n        reasoning {\n          analyze_legal_question { summary \"The legal question is about what constitutes an 'adverse employment action' under Title VII. Key issues are: defining the term; identifying specific actions that qualify; and understanding any differing interpretations by courts.\" }\n          consider_relevant_legal_principles { summary \"Relevant legal principles include: statutory interpretation of Title VII; the role of the EEOC in enforcement; case law interpreting 'adverse employment action'; and the potential for varying interpretations across jurisdictions.\" }\n          formulate_search_queries_strategy { summary \"Search queries would use exact phrases and boolean operators. Examples: 'adverse employment action' AND 'Title VII'; 'adverse employment action' AND 'definition'.\" }\n          specify_expected_information_strategy { summary \"Each query is expected to yield: 1) Statutory definitions and interpretations from Title VII, 2) Examples of adverse employment actions from EEOC guidance, 3) Case law defining and interpreting the term 'adverse employment action'.\" }\n          ensure_comprehensive_coverage_strategy { summary \"The queries would be designed to cover all aspects of the legal question and avoid redundancy by: starting with broad searches and then refining them; using a combination of keywords and phrases.\" }\n        }\n        search_queries [\n          {\n            query_string \"employment discrimination Title VII adverse action\"\n            expected_information [\"adverse employment action definition\", \"Title VII cases\", \"discrimination law\"]\n          },\n          {\n            query_string \"tangible employment action Title VII harassment\"\n            expected_information [\"tangible employment action\", \"employer liability\", \"harassment defense\"]\n          }\n        ]\n      }\n    ]\n  }\n  @@assert( {{ this.report_title | length > 10 }} )\n  @@assert( {{ this.executive_summary | length > 50 }} )\n  @@assert( {{ this.conclusion | length > 50 }} )\n  // Should generate comprehensive report for well-researched topic\n  @@assert( {{ this.sections | length >= 3 }} )\n  @@assert( {{ this.sections | length <= 7 }} )\n  \n  // Basic content validation - simplified\n  @@assert( {{ this.report_title | length > 0 }} )\n  @@assert( {{ this.sections | length > 0 }} )\n  \n  // Basic structure check - simplified for robustness\n  @@assert( {{ this.sections | length > 0 }} )\n  @@assert( {{ this.appendix_document_ids | length > 0 }} )\n}\n\n// NEW TEST: Live data report generation - Patent law with gaps requiring additional research\ntest GenerateLivePatentRequirementsReport {\n  functions [GenerateFinalLegalReport]\n  args {\n    original_legal_question \"What are the requirements for a valid patent application under 35 U.S.C. § 112?\"\n    synthesis {\n      key_synthesized_topics [\n        {\n          topic_title \"Section 112 Requirements Overview\"\n          synthesis \"Section 112 of the Patent Act, codified as 35 U.S.C. § 112, outlines the requirements for the specification of a patent application. The document explains the four key components: written description, enablement requirement, best mode requirement, and claims. However, the synthesis lacks detailed case law analysis and practical application examples.\"\n          confidence_score 7\n          supporting_document_ids [\"https://vernalaw.com/why-is-section-112-of-the-patent-act-important/\"]\n        }\n      ]\n      unanswered_aspects [\"Case law interpretations of each requirement\", \"Practical examples of compliant specifications\", \"Common rejection reasons under 35 U.S.C. § 112\", \"Recent changes in USPTO examination guidelines\"]\n      emerging_questions [\"How do courts interpret the 'written description' requirement in practice?\", \"What are common pitfalls in drafting claims under Section 112?\", \"How has the America Invents Act affected best mode requirements?\"]\n      reasoning {\n        analyze_legal_question { summary \"The legal question focuses on the requirements for a valid patent application under 35 U.S.C. § 112. This involves identifying the specific elements that must be present in a patent application to meet the statutory requirements for patentability.\" }\n        consider_relevant_legal_principles { summary \"Relevant legal principles include statutory interpretation of 35 U.S.C. § 112, which addresses the specification requirements, as well as any relevant case law that interprets and applies this statute.\" }\n        formulate_search_queries_strategy { summary \"Given the focus on 35 U.S.C. § 112, the search query strategy would prioritize direct references to the statute and its specific subsections.\" }\n        specify_expected_information_strategy { summary \"The search queries are expected to yield information that precisely explains the different elements of 35 U.S.C. § 112, including the written description, enablement, best mode, and claims requirements.\" }\n        ensure_comprehensive_coverage_strategy { summary \"To ensure comprehensive coverage, the search strategy would begin with a broad search of 35 U.S.C. § 112, then narrow the focus by searching for each individual component.\" }\n      }\n    }\n    query_history [\n      {\n        reasoning {\n          analyze_legal_question { summary \"The legal question focuses on the requirements for a valid patent application under 35 U.S.C. § 112. This involves identifying the specific elements that must be present in a patent application to meet the statutory requirements for patentability.\" }\n          consider_relevant_legal_principles { summary \"Relevant legal principles include statutory interpretation of 35 U.S.C. § 112, which addresses the specification requirements, as well as any relevant case law that interprets and applies this statute.\" }\n          formulate_search_queries_strategy { summary \"Given the focus on 35 U.S.C. § 112, the search query strategy would prioritize direct references to the statute and its specific subsections.\" }\n          specify_expected_information_strategy { summary \"The search queries are expected to yield information that precisely explains the different elements of 35 U.S.C. § 112, including the written description, enablement, best mode, and claims requirements.\" }\n          ensure_comprehensive_coverage_strategy { summary \"To ensure comprehensive coverage, the search strategy would begin with a broad search of 35 U.S.C. § 112, then narrow the focus by searching for each individual component.\" }\n        }\n        search_queries [\n          {\n            query_string \"patent application requirements 35 USC 112 specification\"\n            expected_information [\"patent specification requirements\", \"USPTO guidelines\", \"written description\"]\n          }\n        ]\n      }\n    ]\n  }\n  @@assert( {{ this.report_title | length > 10 }} )\n  @@assert( {{ this.executive_summary | length > 40 }} )\n  @@assert( {{ this.conclusion | length > 40 }} )\n  // Should generate structured report despite some gaps\n  @@assert( {{ this.sections | length >= 2 }} )\n  @@assert( {{ this.sections | length <= 5 }} )\n  \n  // Report should address 35 U.S.C. § 112 and patent requirements\n  @@assert( {{ (\"patent\" in (this.report_title | lower)) and (\"112\" in (this.report_title | lower)) }} )\n  @@assert( {{ (\"specification\" in (this.executive_summary | lower)) or (\"patent application\" in (this.executive_summary | lower)) or (\"35 u.s.c\" in (this.executive_summary | lower)) }} )\n  \n  // Should cover the four main requirements\n  @@assert( {{ (\"written description\" in (this.sections | map(attribute=\"content\") | join(\" \") | lower)) or (\"enablement\" in (this.sections | map(attribute=\"content\") | join(\" \") | lower)) or (\"best mode\" in (this.sections | map(attribute=\"content\") | join(\" \") | lower)) or (\"claims\" in (this.sections | map(attribute=\"content\") | join(\" \") | lower)) }} )\n  \n  // Should acknowledge limitations and need for additional research\n  @@assert( {{ (\"additional research\" in (this.conclusion | lower)) or (\"case law\" in (this.conclusion | lower)) or (\"practical\" in (this.conclusion | lower)) or (\"further analysis\" in (this.conclusion | lower)) }} )\n  \n  // Should still provide useful statutory guidance\n  @@assert( {{ (\"section 112\" in (this.sections | map(attribute=\"content\") | join(\" \") | lower)) or (\"patent act\" in (this.sections | map(attribute=\"content\") | join(\" \") | lower)) or (\"specification\" in (this.sections | map(attribute=\"content\") | join(\" \") | lower)) }} )\n  \n  // Content should be substantial despite gaps\n  @@assert( {{ (this.sections | map(attribute=\"content\") | join(\" \") | length) > 100 }} )\n}",
  "generators.baml": "// This helps use auto generate libraries you can use in the language of\n// your choice. You can have multiple generators if you use multiple languages.\n// Just ensure that the output_dir is different for each generator.\ngenerator target {\n    // Valid values: \"python/pydantic\", \"typescript\", \"ruby/sorbet\", \"rest/openapi\"\n    output_type \"typescript/react\"\n\n    // Where the generated code will be saved (relative to baml_src/)\n    output_dir \"../\"\n\n    // The version of the BAML package you have installed (e.g. same version as your baml-py or @boundaryml/baml).\n    // The BAML VSCode extension version should also match this version.\n    version \"0.89.0\"\n\n    // Valid values: \"sync\", \"async\"\n    // This controls what `b.FunctionName()` will be (sync or async).\n    default_client_mode async\n}\n",
  "types/analyzed_document.baml": "// Represents the LLM's detailed analysis of a single search result\nclass AnalyzedDocument {\n  search_result_id string @description(\"ID of the SearchResultItem being analyzed.\")\n  relevance_score int @description(\"A score from 1 (not relevant) to 10 (highly relevant) indicating the document's relevance to the original legal question.\") @alias(\"relevance\")\n  confidence_score int @description(\"A score from 1 (low confidence) to 10 (high confidence) in the relevance assessment.\") @alias(\"confidence\")\n  summary string @description(\"A concise summary of the document's key findings and holdings as they relate to the legal question.\")\n  key_arguments_and_reasoning string[] @description(\"List of key legal arguments, judicial reasoning, or statutory interpretations found in the document.\")\n  extracted_entities LegalEntity[] @description(\"Key legal entities (cases, statutes, persons, organizations) mentioned.\")\n  extracted_quotes string[] @description(\"Direct quotes from the document that are particularly pertinent.\")\n  counter_arguments_or_nuances string[]? @description(\"Any counter-arguments, dissenting opinions, or important nuances identified.\")\n  reasoning DetailedReasoning @description(\"LLM's thought process for analyzing this document.\")\n}",
  "types/final_report.baml": "class FinalLegalReport {\n  report_title string @description(\"A comprehensive title for the legal research report.\")\n  executive_summary string @description(\"A concise overview of the findings.\") @stream.with_state\n  sections LegalReportSection[] @description(\"The main sections of the report, logically structured.\")\n  conclusion string @description(\"The overall conclusion based on the research.\") @stream.with_state\n  limitations_and_caveats string[]? @description(\"Any limitations of the research or caveats to the findings.\")\n  appendix_document_ids string[]? @description(\"IDs of key SearchResultItems referenced in the report.\")\n}",
  "types/legal_entity.baml": "class LegalEntity {\n  name string\n  type \"Case\" | \"Statute\" | \"Regulation\" | \"Person\" | \"Organization\" | \"LegalConcept\" | \"Jurisdiction\"\n  details string? @description(\"Further details, e.g., citation for a case/statute, role of a person.\")\n}",
  "types/overall_synthesis.baml": "\n\nclass OverallSynthesis {\n  key_synthesized_topics SynthesizedTopic[] @description(\"A list of synthesized topics addressing different facets of the legal question.\")\n  unanswered_aspects string[]? @description(\"Aspects of the legal question not fully addressed by the current set of documents.\")\n  emerging_questions string[]? @description(\"New questions or research avenues that arose from the synthesis.\")\n  reasoning DetailedReasoning @description(\"LLM's thought process for the overall synthesis.\")\n}",
  "types/report_section.baml": "// For the final report\nclass LegalReportSection {\n  section_title string\n  content string @description(\"Detailed content for this section of the report, properly formatted with citations where appropriate (e.g., [SearchResultItem.id] or case/statute name).\") @stream.with_state\n  // We can add sub-sections recursively if needed: sub_sections LegalReportSection[]?\n}",
  "types/research_assessment.baml": "class ResearchAssessment {\n  is_sufficient bool @description(\"True if the current information is deemed sufficient to answer the legal question comprehensively.\")\n  assessment_summary string @description(\"Brief summary of why the research is or isn't sufficient.\") @stream.with_state\n  identified_gaps string[]? @description(\"Specific information gaps if research is insufficient.\")\n  next_action NextActionType @description(\"The recommended next action for the agent.\")\n  suggested_queries_for_refinement SearchQueryItem[]? @description(\"If next_action is REFINE_QUERIES or NEW_QUERIES, provide new/refined queries.\")\n  document_ids_for_deeper_analysis string[]? @description(\"If DEEPER_ANALYSIS, list IDs of SearchResultItem to re-analyze.\")\n  reasoning DetailedReasoning @description(\"LLM's thought process for this assessment.\")\n}",
  "types/search_queries.baml": "// Represents a single step in the detailed reasoning process.\nclass ReasoningStep {\n  summary string @description(\"Key findings, rationale, and detailed thought process for this specific analysis step. Should be comprehensive.\") @stream.with_state\n  items_considered string[]? @description(\"A list of specific legal concepts, terms, facts, statutes, cases, or principles identified, considered, or analyzed in this step.\")\n  // Default streaming for string[] means items may stream partially.\n  // If you want each item in the list to be fully formed before appearing, you could use:\n  // items_considered (string @stream.done)[]?\n}\n\n// Structured representation of the LLM's thought process.\nclass DetailedReasoning {\n  // Ensure the structure of each reasoning step appears as soon as possible.\n  analyze_legal_question ReasoningStep @description(\"Step 1: Analysis of the legal question (main issues, key concepts, jurisdiction, crucial facts, initial legal theories).\") @stream.not_null\n  consider_relevant_legal_principles ReasoningStep @description(\"Step 2: Consideration of relevant legal principles (constitutional law, statutory interpretations, legal doctrines, counterarguments, jurisdiction-specific interpretations).\") @stream.not_null\n  formulate_search_queries_strategy ReasoningStep @description(\"Step 3: Strategy for formulating search queries (use of Boolean operators, exact phrases, wildcards, proximity operators, date restrictions, relevant legal terminology).\") @stream.not_null\n  specify_expected_information_strategy ReasoningStep @description(\"Step 4: Approach for specifying what information is expected from each query (case law, statutes, legal principles, scholarly articles).\") @stream.not_null\n  ensure_comprehensive_coverage_strategy ReasoningStep @description(\"Step 5: Plan for ensuring the set of queries provides comprehensive coverage of the legal question while avoiding redundancy.\") @stream.not_null\n}\n\nclass SearchQueryItem {\n  query_string string @description(#\"\n    The formulated search query string.\n    Example: '\"Title VII\" AND (\"adverse employment action\" OR \"disparate treatment\") AND \"circuit court\"'\n  \"#)\n  expected_information string[] @description(#\"\n    A list of specific types of information expected to be gathered using this query.\n    Example: [\n      \"Circuit court cases interpreting Title VII in the context of adverse employment actions or disparate treatment.\",\n      \"Key elements required to establish a prima facie case of employment discrimination under Title VII.\",\n      \"Notable exceptions or defenses to Title VII claims discussed in relevant precedents.\"\n    ]\n  \"#)\n  // Stream each SearchQueryItem as a complete unit.\n  @@stream.done\n}\n\n// Final output structure.\nclass LegalQueryAnalysis {\n  reasoning DetailedReasoning @description(\"Structured thought process for analyzing the legal question and formulating search queries, following the 5-step analysis.\")\n  search_queries SearchQueryItem[] @description(\"A list of 3-5 effective search queries, each with its query string and expected information.\")\n}\n",
