          {
            query_string "employment discrimination Title VII adverse action"
            expected_information ["adverse employment action definition", "Title VII cases", "discrimination law"]
          },
          {
            query_string "tangible employment action Title VII harassment"
            expected_information ["tangible employment action", "employer liability", "harassment defense"]
          }
        ]
      }
    ]
  }
  @@assert( {{ this.report_title | length > 10 }} )
  @@assert( {{ this.executive_summary | length > 50 }} )
  @@assert( {{ this.conclusion | length > 50 }} )
  // Should generate comprehensive report for well-researched topic
  @@assert( {{ this.sections | length >= 3 }} )
  @@assert( {{ this.sections | length <= 7 }} )

  // Basic content validation - simplified
  @@assert( {{ this.report_title | length > 0 }} )
  @@assert( {{ this.sections | length > 0 }} )

  // Basic structure check - simplified for robustness
  @@assert( {{ this.sections | length > 0 }} )
  @@assert( {{ this.appendix_document_ids | length > 0 }} )
}

// NEW TEST: Live data report generation - Patent law with gaps requiring additional research
test GenerateLivePatentRequirementsReport {
  functions [GenerateFinalLegalReport]
  args {
    original_legal_question "What are the requirements for a valid patent application under 35 U.S.C. § 112?"
    synthesis {
      key_synthesized_topics [
        {
          topic_title "Section 112 Requirements Overview"
          synthesis "Section 112 of the Patent Act, codified as 35 U.S.C. § 112, outlines the requirements for the specification of a patent application. The document explains the four key components: written description, enablement requirement, best mode requirement, and claims. However, the synthesis lacks detailed case law analysis and practical application examples."
          confidence_score 7
          supporting_document_ids ["https://vernalaw.com/why-is-section-112-of-the-patent-act-important/"]
        }
      ]
      unanswered_aspects ["Case law interpretations of each requirement", "Practical examples of compliant specifications", "Common rejection reasons under 35 U.S.C. § 112", "Recent changes in USPTO examination guidelines"]
      emerging_questions ["How do courts interpret the 'written description' requirement in practice?", "What are common pitfalls in drafting claims under Section 112?", "How has the America Invents Act affected best mode requirements?"]
      reasoning {
        analyze_legal_question { summary "The legal question focuses on the requirements for a valid patent application under 35 U.S.C. § 112. This involves identifying the specific elements that must be present in a patent application to meet the statutory requirements for patentability." }
        consider_relevant_legal_principles { summary "Relevant legal principles include statutory interpretation of 35 U.S.C. § 112, which addresses the specification requirements, as well as any relevant case law that interprets and applies this statute." }
        formulate_search_queries_strategy { summary "Given the focus on 35 U.S.C. § 112, the search query strategy would prioritize direct references to the statute and its specific subsections." }
        specify_expected_information_strategy { summary "The search queries are expected to yield information that precisely explains the different elements of 35 U.S.C. § 112, including the written description, enablement, best mode, and claims requirements." }
        ensure_comprehensive_coverage_strategy { summary "To ensure comprehensive coverage, the search strategy would begin with a broad search of 35 U.S.C. § 112, then narrow the focus by searching for each individual component." }
      }
    }
    query_history [
      {
        reasoning {
          analyze_legal_question { summary "The legal question focuses on the requirements for a valid patent application under 35 U.S.C. § 112. This involves identifying the specific elements that must be present in a patent application to meet the statutory requirements for patentability." }
          consider_relevant_legal_principles { summary "Relevant legal principles include statutory interpretation of 35 U.S.C. § 112, which addresses the specification requirements, as well as any relevant case law that interprets and applies this statute." }
          formulate_search_queries_strategy { summary "Given the focus on 35 U.S.C. § 112, the search query strategy would prioritize direct references to the statute and its specific subsections." }
          specify_expected_information_strategy { summary "The search queries are expected to yield information that precisely explains the different elements of 35 U.S.C. § 112, including the written description, enablement, best mode, and claims requirements." }
          ensure_comprehensive_coverage_strategy { summary "To ensure comprehensive coverage, the search strategy would begin with a broad search of 35 U.S.C. § 112, then narrow the focus by searching for each individual component." }
        }
        search_queries [
          {
            query_string "patent application requirements 35 USC 112 specification"
            expected_information ["patent specification requirements", "USPTO guidelines", "written description"]
          }
        ]
      }
    ]
  }
  @@assert( {{ this.report_title | length > 10 }} )
  @@assert( {{ this.executive_summary | length > 40 }} )
  @@assert( {{ this.conclusion | length > 40 }} )
  // Should generate structured report despite some gaps
  @@assert( {{ this.sections | length >= 2 }} )
  @@assert( {{ this.sections | length <= 5 }} )

  // Report should address 35 U.S.C. § 112 and patent requirements
  @@assert( {{ ("patent" in (this.report_title | lower)) and ("112" in (this.report_title | lower)) }} )
  @@assert( {{ ("specification" in (this.executive_summary | lower)) or ("patent application" in (this.executive_summary | lower)) or ("35 u.s.c" in (this.executive_summary | lower)) }} )

  // Should cover the four main requirements
  @@assert( {{ ("written description" in (this.sections | map(attribute="content") | join(" ") | lower)) or ("enablement" in (this.sections | map(attribute="content") | join(" ") | lower)) or ("best mode" in (this.sections | map(attribute="content") | join(" ") | lower)) or ("claims" in (this.sections | map(attribute="content") | join(" ") | lower)) }} )

  // Should acknowledge limitations and need for additional research
  @@assert( {{ ("additional research" in (this.conclusion | lower)) or ("case law" in (this.conclusion | lower)) or ("practical" in (this.conclusion | lower)) or ("further analysis" in (this.conclusion | lower)) }} )

  // Should still provide useful statutory guidance
  @@assert( {{ ("section 112" in (this.sections | map(attribute="content") | join(" ") | lower)) or ("patent act" in (this.sections | map(attribute="content") | join(" ") | lower)) or ("specification" in (this.sections | map(attribute="content") | join(" ") | lower)) }} )

  // Content should be substantial despite gaps
  @@assert( {{ (this.sections | map(attribute="content") | join(" ") | length) > 100 }} )
}



# BAML Testing Guidelines

## Tests in BAML

Tests are first-class citizens in BAML, designed to make testing AI functions straightforward and robust. BAML tests can be written anywhere in your codebase and run with minimal setup.

### Overview

A BAML test consists of:
- Test name and metadata
- Functions under test
- Input arguments
- Optional testing configuration
- Optional assertions
- Optional type builders

```baml
test TestName {
    functions [FunctionName]
    args {
        paramName "value"
    }
}
```

### Test Declaration

#### Basic Syntax

```baml
test name {
    functions [function_list]
    args {
        parameter_assignments
    }
}
```

#### Optional Features

```baml {3-11, 15, 16}
test name {
    functions [function_list]
    type_builder {
        class NewType {
            // Props
        }
        dynamic class ExistingDynamicType {
            new_prop NewType
            // Inject Props Here
        }
    }
    args {
        parameter_assignments
    }
    @@check( check_length, {{ this.prop|length > 0 }} )
    @@assert( {{ this.prop|length < 255 }})
}
```

#### Components

- `name`: Test identifier (unique per function)
- `functions`: List of functions to test
- `args`: Input parameters for the test case
- `type_builder`: Block used to inject values into dynamic types
- `@@check`: Conditional check for test validity
- `@@assert`: Assertion for test result

### Input Types

#### Basic Types

Simple values are provided directly:

```baml
test SimpleTest {
    functions [ClassifyMessage]
    args {
        input "Can't access my account"
    }
}
```

#### Complex Objects

Objects are specified using nested structures:

```baml
test ComplexTest {
    functions [ProcessMessage]
    args {
        message {
            user "john_doe"
            content "Hello world"
            metadata {
                timestamp 1234567890
                priority "high"
            }
        }
    }
}
```

#### Arrays

Arrays use bracket notation:

```baml
test ArrayTest {
    functions [BatchProcess]
    args {
        messages [
            {
                user "user1"
                content "Message 1"
            }
            {
                user "user2"
                content "Message 2"
            }
        ]
    }
}
```

### Media Inputs

#### Images

Images can be specified using three methods:

1. **File Reference**

```baml {4-6}
test ImageFileTest {
    functions [AnalyzeImage]
    args {
        param {
            file "../images/test.png"
        }
    }
}
```

2. **URL Reference**

```baml {4-6}
test ImageUrlTest {
    functions [AnalyzeImage]
    args {
        param {
            url "https://example.com/image.jpg"
        }
    }
}
```

3. **Base64 Data**

```baml {4-7}
test ImageBase64Test {
    functions [AnalyzeImage]
    args {
        param {
            base64 "a41f..."
            media_type "image/png"
        }
    }
}
```

#### Audio

Similar to images, audio can be specified in three ways:

1. **File Reference**

```baml
test AudioFileTest {
    functions [TranscribeAudio]
    args {
        audio {
            file "../audio/sample.mp3"
        }
    }
}
```

2. **URL Reference**

```baml
test AudioUrlTest {
    functions [TranscribeAudio]
    args {
        audio {
            url "https://example.com/audio.mp3"
        }
    }
}
```

3. **Base64 Data**

```baml
test AudioBase64Test {
    functions [TranscribeAudio]
    args {
        audio {
            base64 "..."
            media_type "audio/mp3"
        }
    }
}
```

### Multi-line Strings

For long text inputs, use the block string syntax:

```baml
test LongTextTest {
    functions [AnalyzeText]
    args {
        content #"
            This is a multi-line
            text input that preserves
            formatting and whitespace
        "#
    }
}
```

### Testing Multiple Functions

This requires each function to have the exact same parameters:

```baml
test EndToEndFlow {
    functions [
        ExtractInfo
        ProcessInfo
        ValidateResult
    ]
    args {
        input "test data"
    }
}
```

### Testing Dynamic Types

Dynamic types can be tested using `type_builder` and `dynamic` blocks:

```baml {3, 12-16}
class DynamicClass {
    static_prop string
    @@dynamic
}

function ReturnDynamicClass(input: string) -> DynamicClass {
    // ...
}

test DynamicClassTest {
    functions [ReturnDynamicClass]
    type_builder {
        dynamic class DynamicClass {
            new_prop_here string
        }
    }
    args {
        input "test data"
    }
}
```

## `@assert attribute

The `@assert` attribute in BAML is used for strict validations. If a type fails an `@assert` validation, it will not be returned in the response, and an exception will be raised if it's part of the top-level type.

### Usage

Asserts can be named or unnamed.

#### Field Assertion

```baml BAML
class Foo {
  // @assert will be applied to the field with the name "bar"
  bar int @assert(between_0_and_10, {{ this > 0 and this < 10 }})
}
```

```baml BAML
class Foo {
  // @assert will be applied to the field with no name
  bar int @assert({{ this > 0 and this < 10 }})
}
```

```baml BAML
class MyClass {
  // @assert will be applied to each element in the array
  my_field (string @assert(is_valid_email, {{ this|regex_match("@") }}))[]
}
```

#### Parameter Assertion

Asserts can also be applied to parameters.

```baml BAML
function MyFunction(x: int @assert(between_0_and_10, {{ this > 0 and this < 10 }})) {
  client "openai/gpt-4o"
  prompt #"Hello, world!"#
}
```

#### Block Assertion

Asserts can be used in a block definition, referencing fields within the block.

```baml BAML
class Foo {
  bar int
  baz string
  @@assert(baz_length_limit, {{ this.baz|length < this.bar }})
}
```

See [Jinja in Attributes](/ref/attributes/jinja-in-attributes) for a longer description of the Jinja syntax
available in asserts.

## Jinja in Attributes
`@check` and `@assert` use [Jinja](/ref/prompt-syntax/what-is-jinja) syntax to specify the invariants
(properties that should always hold true) of a type.

### Checks and Asserts

This example demonstrates [@assert](/ref/attributes/assert) and [@check](/ref/attributes/check) on both class fields
and the class block itself, and it shows a few examples of Jinja syntax.

```baml BAML
class Student {
    first_name string @assert( {{ this|length > 0 }})
    last_name string @assert( {{ this|length > 0 }})
    age int @check(old_enough, {{ this > 5 }}) @check(u8, {{ this|abs < 255 }})
    concentration string @assert( {{ this.regex_match("[Math|Science]")}})
    @@check(age_threshold, {{ this.concentration != "calculus" or this.age > 12 }})
}
```

### `this` keyword

Inside a Jinja expression, `this` refers to the value of a class field, if the
`@assert` or `@check` is applied to a class field, and it applies to the whole
object if it is applied to the whole type with `@@assert()` or `@@check()`.

### Filters

In Jinja, functions are called "filters", and they are applied to arguments
by writing `some_argument|some_filter`. Filters can be applied one after the
other by chaining them with additional `|`s.

 - `abs`: Absolote value.
 - `capitalize`: Make the first letter uppercase
 - `escape`: Replace special HTML characters with their escaped counterparts
 - `first`: First item of a list
 - `last`: Last item of a list
 - `default(x)`: Returns `x` when applied to something undefined.
 - `float`: Convert to a float, or 0.0 if conversion fails
 - `int`: Convert to an int, or 0 if conversion fails
 - `join`: Concatenate a list of strings
 - `length`: List length
 - `lower`: Make the string lowercase
 - `upper`: Make the string uppercase
 - `map(filter)`: Apply a filter to each item in a list
 - `max`: Maximum of a list of numbers or Booleans
 - `min`: Minimum of a list of numbers or Booleans
 - `regex_match("regex")`: Return true if argument matches the regex
 - `reject("test")`: Filter out items that fail the test
 - `reverse`: Reverse a list or string
 - `round`: Round a float to the nearest int
 - `select("test_name")`: Retain the values of a list passing `test_name`
 - `sum`: Sum of a list of numbers
 - `title`: Convert a string to "Title Case"
 - `trim`: Remove leading and trailing whitespace from a string
 - `unique`: Remove duplicate entries in a list

### Common Patterns

#### Test that a substring appears inside some string

 ```baml BAML
 function GenerateStory(subject: string) -> string {
   client GPT4
   prompt #"Write a story about {{ subject }}"#
 }

 test HorseStory {
    functions [GenerateStory]
    args {
        subject "Equestrian team coming-of-age story"
    }
    @@assert( {{ this|lower|regex_match("horse") }} )
 }
 ```

 We use the `lower` filter to make the whole story lowercase, and pass
 the result to `regex_match()` to search for an occurrance of "horse".

#### Test that a string is an exact match

```baml BAML
class Person {
    first_name string
    last_name string
}

function ExtractPerson(description: string) -> Person {
    client GPT4
    prompt #"
      Extract a Person from the description {{ description }}.
      {{ ctx.output_format }}
    "#
}

test ExtractJohnDoe {
    functions [ExtractPerson]
    args {
        description "John Doe is a 5'6\" man riding a stolen horse."
    }
    @@assert( {{ this.first_name|regex_match("^John$") }} )
    @@assert( {{ this.last_name == "Doe" }} )
}
```

We can use `regex_match` with special control characters indicating
the beginning and end of a string, as in the first `@@assert`, or
simply check equality with a literal string as in the second `@@assert`.

#### Test that item prices add up to a total

```baml BAML
class Receipt {
    establishment string
    items Item[]
    tax_cents int
    total_cents int
}

class Item {
    name string
    price_cents int
}

function ExtractReceipt(text_receipt: string) -> Receipt {
    client GPT4
    prompt #"
      Extract the details of this receipt: {{ text_receipt }}
      {{ ctx.output_format }}
    "#
}

test SmallReceipt {
    functions [ExtractReceipt]
    args {
        text_receipt "Nutty Squirrel. Affogato: $8.50. Kids cone: $6.50. Tax: $1. Total: $16.00"
    }

    @@assert( {{ this.items|map(attribute="price_cents")|sum + this.tax_cents == this.total_cents }} )
}
```

To check that the numbers in our `Receipt` add up, we first
`map` over the items to get the price of each item, then sum
the list of prices, and check the sum of the items and the sales
tax against the receipt total.



// Represents the LLM's detailed analysis of a single search result
class AnalyzedDocument {
  search_result_id string @description("ID of the SearchResultItem being analyzed.")
  relevance_score int @description("A score from 1 (not relevant) to 10 (highly relevant) indicating the document's relevance to the original legal question.") @alias("relevance")
  confidence_score int @description("A score from 1 (low confidence) to 10 (high confidence) in the relevance assessment.") @alias("confidence")
  summary string @description("A concise summary of the document's key findings and holdings as they relate to the legal question.")
  key_arguments_and_reasoning string[] @description("List of key legal arguments, judicial reasoning, or statutory interpretations found in the document.")
  extracted_entities LegalEntity[] @description("Key legal entities (cases, statutes, persons, organizations) mentioned.")
  extracted_quotes string[] @description("Direct quotes from the document that are particularly pertinent.")
  counter_arguments_or_nuances string[]? @description("Any counter-arguments, dissenting opinions, or important nuances identified.")
  reasoning DetailedReasoning @description("LLM's thought process for analyzing this document.")
}



class FinalLegalReport {
  report_title string @description("A comprehensive title for the legal research report.")
  executive_summary string @description("A concise overview of the findings.") @stream.with_state
  sections LegalReportSection[] @description("The main sections of the report, logically structured.")
  conclusion string @description("The overall conclusion based on the research.") @stream.with_state
  limitations_and_caveats string[]? @description("Any limitations of the research or caveats to the findings.")
  appendix_document_ids string[]? @description("IDs of key SearchResultItems referenced in the report.")
}



class LegalEntity {
  name string
  type "Case" | "Statute" | "Regulation" | "Person" | "Organization" | "LegalConcept" | "Jurisdiction"
  details string? @description("Further details, e.g., citation for a case/statute, role of a person.")
}



class OverallSynthesis {
  key_synthesized_topics SynthesizedTopic[] @description("A list of synthesized topics addressing different facets of the legal question.")
  unanswered_aspects string[]? @description("Aspects of the legal question not fully addressed by the current set of documents.")
  emerging_questions string[]? @description("New questions or research avenues that arose from the synthesis.")
  reasoning DetailedReasoning @description("LLM's thought process for the overall synthesis.")
}



// For the final report
class LegalReportSection {
  section_title string
  content string @description("Detailed content for this section of the report, properly formatted with citations where appropriate (e.g., [SearchResultItem.id] or case/statute name).") @stream.with_state
  // We can add sub-sections recursively if needed: sub_sections LegalReportSection[]?
}



class ResearchAssessment {
  is_sufficient bool @description("True if the current information is deemed sufficient to answer the legal question comprehensively.")
  assessment_summary string @description("Brief summary of why the research is or isn't sufficient.") @stream.with_state
  identified_gaps string[]? @description("Specific information gaps if research is insufficient.")
  next_action NextActionType @description("The recommended next action for the agent.")
  suggested_queries_for_refinement SearchQueryItem[]? @description("If next_action is REFINE_QUERIES or NEW_QUERIES, provide new/refined queries.")
  document_ids_for_deeper_analysis string[]? @description("If DEEPER_ANALYSIS, list IDs of SearchResultItem to re-analyze.")
  reasoning DetailedReasoning @description("LLM's thought process for this assessment.")
}



// Represents a single step in the detailed reasoning process.
class ReasoningStep {
  summary string @description("Key findings, rationale, and detailed thought process for this specific analysis step. Should be comprehensive.") @stream.with_state
  items_considered string[]? @description("A list of specific legal concepts, terms, facts, statutes, cases, or principles identified, considered, or analyzed in this step.")
  // Default streaming for string[] means items may stream partially.
  // If you want each item in the list to be fully formed before appearing, you could use:
  // items_considered (string @stream.done)[]?
}

// Structured representation of the LLM's thought process.
class DetailedReasoning {
  // Ensure the structure of each reasoning step appears as soon as possible.
  analyze_legal_question ReasoningStep @description("Step 1: Analysis of the legal question (main issues, key concepts, jurisdiction, crucial facts, initial legal theories).") @stream.not_null
  consider_relevant_legal_principles ReasoningStep @description("Step 2: Consideration of relevant legal principles (constitutional law, statutory interpretations, legal doctrines, counterarguments, jurisdiction-specific interpretations).") @stream.not_null
  formulate_search_queries_strategy ReasoningStep @description("Step 3: Strategy for formulating search queries (use of Boolean operators, exact phrases, wildcards, proximity operators, date restrictions, relevant legal terminology).") @stream.not_null
  specify_expected_information_strategy ReasoningStep @description("Step 4: Approach for specifying what information is expected from each query (case law, statutes, legal principles, scholarly articles).") @stream.not_null
  ensure_comprehensive_coverage_strategy ReasoningStep @description("Step 5: Plan for ensuring the set of queries provides comprehensive coverage of the legal question while avoiding redundancy.") @stream.not_null
}

class SearchQueryItem {
  query_string string @description(#"
    The formulated search query string.
    Example: '"Title VII" AND ("adverse employment action" OR "disparate treatment") AND "circuit court"'
  "#)
  expected_information string[] @description(#"
    A list of specific types of information expected to be gathered using this query.
    Example: [
      "Circuit court cases interpreting Title VII in the context of adverse employment actions or disparate treatment.",
      "Key elements required to establish a prima facie case of employment discrimination under Title VII.",
      "Notable exceptions or defenses to Title VII claims discussed in relevant precedents."
    ]
  "#)
  // Stream each SearchQueryItem as a complete unit.
  @@stream.done
}

// Final output structure.
class LegalQueryAnalysis {
  reasoning DetailedReasoning @description("Structured thought process for analyzing the legal question and formulating search queries, following the 5-step analysis.")
  search_queries SearchQueryItem[] @description("A list of 3-5 effective search queries, each with its query string and expected information.")
}



// Represents a single document retrieved from a search query
class SearchResultItem {
  id string @description("Unique identifier for this search result, typically the URL or an Exa-specific ID.")
  url string @description("The direct URL of the search result.")
  title string? @description("Title of the document or webpage.")
  source_name string @description("Name of the search engine or source, e.g., 'Exa Search'.")
  snippet string? @description("A concise snippet or abstract of the document content. Often derived from Exa highlights.")
  // highlights string[]? @description("Direct highlight snippets from Exa, if requested.") // Alternative to single snippet
  full_text string? @description("The full text content of the document, if retrieved via Exa's contents feature.")
  published_date string? @description("Estimated publication date of the document (e.g., YYYY-MM-DD) as provided by Exa.")
  retrieval_date string @description("ISO8601 timestamp indicating when this item was retrieved by the agent.")
  author string? @description("Author of the content, if provided by Exa.")
  score float? @description("Relevance score from Exa (0 to 1), if available.")
  original_query SearchQueryItem? @description("The BAML SearchQueryItem that led to this result.")
  // Store Exa's specific ID if BAML's 'id' field is used for the URL or another identifier
  metadata map? @description("Additional metadata, e.g., {'exa_internal_id': 'exa_id_value', 'exa_autoprompt': 'autoprompt_string_if_any'}")
}



// For synthesizing findings from multiple documents
class SynthesizedTopic {
  topic_title string @description("A title for this synthesized topic or legal principle.")
  synthesis string @description("A coherent synthesis of information related to this topic, drawing from multiple analyzed documents. Should explain convergences, divergences, and overall themes.")
  supporting_document_ids string[] @description("IDs of the AnalyzedDocuments that support this synthesis.")
  confidence_score int @description("Confidence in the accuracy and completeness of this synthesis (1-10).")
}



# CLAUDE.md - BAML Guidelines

This guide provides essential instructions and context for working within the `/baml_src` directory of the LexiSynth project. This directory contains all BAML (Boundary AI Markup Language) definitions, which are crucial for the AI-powered legal research pipeline.

**Your primary goal when working here is to define, test, and refine the LLM interactions (prompts, schemas, client configurations) that drive LexiSynth's intelligence.**

## 1. Overview of `/baml_src` Directory Structure

*   **`clients.baml`**:
    *   **Purpose**: Defines LLM client configurations (e.g., `QueryGeneration`, `DocumentAnalysis`). Specifies providers (Google AI, OpenAI, Anthropic), models, API key environment variables (e.g., `env.GOOGLE_API_KEY`), and retry policies (`TestSafely`, `Constant`).
    *   **Usage**: When defining BAML functions, you'll select a client from here (e.g., `client QueryGeneration;`).

*   **`core_loop.baml`** (and `core_loop.test.baml`):
    *   **Purpose**: Contains the `AssessResearchAndPlanNextSteps` BAML function. This is a critical decision-making step in the research pipeline.
    *   **Focus**: The prompt here involves complex logic to guide the LLM in assessing research sufficiency and determining the next action (e.g., refine queries, generate report).

*   **`functions/`**:
    *   **Purpose**: Contains individual BAML functions for each distinct stage of the AI pipeline (e.g., `1-generate_queries.baml`, `2-analyze_document.baml`).
    *   **Structure**: Each `.baml` file typically defines one main function.
    *   **Testing**: Each function file MUST have a corresponding `.test.baml` file (e.g., `1-generate_queries.test.baml`).
    *   **`functions/CLAUDE.md`**: **IMPORTANT META-DOCUMENTATION!** This file is **your primary guide for BAML testing syntax, Jinja filters, and best practices for writing assertions (`@@assert`).** Refer to this extensively when creating or modifying BAML tests.

*   **`generators.baml`**:
    *   **Purpose**: Configures the BAML code generator.
    *   **Key Settings**:
        *   `output_type "typescript/react"`: Specifies generation of TypeScript clients and React hooks.
        *   `output_dir "../"`: Generated code goes into the root `baml_client/` directory.
        *   `version "0.89.0"`: Ensures compatibility with the installed `@boundaryml/baml` package. Keep this aligned.
        *   `default_client_mode async`: Generated client calls are asynchronous by default.

*   **`types/`**:
    *   **Purpose**: Defines all BAML `class` and `enum` type definitions used throughout the pipeline (e.g., `analyzed_document.baml`, `final_report.baml`, `legal_entity.baml`, `search_queries.baml`).
    *   **Streaming**: Pay close attention to streaming annotations:
        *   `@stream.with_state`: For fields that should be progressively built and where the client needs to know if the field is "Pending", "Incomplete", or "Complete" (e.g., `FinalLegalReport.executive_summary`, `LegalReportSection.content`). This is reflected in `baml_client/partial_types.ts`.
        *   `@@stream.done`: For types or fields that should be delivered atomically, not streamed character by character (e.g., `SearchQueryItem`).
    *   **Descriptions**: Use `@description` generously to clarify the purpose of types and fields.

## 2. Core BAML Development Workflow

1.  **Define/Modify Types (`types/*.baml`)**:
    *   Start by defining the data structures your LLM will consume or produce.
    *   Apply streaming annotations (`@stream.with_state`, `@@stream.done`) thoughtfully based on UI requirements for progressive display.

2.  **Define/Modify Functions (`functions/*.baml`, `core_loop.baml`)**:
    *   Write or refine the prompt. Use Jinja templating (`{{ ... }}`) for dynamic content.
    *   Clearly instruct the LLM on the desired output format, often using `{{ ctx.output_format }}` to inject the JSON schema of the return type.
    *   Select an appropriate LLM client defined in `clients.baml`.

3.  **Configure Clients (`clients.baml`)** (if necessary):
    *   Add new clients or adjust existing ones (model, provider, retry policy).

4.  **Write/Update Tests (`*.test.baml`)**:
    *   **This is a MANDATORY step for every BAML function.**
    *   Create diverse test cases covering various input scenarios (simple, complex, edge cases).
    *   Use `args { ... }` to define test inputs.
    *   Use `@@assert( {{ ... }} )` to validate output structure and key content.
    *   **Refer to `@functions/CLAUDE.md` for detailed guidance on Jinja filters and assertion syntax (e.g., `{{ this|length > 0 }}`, `{{ this.field == "value" }}`, `{{ "keyword" in (this.summary | lower) }}`).**

5.  **Run BAML Tests (`bun baml:test`)**:
    *   Iterate on prompts and type definitions until all relevant tests pass.
    *   Use the BAML VSCode extension's "Playground" feature to test individual function calls with specific inputs interactively. This is excellent for debugging prompts.
    *   To run tests for a single function: `bun baml:test -i {$FunctionName}::` (e.g., `bun baml:test -i GenerateLegalSearchQueries::`).

6.  **Regenerate BAML Client (`bun baml:generate`)**:
    *   **CRUCIAL**: After **any** change to `.baml` files (types, functions, clients, generators), you **MUST** run this command.
    *   This updates the `/baml_client` directory with new TypeScript types, client methods, and React hooks.

## 3. Key BAML Concepts & Best Practices

*   **Prompt Engineering**:
    *   Be explicit and structured in your prompts.
    *   Clearly define the persona/role of the LLM.
    *   Provide context using Jinja variables (e.g., `{{original_legal_question}}`).
    *   Guide the LLM towards the desired output format using `{{ ctx.output_format }}`.
    *   Use examples within prompts (few-shot prompting) if the task is complex or the LLM struggles with the format.
*   **Schema-First**: Define robust BAML `class` and `enum` types in `/types`. These schemas are compiled and used for validating LLM outputs and generating typed clients.
*   **Streaming**:
    *   `@stream.with_state` on a field (e.g., `summary string @stream.with_state`) means the generated client will provide information on whether this field is "Pending", "Incomplete", or "Complete" during streaming. This is used for fields that are built token by token (like a long report section).
    *   `@@stream.done` on a class (e.g., `class SearchQueryItem { ... @@stream.done }`) means instances of this class will be yielded whole, not partially, when part of a streamed list.
    *   Refer to `types/final_report.baml`, `types/report_section.baml` (for `@stream.with_state`) and `types/search_queries.baml` (for `@@stream.done` on `SearchQueryItem`) for examples.
*   **Testing**:
    *   **MANDATORY**. Write tests *before or alongside* BAML function implementation.
    *   Cover happy paths, edge cases (empty inputs, unexpected values), and variations in input complexity.
    *   Assertions should check for structural correctness and key content elements.
    *   **Consult `@functions/CLAUDE.md` for advanced assertion techniques (Jinja filters like `selectattr`, `map`, `join`, `lower`, `regex_match`).**
*   **LLM Client Configuration (`clients.baml`)**:
    *   Use specific clients for different tasks if performance/cost/capability trade-offs are needed (e.g., a faster model for `DecidesNextStep`, a more powerful one for `GenerateFinalReport`).
    *   Define retry policies (`TestSafely`, `Constant`) to handle transient LLM API errors.
*   **Modularity**: Break down complex LLM tasks into smaller, manageable BAML functions. The LexiSynth pipeline (GenerateQueries -> Analyze -> Synthesize -> Assess -> Report) exemplifies this.

## 4. Working with Specific File Types in `/baml_src`

*   **Type Definitions (`types/*.baml`)**:
    *   Focus: Field names, BAML types (e.g., `string`, `int`, `bool`, `YourCustomClass[]`, `map`), optionality (`?`), descriptions (`@description`), and streaming annotations (`@stream.with_state`, `@@stream.done`).
*   **Function Definitions (`functions/*.baml`, `core_loop.baml`)**:
    *   Focus: Input parameters, output type, `client` selection, and the `prompt` content.
    *   The prompt is the core logic. Ensure it's clear, provides necessary context via `{{ ... }}`, and explicitly requests output matching `{{ ctx.output_format }}`.
*   **Test Files (`*.test.baml`)**:
    *   Focus: Defining `test YourTestName { functions [FunctionToTest]; args { ... }; @@assert( ... ); }`.
    *   The `args` block must exactly match the input parameters of the function under test.
    *   `@@assert` clauses use Jinja to validate `this` (the function's output).
*   **`clients.baml`**:
    *   Focus: `client ClientName { provider ...; options { model ...; api_key ...; }; retry_policy ...; }`.
*   **`generators.baml`**:
    *   Usually stable, but verify `version` matches the installed `@boundaryml/baml` package version.

## 5. Important Commands (Run from Project Root)

*   **`bun baml:generate`**: **Run this after ANY change to ANY `.baml` file.** It updates the `/baml_client` directory.
*   **`bun baml:test`**: Runs all BAML tests defined in `.test.baml` files.
*   **`bun baml:test -i {$FunctionName}::`**: Runs all tests for a specific BAML function. Useful for focused development.
    *   Example: `bun baml:test -i GenerateLegalSearchQueries::`

## 6. Relationship with `/baml_client`

*   The `/baml_client` directory is **ENTIRELY AUTO-GENERATED** by the `bun baml:generate` command based on the contents of `/baml_src`.
*   **NEVER MANUALLY EDIT FILES IN `/baml_client`.** Your changes will be overwritten.
*   All changes to BAML logic, types, or client configurations must be made in `/baml_src`, followed by client regeneration.

## 7. Troubleshooting Common BAML Issues

*   **Client Generation Fails**:
    *   Check for syntax errors in your `.baml` files. The BAML VSCode extension should highlight these.
    *   Ensure `generators.baml` is correctly configured and the BAML version matches.
*   **BAML Tests Fail**:
    *   **Input Issues**: Double-check the `args {}` block in your `.test.baml` file. Does it provide all required inputs in the correct format?
    *   **Prompt Issues**: The LLM might not be understanding your prompt correctly. Use the BAML Playground (in VSCode extension) to experiment with the prompt and inputs live.
    *   **Schema Mismatch**: The LLM output might not conform to the BAML function's return type. Refine the prompt to be more explicit about the output structure, or adjust the BAML type definition.
    *   **Assertion Failures**: Your `@@assert` logic might be incorrect, or the LLM output is not meeting expectations.
*   **Type Errors in Main TypeScript Code (after `baml:generate`)**:
    *   This usually means your BAML type definitions have changed, and the TypeScript code using the old types in `/baml_client` needs to be updated.
    *   Ensure you're importing types correctly from `@/baml_client/types` or `@/baml_client/partial_types`.

By following these guidelines, you can effectively contribute to the AI core of LexiSynth. Remember to test thoroughly and regenerate the client after making any changes in `/baml_src`. The `functions/CLAUDE.md` file is your best friend for writing effective BAML tests.
```



// Learn more about clients at https://docs.boundaryml.com/docs/snippets/clients/overview

client QueryGeneration {
  provider google-ai
  retry_policy TestSafely
  options {
    model "gemini-2.0-flash-lite"
    api_key env.GOOGLE_API_KEY
  }
}

client DocumentAnalysis {
  provider google-ai
  retry_policy TestSafely
  options {
    model "gemini-2.0-flash-lite"
    api_key env.GOOGLE_API_KEY
  }
}

client FindingsSynthetizing {
  provider google-ai
  retry_policy TestSafely
  options {
    model "gemini-2.0-flash-lite"
    api_key env.GOOGLE_API_KEY
  }
}

client DecidesNextStep {
  provider google-ai
  retry_policy TestSafely
  options {
    model "gemini-2.0-flash-lite"
    api_key env.GOOGLE_API_KEY
  }
}

client GenerateFinalReport {
  provider google-ai
  retry_policy TestSafely
  options {
    model "gemini-2.0-flash-lite"
    api_key env.GOOGLE_API_KEY
  }
}


client CustomGPT4o {
  provider openai
  options {
    model "gpt-4o"
    api_key env.OPENAI_API_KEY
  }
}

client CustomGPT4oMini {
  provider openai
  options {
    model "gpt-4o-mini"
    api_key env.OPENAI_API_KEY
  }
}

client CustomSonnet {
  provider anthropic
  options {
    model "claude-3-5-sonnet-20241022"
    api_key env.ANTHROPIC_API_KEY
  }
}


client CustomHaiku {
  provider anthropic
  retry_policy Constant
  options {
    model "claude-3-haiku-20240307"
    api_key env.ANTHROPIC_API_KEY
  }
}

// https://docs.boundaryml.com/docs/snippets/clients/round-robin
client CustomFast {
  provider round-robin
  options {
    // This will alternate between the two clients
    strategy [CustomGPT4oMini, CustomHaiku]
  }
}

// https://docs.boundaryml.com/docs/snippets/clients/fallback
client OpenaiFallback {
  provider fallback
  options {
    // This will try the clients in order until one succeeds
    strategy [CustomGPT4oMini, CustomGPT4oMini]
  }
}

// https://docs.boundaryml.com/docs/snippets/clients/retry
retry_policy Constant {
  max_retries 3
  // Strategy is optional
  strategy {
    type constant_delay
    delay_ms 200
  }
}

retry_policy TestSafely {
  max_retries 1
  strategy {
    type exponential_backoff
    delay_ms 200
    multiplier 1.5
    max_delay_ms 10000
  }
}



// For assessing research sufficiency and planning next steps
enum NextActionType {
  REFINE_QUERIES
  NEW_QUERIES
  DEEPER_ANALYSIS_OF_EXISTING_DOCS
  GENERATE_REPORT
  REQUEST_HUMAN_REVIEW
}

// 4. Assess Research Sufficiency and Plan Next Iteration
//    Purpose: Decides if more research is needed or if the agent can proceed to report generation.
function AssessResearchAndPlanNextSteps(
  original_legal_question: string,
  initial_queries_analysis: LegalQueryAnalysis,
  current_synthesis: OverallSynthesis?
) -> ResearchAssessment {
  client DecidesNextStep // Using a potentially faster/cheaper client for decision-making
  prompt #"
You are a managing legal researcher overseeing a research project. Your task is to review the progress, assess if the current information is sufficient to answer the original legal question, and plan the next steps. Follow these instructions carefully:

1. Review the original legal question:

    {{ original_legal_question }}


2. Review the initial query generation reasoning:

    1. Analyze Legal Question Summary: {{ initial_queries_analysis.reasoning.analyze_legal_question.summary | default("N/A") }}
    2. Consider Legal Principles Summary: {{ initial_queries_analysis.reasoning.consider_relevant_legal_principles.summary | default("N/A") }}
    3. Formulate Queries Strategy Summary: {{ initial_queries_analysis.reasoning.formulate_search_queries_strategy.summary | default("N/A") }}
    4. Specify Expected Info Strategy Summary: {{ initial_queries_analysis.reasoning.specify_expected_information_strategy.summary | default("N/A") }}
    5. Ensure Coverage Strategy Summary: {{ initial_queries_analysis.reasoning.ensure_comprehensive_coverage_strategy.summary | default("N/A") }}


3. Review the current synthesis of findings:

    {% if current_synthesis %}
      Key Synthesized Topics:
      {% for topic in current_synthesis.key_synthesized_topics %}
      {#
        Removed | truncate(150).
        If topic.synthesis is too long, the OverallSynthesis should ideally contain
        a briefer summary per topic, or your application code should prepare this.
        Alternatively, instruct the SynthesizeAllFindings function to make its topic.synthesis concise.
        For this assessment prompt, a very short excerpt or just the title might be enough.
      #}
      - {{ topic.topic_title }}: (Confidence: {{ topic.confidence_score }}/10)
        Summary: {{ topic.synthesis | default("No synthesis content.") }}
        Supporting Documents: {{ topic.supporting_document_ids | join(", ") }}
      {% else %}
      No topics synthesized yet.
      {% endfor %}
      Unanswered Aspects: {{ current_synthesis.unanswered_aspects | default(["None identified."]) | join(", ") }}
      Emerging Questions: {{ current_synthesis.emerging_questions | default(["None identified."]) | join(", ") }}
    {% else %}
      No synthesis has been performed yet. This is likely the first assessment after initial query generation or if previous searches yielded no relevant documents.
    {% endif %}


4. Assess Sufficiency:
MANDATORY: You MUST evaluate each criterion explicitly and state YES or NO for each:

a) Confidence Scores: Are they 7+ for key topics? Answer: [YES/NO]
b) Unanswered Aspects: Is the list empty or contains only very minor items? Answer: [YES/NO]
c) Emerging Questions: Is the list empty or contains only non-critical items? Answer: [YES/NO]
d) Actionable Information: Does the synthesis provide practical, actionable information to answer the core question? Answer: [YES/NO]

STRICT RULE: If ALL FOUR answers are "YES", you MUST set is_sufficient = true and next_action = "GENERATE_REPORT". 
DO NOT second-guess this rule. DO NOT add additional requirements beyond these four criteria.

CRITICAL SUFFICIENCY STANDARD: You are REQUIRED to follow ONLY the 4-step criteria above. Do NOT add additional legal analysis beyond those 4 criteria.

If the 4 criteria are met (confidence 7+, empty unanswered aspects, empty emerging questions, actionable info), the research IS SUFFICIENT regardless of what additional details you might personally want as a lawyer.

EXAMPLES OF SUFFICIENT SCENARIOS:
- Confidence scores 8-9/10 + empty unanswered_aspects + empty emerging_questions + core question answered = SUFFICIENT
- Basic legal rule provided + application guidance + high confidence = SUFFICIENT

FORBIDDEN: Do NOT require additional exceptions, edge cases, tolling doctrines, or comprehensive coverage if the 4 criteria are already met. Your job is assessment, not legal practice.

5. Summarize Assessment:
Briefly explain your reasoning for sufficiency/insufficiency. This will be used to populate the assessment_summary field.

6. Identify Gaps:
If not sufficient, list the specific information gaps. This will be used to populate the identified_gaps field.

7. Recommend Next Action:
Follow this MANDATORY decision tree step-by-step:

STEP A: Check for extensive research indicators
Look at the Initial Query Generation Reasoning summaries. Do they contain ANY of these phrases: "incomplete", "missing", "partial coverage", "current research incomplete", "need comprehensive", "homestead focus but missing", or similar?
- If YES → Go to STEP B
- If NO → Go to STEP C

STEP B: Extensive research detected - LIMITED OPTIONS ONLY
You may ONLY choose from:
- DEEPER_ANALYSIS_OF_EXISTING_DOCS (if Supporting Documents exist)
- REQUEST_HUMAN_REVIEW (if complexity suggests research limits reached)
- GENERATE_REPORT (if somehow sufficient despite gaps)
YOU ARE FORBIDDEN from choosing REFINE_QUERIES or NEW_QUERIES

STEP C: Normal decision process
First, evaluate the initial query effectiveness:

CHECK: Do the Initial Query Generation Reasoning summaries contain any of these ineffectiveness indicators?
- "too broad", "ineffective", "completely missed", "wrong approach", "fundamentally flawed", "inappropriate strategy"
- If YES → Choose NEW_QUERIES

CHECK: Do the Initial Query Generation Reasoning summaries suggest minor improvements needed?
- "need adjustment", "slightly off", "partially effective", "good direction but", "mostly correct but"
- If YES → Choose REFINE_QUERIES

If neither above applies, choose from:
- DEEPER_ANALYSIS_OF_EXISTING_DOCS: Choose this if Supporting Documents are listed AND any of these conditions: (1) confidence scores below 6/10, (2) synthesis mentions "surface-level" or similar phrases, (3) reasoning mentions "need detailed analysis", (4) extensive research has been conducted but gaps remain and documents exist for re-analysis. Do not choose this if the question involves complexity requiring specialized expertise.
- GENERATE_REPORT: If the information gathered is sufficient.
- REQUEST_HUMAN_REVIEW: Prioritize this for complex multi-jurisdictional issues, conflicting legal frameworks, strategic business decisions, or when initial reasoning indicates "complexity beyond automated analysis". Also choose this when extensive research has been conducted but significant gaps remain and complexity suggests automated research has reached its limits.

8. Provide Conditional Details:
- If next_action is REFINE_QUERIES or NEW_QUERIES, provide a list of SearchQueryItem objects for suggested_queries_for_refinement.
- If next_action is DEEPER_ANALYSIS_OF_EXISTING_DOCS, provide specific document IDs from the "Supporting Documents" for document_ids_for_deeper_analysis.
- For other next_action types, omit these fields.

9. Reasoning:
Provide your detailed thought process for this assessment and plan. Explain why you chose the next action and how you identified gaps or formulated new queries/plans. Use the ReasoningStep structure for each of these steps:
a) analyze_legal_question
b) consider_relevant_legal_principles
c) formulate_search_queries_strategy
d) specify_expected_information_strategy
e) ensure_comprehensive_coverage_strategy

10. Output Format:
Provide your final output in JSON format using the following schema:

{{ ctx.output_format }}

Your final output should consist of only the JSON object on the schema described above. Do not include any additional text, explanations, or formatting outside of this JSON structure.
  "#
}



// ----- Comprehensive Test Cases for AssessResearchAndPlanNextSteps -----

test AssessmentWithNoSynthesis {
  functions [AssessResearchAndPlanNextSteps]
  args {
    original_legal_question "What is the statute of limitations for personal injury in California?"
    initial_queries_analysis {
      reasoning {
        analyze_legal_question { summary "Initial analysis of personal injury limitation question" }
        consider_relevant_legal_principles { summary "Identified statute of limitations principles" }
        formulate_search_queries_strategy { summary "Strategy for statutory and case law research" }
        specify_expected_information_strategy { summary "Expected California-specific limitation periods" }
        ensure_comprehensive_coverage_strategy { summary "Comprehensive coverage of limitation rules" }
      }
      search_queries [
        {
          query_string "California personal injury statute of limitations CCP 335.1"
          expected_information ["Statutory limitation period", "Accrual rules", "Discovery rule exceptions"]
        }
      ]
    }
    current_synthesis none
  }
  // First pass assessment should identify need for research
  @@assert( {{ this.is_sufficient == false }} )
  @@assert( {{ (this.assessment_summary or "") | length > 10 }} )
  @@assert( {{ this.next_action in ["NEW_QUERIES", "REFINE_QUERIES"] }} )
  // Should provide suggested queries for first research
  @@assert( {{ this.suggested_queries_for_refinement != none and ((this.suggested_queries_for_refinement or []) | length > 0) }} )
  // document_ids_for_deeper_analysis should be none for NEW_QUERIES action
  @@assert( {{ this.reasoning.analyze_legal_question.summary | length > 0 }} )
  @@assert( {{ this.reasoning.consider_relevant_legal_principles.summary | length > 0 }} )
  @@assert( {{ this.reasoning.formulate_search_queries_strategy.summary | length > 0 }} )
}

test AssessmentSufficientForReport {
  functions [AssessResearchAndPlanNextSteps]
  args {
    original_legal_question "What is the statute of limitations for personal injury in California?"
    initial_queries_analysis {
      reasoning {
        analyze_legal_question { summary "Comprehensive analysis of personal injury limitation periods" }
        consider_relevant_legal_principles { summary "Accrual rules and discovery doctrine" }
        formulate_search_queries_strategy { summary "Statutory and case law research" }
        specify_expected_information_strategy { summary "Time limits and exceptions" }
        ensure_comprehensive_coverage_strategy { summary "Multiple sources and perspectives" }
      }
      search_queries [
        {
          query_string "California personal injury statute of limitations CCP 335.1"
          expected_information ["Statutory limitation period", "Accrual rules"]
        },
        {
          query_string "discovery rule personal injury California accrual"
          expected_information ["Discovery rule application", "Latent injury cases"]
        }
      ]
    }
    current_synthesis {
      key_synthesized_topics [
        {
          topic_title "California Personal Injury Statute of Limitations"
          synthesis "California Code of Civil Procedure § 335.1 establishes a 2-year statute of limitations for personal injury actions. The limitation period begins when the cause of action accrues, which is generally when the injury occurs. However, the discovery rule applies in cases where the injury is not immediately apparent, starting the clock when the plaintiff discovers or reasonably should have discovered the injury and its cause."
          confidence_score 9
          supporting_document_ids ["statute_335", "case_discovery_rule", "appellate_interpretation"]
        },
        {
          topic_title "Discovery Rule Application"
          synthesis "Courts apply the discovery rule to delay accrual of the statute of limitations until the plaintiff knows or should know of the injury and its wrongful cause. This rule is particularly important in medical malpractice, toxic exposure, and latent injury cases."
          confidence_score 8
          supporting_document_ids ["case_discovery_rule", "medical_malpractice_cases", "toxic_exposure_precedent"]
        }
      ]
      unanswered_aspects []
      emerging_questions []
      reasoning {
        analyze_legal_question { summary "Comprehensive analysis of limitation periods" }
        consider_relevant_legal_principles { summary "Accrual rules and discovery doctrine" }
        formulate_search_queries_strategy { summary "Statutory and case law research" }
        specify_expected_information_strategy { summary "Time limits and exceptions" }
        ensure_comprehensive_coverage_strategy { summary "Multiple sources and perspectives" }
      }
    }
  }
  @@assert( {{ this.is_sufficient == true }} )
  @@assert( {{ this.next_action == "GENERATE_REPORT" }} )
  @@assert( {{ (this.assessment_summary or "") | length > 10 }} )
  // Should not provide refinement suggestions when sufficient
  @@assert( {{ not this.suggested_queries_for_refinement }} )
  // document_ids_for_deeper_analysis should be none for GENERATE_REPORT action
  // Assessment should reference the synthesis quality
  @@assert( {{ ("sufficient" in ((this.assessment_summary or "") | lower)) or ("comprehensive" in ((this.assessment_summary or "") | lower)) or ("adequate" in ((this.assessment_summary or "") | lower)) }} )
}

test AssessmentNeedsRefinement {
  functions [AssessResearchAndPlanNextSteps]
  args {
    original_legal_question "What are the requirements for adverse possession in Texas?"
    initial_queries_analysis {
      reasoning {
        analyze_legal_question { summary "General adverse possession principles identified" }
        consider_relevant_legal_principles { summary "Common law elements found" }
        formulate_search_queries_strategy { summary "Broad search conducted" }
        specify_expected_information_strategy { summary "Texas-specific information lacking" }
        ensure_comprehensive_coverage_strategy { summary "Need jurisdiction-specific research" }
      }
      search_queries [
        {
          query_string "adverse possession elements requirements"
          expected_information ["General elements", "Common law principles"]
        },
        {
          query_string "adverse possession statute of limitations"
          expected_information ["Time periods", "Statutory requirements"]
        }
      ]
    }
    current_synthesis {
      key_synthesized_topics [
        {
          topic_title "Basic Adverse Possession Elements"
          synthesis "Adverse possession generally requires open, notorious, exclusive, and continuous possession for a statutory period. However, specific requirements may vary by jurisdiction."
          confidence_score 4
          supporting_document_ids ["general_law_overview"]
        }
      ]
      unanswered_aspects ["Texas-specific statutory requirements", "Required time period in Texas", "Good faith vs. bad faith requirements", "Tacking provisions", "Payment of taxes requirement"]
      emerging_questions ["What is the exact statutory period in Texas?", "Are there different rules for rural vs. urban property?", "What constitutes 'open and notorious' use in Texas?"]
      reasoning {
        analyze_legal_question { summary "General adverse possession principles identified" }
        consider_relevant_legal_principles { summary "Common law elements found" }
        formulate_search_queries_strategy { summary "Broad search conducted" }
        specify_expected_information_strategy { summary "Texas-specific information lacking" }
        ensure_comprehensive_coverage_strategy { summary "Need jurisdiction-specific research" }
      }
    }
  }
  @@assert( {{ this.is_sufficient == false }} )
  @@assert( {{ this.next_action == "REFINE_QUERIES" }} )
  @@assert( {{ (this.assessment_summary or "") | length > 10 }} )
  // Should provide Texas-specific refinement suggestions
  @@assert( {{ this.suggested_queries_for_refinement != none and ((this.suggested_queries_for_refinement or []) | length > 0) }} )
  @@assert( {{ ("texas" in (((this.suggested_queries_for_refinement or []) | join(" ")) | lower)) }} )
  // document_ids_for_deeper_analysis should be none for REFINE_QUERIES action
  // Assessment should identify the gaps
  @@assert( {{ ("texas" in ((this.assessment_summary or "") | lower)) or ("specific" in ((this.assessment_summary or "") | lower)) or ("jurisdiction" in ((this.assessment_summary or "") | lower)) }} )
}

