                              {detail}

                          ))}

                      )}


                ))
              ) : (


                  No detailed reasoning steps available.

              )}






              Sources Used



              {sourcesUsed.length > 0 ? (
                sourcesUsed.map((source, index) => (





                        {source.docId}

