              const isComplete = getSectionCompletion(sectionTitle)
              return (





                    {sectionTitle}


              )
            })}






            {report.executiveSummary && (
              <>

Executive Summary


                  {report.executiveSummary}


              </>
            )}

            {report.sections
              .filter(
                section =>
                  section.title !== "Executive Summary" &&
                  section.title !== "Conclusion"
              )
              .map((section, index) => (



{section.title}


                    {section.content}



              ))}

            {report.conclusion && (
